window.SOMA={"asanalar":[{"n":1,"bolum":1,"ad":"山のポーズ（ターダーサナ）","aile":"立位","seviye":"初級","yogunluk":[1,2,3],"calisan":["大腿四頭筋","腹横筋","脊柱起立筋"],"dengeleyen":["中殿筋・小殿筋","腓腹筋・ヒラメ筋","骨盤底筋群"],"uzayan":[],"ozet":"すべての立位のポーズの土台となるアライメントを教えます。足裏から頭頂までまっすぐに伸びる、バランスのとれた縦のラインです。クラスでは姿勢への気づきと、呼吸で心身を整えるための出発点になります。","asamalar":{"giris":"足を腰幅で平行に置き、体重をかかとと母趾球・小趾球に均等にのせます。息を吸いながら背骨を頭頂から上へ伸ばし、息を吐きながら肩を耳から遠ざけます。","kalis":"骨盤はニュートラルに保ち、尾骨は床の方向へ伸ばします。肋骨は前に突き出さず、あごは床と平行にします。鼻から穏やかに呼吸しながら5〜8呼吸キープします。","cikis":"息を吐きながら膝を軽くゆるめ、体重を一度前後に移してから中心に戻し、次のポーズへ移ります。"},"hata":{"ne":"膝を後ろにロックして骨盤を前に押し出してしまう。","neden":"大腿四頭筋が過度に収縮すると膝が過伸展し、骨盤が前に移動して腰の反りが強くなります。","yonlendirme":"膝はやわらかく、尾骨は床へ伸ばします。"},"soylenecekler":["足裏の四隅で均等に床を押しましょう。","頭のてっぺんで天井に向かって伸びていきましょう。","呼吸で肋骨を横に広げ、肩は下げたままにしてください。"],"eller":{"nereye":"片手を仙骨の上縁に、もう片方の手を胸骨のすぐ下に、手のひらを平らにして当てます。","nasil":"仙骨の手は軽く下へ、胸の手は上へ方向を示し、背骨が長く伸びる感覚を伝えます。押さずに、方向を示すだけにしてください。","ne_zaman_degil":"生徒の同意が得られていない場合や、目を閉じている生徒に声をかけずに近づくことになる場合は触れないでください。"},"kolay":"背中を壁につけ、かかと・お尻・肩甲骨が壁に触れている感覚を確かめてもらいます。","zor":"目を閉じる、または両腕を頭上に伸ばした状態で、同じアライメントとバランスを保ちます。","dikkat":"めまいを訴える生徒は目を開けたままにし、壁の近くで行います。足・膝・腰に痛みがある場合は、医師や理学療法士に相談するよう勧めてください。","s":6,"fig":true},{"n":2,"bolum":1,"ad":"椅子のポーズ（ウトゥカターサナ）","aile":"立位","seviye":"初級","yogunluk":[3,5,7],"calisan":["大腿四頭筋","大殿筋","脊柱起立筋","三角筋"],"dengeleyen":["腹横筋","前脛骨筋","内転筋群"],"uzayan":["腓腹筋・ヒラメ筋","広背筋"],"ozet":"お尻を後ろに引いて座る動きと、脚の力を背骨の長さと組み合わせることを教えます。フローのウォームアップや持久力のパートに最適です。","asamalar":{"giris":"足をそろえるか腰幅にして立ち、息を吐きながら膝を曲げ、後ろにある椅子に座るようにお尻を後ろへ引きます。息を吸いながら両腕を耳の横で上に伸ばします。","kalis":"上体はわずかに前傾しますが、背骨は長く保ちます。肋骨は引き込み、尾骨は下へ伸ばします。体重はかかとにのせ、5呼吸キープします。","cikis":"息を吸いながら足で床を押して膝を伸ばし、山のポーズへ戻ります。息を吐きながら腕を下ろします。"},"hata":{"ne":"膝が前に出て、かかとが浮いてしまう。","neden":"股関節の屈曲や足首の可動域が限られていると、体はお尻を後ろに引く代わりに膝を前に押し出してバランスをとろうとします。","yonlendirme":"後ろに座り、体重はかかとへ。"},"soylenecekler":["椅子に座るように、お尻を後ろへ引きましょう。","足の指が動かせるくらい、体重はかかとにのせてください。","腕を伸ばしながら、肩は耳から遠ざけましょう。"],"eller":{"nereye":"両手を腸骨稜の上縁に、横から当てます。","nasil":"お尻を軽く後ろと下へ導き、座る感覚を伝えます。下に押し込まず、方向を示すだけにしてください。","ne_zaman_degil":"膝の痛みを訴えている場合、妊娠中の生徒、または同意を得ていない場合は触れないでください。"},"kolay":"手を腰に置くか胸の前で合わせます。曲げる深さを浅くするか、背中を壁につけて行います。","zor":"かかとを床から浮かせて母趾球で同じ深さを保つか、手のひらの間にブロックをはさみます。","dikkat":"膝や足首に不安がある場合は浅く曲げます。肩に詰まり感がある場合は、腕を肩幅より広く開きます。痛みが続く場合は、医師や理学療法士に相談するよう勧めてください。","s":7,"fig":true},{"n":3,"bolum":1,"ad":"戦士のポーズⅠ（ヴィーラバドラーサナⅠ）","aile":"立位","seviye":"初級","yogunluk":[3,5,7],"calisan":["大腿四頭筋","大殿筋","三角筋"],"dengeleyen":["腹横筋","中殿筋・小殿筋","腹斜筋"],"uzayan":["腸腰筋","腓腹筋・ヒラメ筋"],"ozet":"腰を正面に向けて、前脚で力を、後ろ脚で伸びを生み出すことを教えます。立位フローにおける股関節アライメントの基本レッスンです。","asamalar":{"giris":"片足を大きく後ろへ引き、後ろ足を約45度外に向け、左右の腰骨を正面に向けます。息を吐きながら前膝を足首の真上まで曲げ、息を吸いながら両腕を上に伸ばします。","kalis":"骨盤は正面を向き、肋骨は前に突き出しません。後ろのかかとは床を押し、後ろ脚は長く保ちます。5呼吸キープします。","cikis":"息を吸いながら前脚を伸ばし、息を吐きながら腕を下ろし、足をそろえて反対側へ移ります。"},"hata":{"ne":"後ろ側の腰が後ろに残り、骨盤が横に開いてしまう。","neden":"後ろ脚の股関節屈筋群やふくらはぎが硬いと、骨盤が正面を向けず横に逃げてしまいます。","yonlendirme":"後ろの腰を前へ、左右の腰骨を同じ方向へ。"},"soylenecekler":["左右の腰骨を、ヘッドライトのように正面に向けましょう。","後ろのかかとで床を後ろへ押してください。","肋骨を引き込み、腕を上に伸ばしながら腰は長く保ちましょう。"],"eller":{"nereye":"片手を後ろ側の腰の外側（大転子のあたり）に、もう片方の手を前側の腰骨に当てます。","nasil":"後ろの腰をやさしく前へ、前の腰を軽く後ろへ導いて骨盤を中央に整えます。回旋を無理に促さないでください。","ne_zaman_degil":"股関節や膝に痛みがある場合、妊娠中の生徒、または触れられることを望まない場合は控えてください。"},"kolay":"スタンスを短くするか、足をもう少し左右に開きます（線路の上に立つように）。手は腰に置いたままにします。","zor":"頭上で両手を合わせて視線を親指へ上げるか、前の太ももが床と平行になるまで腰を下ろします。","dikkat":"腰に不安がある場合は、腕を肩幅に保ち、後屈を加えないようにします。痛みを訴えた場合は、医師や理学療法士に相談するよう勧めてください。","s":8,"fig":true},{"n":4,"bolum":1,"ad":"戦士のポーズⅡ（ヴィーラバドラーサナⅡ）","aile":"立位","seviye":"初級","yogunluk":[3,5,7],"calisan":["大腿四頭筋","中殿筋・小殿筋","三角筋"],"dengeleyen":["内転筋群","腹横筋","腹斜筋"],"uzayan":["内転筋群"],"ozet":"股関節を横に開きながら前膝を足と同じラインに保ち、両腕を床と平行に伸ばすことを教えます。立位のシークエンスで持久力と集中力を養う基本のポーズです。","asamalar":{"giris":"足を大きく開き、前足を90度外に、後ろ足を少し内側に向けます。息を吸いながら両腕を肩の高さで左右に伸ばし、息を吐きながら前膝を足首の真上まで曲げます。","kalis":"骨盤と胸は横に開いたまま、上体は両脚の真ん中でまっすぐに保ちます。前膝は人差し指（第2趾）のラインにそろえます。視線は前の手の指先に向け、5〜8呼吸キープします。","cikis":"息を吸いながら前脚を伸ばし、息を吐きながら腕を下ろし、足を平行に戻して反対側へ移ります。"},"hata":{"ne":"前膝が内側へ、足の親指より内側に入ってしまう。","neden":"中殿筋や股関節の外旋筋群が疲れると、太ももが内旋し、膝が正中線の内側へ崩れます。","yonlendirme":"膝は人差し指（第2趾）の方向へ。"},"soylenecekler":["前の膝を、小指の方向へ少し外に開きましょう。","上体が前に流れないよう、両脚のちょうど真ん中に置いてください。","指先で左右の壁に向かって伸び、肩は下げましょう。"],"eller":{"nereye":"片手を前膝の外側に、もう片方の手を同じ側のお尻の外側に当てます。","nasil":"膝を軽く外へ、第2趾のラインに導きます。お尻はやさしく下と後ろへ方向を示します。膝を内側や下へ押すことは決してしないでください。","ne_zaman_degil":"膝の痛みがある場合、人工股関節の生徒、または生徒の同意がない場合は触れないでください。"},"kolay":"スタンスを短くし、前膝の曲げを浅くします。腕が疲れたら手を腰に置きます。","zor":"前の太ももを床と平行まで下ろして10呼吸キープするか、腕を固定したまま呼吸に合わせて膝の曲げ伸ばしを行います。","dikkat":"肩に不調がある場合は腕を低めに保ちます。膝や股関節に痛みがある場合は浅く曲げ、医師や理学療法士に相談するよう勧めてください。","s":9,"fig":true},{"n":5,"bolum":1,"ad":"逆転の戦士のポーズ（ヴィパリータ・ヴィーラバドラーサナ）","aile":"立位","seviye":"初級","yogunluk":[3,5,6],"calisan":["大腿四頭筋","腹斜筋","中殿筋・小殿筋"],"dengeleyen":["内転筋群","腹横筋","腰方形筋"],"uzayan":["広背筋","腹斜筋","腰方形筋"],"ozet":"戦士のポーズⅡの脚の土台を保ったまま、体側のラインを伸ばすことを教えます。フローの中で、呼吸を体側の肋骨へ導くために使います。","asamalar":{"giris":"戦士のポーズⅡから始めます。息を吸いながら前の手のひらを天井に向けて腕を上と後ろへ伸ばし、後ろの手は後ろの太ももに軽く添えます。","kalis":"前膝は曲げたまま足首の上に保ち、骨盤は低く安定させます。体側の腰を縮めずにアーチを描きます。3〜5呼吸キープし、吸う息ごとに上側の肋骨を広げます。","cikis":"息を吐きながら上体を中央に戻して戦士のポーズⅡに戻るか、両手を床に下ろしてフローを続けます。"},"hata":{"ne":"後ろに伸びるときに前膝を伸ばしてしまい、体重を後ろの手に預けてしまう。","neden":"体側を開こうとするあまり、脚の土台が抜けてバランスを後ろの腕に任せてしまいます。","yonlendirme":"前膝は曲げたまま、後ろの手は触れるだけ。"},"soylenecekler":["前の膝は曲げたまま、腰は低く保ちましょう。","上の指先で、まず天井へ、それから後ろへ伸びていきましょう。","後ろの手は脚に触れるだけにして、体重をのせないでください。"],"eller":{"nereye":"片手を前膝の外側に、もう片方の手を伸ばしている腕の側の体側の肋骨に当てます。","nasil":"膝が第2趾のラインに保たれるよう軽く外へ導き、肋骨には上へ伸びる方向をやさしく示します。後ろへ引っぱらないでください。","ne_zaman_degil":"腰や首の痛みを訴えている場合、めまいがある場合、または同意がない場合は触れないでください。"},"kolay":"後ろの手を腰に置き、後ろではなく上にだけ伸びます。","zor":"後ろの腕を腰に回してバインドするか、視線を伸ばした手に上げて5呼吸キープします。","dikkat":"首に不安がある場合は、視線を床または横に保ちます。腰に詰まり感がある場合は伸びを小さくし、痛みが続く場合は医師や理学療法士に相談するよう勧めてください。","s":10,"fig":true},{"n":6,"bolum":1,"ad":"三角のポーズ（トリコーナーサナ）","aile":"立位","seviye":"初級","yogunluk":[2,4,6],"calisan":["腹斜筋","腰方形筋","大腿四頭筋"],"dengeleyen":["ハムストリングス","腹横筋","中殿筋・小殿筋"],"uzayan":["ハムストリングス","内転筋群"],"ozet":"脚を長く保ったまま、股関節から上体を横へ伸ばすことを教えます。深さよりも、体側の両側を均等に伸ばすことのもっとも明確な例です。","asamalar":{"giris":"足を大きく開き、前足を90度外に向けます。息を吸いながら両腕を左右に伸ばし、息を吐きながら上体を前脚の方向へ伸ばし、前の手をすね、ブロック、または床に置きます。","kalis":"体側の両側を同じ長さに保ち、胸は横に開きます。前膝はロックしません。上の腕は天井へ伸ばし、5呼吸キープします。","cikis":"息を吸いながら後ろのかかとで床を押し、上体をひとかたまりのまま起こします。息を吐きながら腕を下ろし、反対側へ移ります。"},"hata":{"ne":"床に届かせようとして、下側の体側を押しつぶしてしまう。","neden":"ハムストリングスが硬いと、動きが股関節からではなく腰椎の側屈で代償されます。","yonlendirme":"深くではなく、長く。"},"soylenecekler":["まず前の手で前方へ伸び、それから下りていきましょう。","下側の体側も、上側と同じくらい長く保ちましょう。","胸を天井に向けて開き、前の膝は少しやわらかくしてください。"],"eller":{"nereye":"片手を後ろ側の腰の上に、もう片方の手を上側の肩甲骨に当てます。","nasil":"腰を軽く後ろへ、肩甲骨は胸が開く方向へやさしく導きます。上体を下へ押さないでください。","ne_zaman_degil":"首や腰に痛みがある場合、生徒がふらつきを感じている瞬間、または同意がない場合は触れないでください。"},"kolay":"前の手を高めのブロックかすねの上部に置き、視線は床に向けたままにします。","zor":"上の腕を耳の横から前方へ伸ばすか、前の手を足の後ろの床に下ろして体側のラインを保ちます。","dikkat":"首に不安がある場合は、頭を床または前に向けます。膝が過伸展しやすい場合は、前膝を軽く曲げたままにします。痛みがある場合は、医師や理学療法士に相談するよう勧めてください。","s":11,"fig":true},{"n":7,"bolum":1,"ad":"体側を伸ばすポーズ（ウッティタ・パールシュヴァコーナーサナ）","aile":"立位","seviye":"初級","yogunluk":[3,5,7],"calisan":["大腿四頭筋","腹斜筋","中殿筋・小殿筋"],"dengeleyen":["内転筋群","前鋸筋","腹横筋"],"uzayan":["広背筋","内転筋群"],"ozet":"戦士のポーズⅡの脚の土台の上で、かかとから指先までひと続きの斜めのラインをつくることを教えます。体側の伸びと脚の力を同時に養います。","asamalar":{"giris":"戦士のポーズⅡから、息を吐きながら上体を前脚の方へ伸ばし、前の前腕を太ももに置くか、手をブロックに置きます。息を吸いながら上の腕を耳の横から斜め前方へ伸ばします。","kalis":"前膝は足首の上に保ち、骨盤は横に開き、胸は天井へ向けます。後ろのかかとから上の手までまっすぐなラインができます。5呼吸キープします。","cikis":"息を吸いながら後ろ足で床を押して上体を起こし、戦士のポーズⅡに戻ります。息を吐きながら脚を伸ばします。"},"hata":{"ne":"前の腕を膝にもたれかけ、上体が前へ崩れてしまう。","neden":"上体の重さを腕に預けると前鋸筋と腹斜筋が働かなくなり、胸が床の方へ閉じてしまいます。","yonlendirme":"前腕は膝で休むだけ、胸は天井へ開きます。"},"soylenecekler":["後ろのかかとから指先まで、一本のラインを感じましょう。","前の腕は太ももに体重をかけず、触れるだけにしてください。","上の肩を後ろへ回し、胸を天井に向けて開きましょう。"],"eller":{"nereye":"片手を上側のお尻の横に、もう片方の手を伸ばしている腕のひじのすぐ下に当てます。","nasil":"お尻を軽く後ろへ導き、腕を斜めの方向へ伸ばしてラインを感じてもらいます。回旋を無理に促さないでください。","ne_zaman_degil":"肩の不安定さを訴えている場合、妊娠中の生徒、同意がない場合、または膝の痛みがある場合は触れないでください。"},"kolay":"前の前腕を太ももに置き、上の手は腰に置きます。","zor":"前の手を足の外側の床に下ろすか、上の腕を脚の下に回してバインドします。","dikkat":"肩に痛みがある場合は、上の手を腰に置きます。そけい部や膝に不安がある場合はスタンスを短くします。痛みが続く場合は、医師や理学療法士に相談するよう勧めてください。","s":12,"fig":true},{"n":8,"bolum":1,"ad":"ピラミッドのポーズ（パールシュヴォッターナーサナ）","aile":"立位","seviye":"中級","yogunluk":[3,5,7],"calisan":["大腿四頭筋","脊柱起立筋","中殿筋・小殿筋"],"dengeleyen":["腹横筋","内転筋群","前脛骨筋"],"uzayan":["ハムストリングス","腓腹筋・ヒラメ筋"],"ozet":"腰を正面にそろえたまま前脚の上に股関節から折りたたみ、背中を長く保つことを教えます。ハムストリングスの伸びと骨盤のコントロールを同時に養います。","asamalar":{"giris":"短めのスタンスで片足を後ろに引き、後ろ足を少し外に向け、両方の腰を正面に向けます。息を吸いながら背骨を伸ばし、息を吐きながら股関節から前脚の上へ前屈します。","kalis":"骨盤は正面にそろえ、体重は両足に均等にのせます。背骨はまず長く伸ばし、それから楽に折りたたみます。手はブロックか床に置き、5呼吸キープします。","cikis":"息を吸いながら背中をまっすぐに保って手を腰に移し、上体を起こします。息を吐きながら足をそろえ、反対側へ移ります。"},"hata":{"ne":"額を膝につけようとして背中を丸めてしまう。","neden":"ハムストリングスが硬いと骨盤が前傾できず、動きが背骨の屈曲で代償されます。","yonlendirme":"胸は前へ伸び、額はそのあとで。"},"soylenecekler":["胸を前の足に向かって伸ばしていきましょう。","前側の腰を少し後ろへ引き、左右の腰の高さをそろえましょう。","前の膝はロックせず、少しやわらかく保ってください。"],"eller":{"nereye":"両手を左右の腰骨の横に当てます。","nasil":"前側の腰を軽く後ろへ、後ろ側の腰を前へ導き、骨盤が正面にそろう感覚を伝えます。上体を下へ押さないでください。","ne_zaman_degil":"ハムストリングスの張りや痛みを訴えている場合、腰の痛みがある場合、または同意がない場合は触れないでください。"},"kolay":"前足の両側に置いた高めのブロックに手を置き、前膝は曲げたままにします。","zor":"背中で手を逆合掌に組んでから前屈します。","dikkat":"腰に不安がある場合は、半前屈（背中が床と平行）で止めます。後ろ脚や太ももの裏に痛みがある場合は、医師や理学療法士に相談するよう勧めてください。","s":13,"fig":true},{"n":9,"bolum":1,"ad":"ねじった三角のポーズ（パリヴリッタ・トリコーナーサナ）","aile":"ねじり","seviye":"中級","yogunluk":[4,6,7],"calisan":["腹斜筋","多裂筋","大腿四頭筋"],"dengeleyen":["中殿筋・小殿筋","腹横筋","内転筋群"],"uzayan":["ハムストリングス"],"ozet":"安定して水平な骨盤の上で、背骨を伸ばして胸郭からねじることを教えます。ねじり、バランス、ハムストリングスの伸びを同時に必要とするポーズです。","asamalar":{"giris":"短めのスタンスで腰を正面に向けます。息を吸いながら背骨を伸ばし、息を吐きながら上体を前へ伸ばして、反対側の手をブロック、または前足の内側か外側に置きます。","kalis":"骨盤は水平に保ち、背骨は長い軸を中心に回旋します。上の腕は天井へ伸ばします。5呼吸キープし、吸う息で伸びて、吐く息でねじります。","cikis":"息を吐きながら上の手を腰に移し、息を吸いながら上体をひとかたまりのまま起こして、反対側へ移ります。"},"hata":{"ne":"ねじりを深めようとして腰が横にずれてしまう。","neden":"ねじりを胸郭ではなく骨盤から行おうとすると中殿筋のコントロールが失われ、腰が外へ押し出されます。","yonlendirme":"まず腰をそろえ、それからねじります。"},"soylenecekler":["腰を中央にそろえましょう。前の腰は後ろへ、後ろの腰は前へ。","まず頭のてっぺんへ向かって伸び、それからねじりましょう。","ねじりはおへその下からではなく、胸から始めてください。"],"eller":{"nereye":"片手を外へずれている側の腰の横に、もう片方の手を上側の肩甲骨に当てます。","nasil":"腰をやさしく正中線の方向へ導き、肩甲骨にはねじる方向を示すだけにします。回してねじりを深めないでください。","ne_zaman_degil":"腰や仙腸関節の痛みがある場合、妊娠中、椎間板の問題を申告している生徒、または同意がない場合は触れないでください。"},"kolay":"下の手を高めのブロックに置き、上の手は腰に置いたまま、スタンスを広くします。","zor":"下の手を前足の外側の床に置き、視線を上の手に上げます。","dikkat":"妊娠中は、この閉じたねじりの代わりに開いたねじりのバリエーションを選びます。腰や仙腸関節のあたりに痛みがある場合は、医師や理学療法士に相談するよう勧めてください。","s":14,"fig":true},{"n":10,"bolum":1,"ad":"開脚前屈（プラサーリタ・パードッターナーサナ）","aile":"前屈","seviye":"初級","yogunluk":[2,4,6],"calisan":["大腿四頭筋","脊柱起立筋"],"dengeleyen":["内転筋群","中殿筋・小殿筋","腹横筋"],"uzayan":["ハムストリングス","内転筋群","腓腹筋・ヒラメ筋"],"ozet":"広い土台の上で股関節から折りたたみ、頭を心臓より低い位置へ安全に下ろすことを教えます。軽い逆転の効果があり、クラスのクールダウンへの橋渡しになります。","asamalar":{"giris":"足を脚一本分ほどの幅に開き、足の外側を平行に保ちます。息を吸いながら背骨を伸ばし、息を吐きながら股関節から前に折りたたみ、両手を肩の下の床に置きます。","kalis":"腰は足首の真上に保ち、体重は母趾球の方へ少し移します。背骨は長く、首はリラックスさせます。5〜8呼吸キープします。","cikis":"両手を腰に移し、息を吸いながら背中をまっすぐに保って上体を起こし、足を少しずつそろえます。"},"hata":{"ne":"体重をかかとにかけ、頭を無理に床へつけようとする。","neden":"腰が後ろへ引けるとハムストリングスが緊張し、体は首や背中で深さを求めようとします。","yonlendirme":"体重は母趾球に、腰は足首の真上に。"},"soylenecekler":["腰を足首の真上に保ちましょう。","足の外側で床を押し、土踏まずは引き上げてください。","頭の力を抜いて、首の後ろを長くしましょう。"],"eller":{"nereye":"両手を左右の腰骨の上縁に、後ろから当てます。","nasil":"腰を軽く前へ、足首の真上に導きます。下へ押さないでください。","ne_zaman_degil":"高血圧、緑内障、めまいを訴える生徒や、同意がない場合は触れないでください。"},"kolay":"両手をブロックに置いて背中を床と平行に保ち、膝を軽く曲げます。","zor":"背中で両手を組み、腕を頭の上の方向へ伸ばします。","dikkat":"血圧、眼圧、めまいの不安を訴える生徒は、頭を心臓より高い位置に保ちます。腰に痛みがある場合は、医師や理学療法士に相談するよう勧めてください。","s":15,"fig":true},{"n":11,"bolum":1,"ad":"ハイランジ","aile":"立位","seviye":"初級","yogunluk":[3,5,7],"calisan":["大腿四頭筋","大殿筋","三角筋"],"dengeleyen":["中殿筋・小殿筋","腹横筋","内転筋群"],"uzayan":["腸腰筋"],"ozet":"後ろのかかとを浮かせた狭い土台の上で、力とバランスをつくることを教えます。後ろ脚の股関節の前側を伸ばし、前脚の持久力を養います。","asamalar":{"giris":"下向きの犬のポーズから片足を両手の間に踏み出し、後ろのかかとは浮かせたままにします。息を吸いながら上体と両腕を上へ起こします。","kalis":"前膝は足首の上、後ろ脚は長くアクティブに保ちます。骨盤は正面を向き、肋骨は引き込んだままにします。5呼吸キープします。","cikis":"息を吐きながら両手を前足の両側に下ろし、足を後ろへ引いて下向きの犬のポーズに戻ります。"},"hata":{"ne":"後ろ膝をロックして腰の反りを強めてしまう。","neden":"後ろ脚の股関節の前にある腸腰筋が硬いと、骨盤が前傾して腰のカーブが大きくなります。","yonlendirme":"後ろのかかとは後ろへ、肋骨は内へ。"},"soylenecekler":["後ろのかかとで壁を押すように伸びましょう。","肋骨を引き込み、腰は長く保ってください。","前の膝は足首の真上に保ちましょう。"],"eller":{"nereye":"片手を仙骨に、もう片方の手を下部肋骨の前側に当てます。","nasil":"仙骨を軽く下へ、肋骨を内へ導き、ニュートラルな骨盤を感じてもらいます。体重をかけないでください。","ne_zaman_degil":"膝の痛みがある場合、妊娠後期、または同意がない場合は触れないでください。"},"kolay":"後ろの膝を床に下ろすか、両手を前の太ももに置きます。","zor":"腕を上げたまま前膝を深めるか、呼吸に合わせて後ろ膝の曲げ伸ばしを行います。","dikkat":"ふらつきを感じる生徒は壁のそばで行います。膝や股関節に痛みがある場合は、医師や理学療法士に相談するよう勧めてください。","s":16,"fig":true},{"n":12,"bolum":1,"ad":"ローランジ（アンジャネーヤーサナ）","aile":"股関節ひらき","seviye":"初級","yogunluk":[2,4,6],"calisan":["大腿四頭筋","大殿筋","三角筋"],"dengeleyen":["腹横筋","中殿筋・小殿筋"],"uzayan":["腸腰筋","大腿四頭筋"],"ozet":"後ろの膝を床につけて、股関節の前側をコントロールしながら開くことを教えます。長時間座ったあとに股関節屈筋群をゆるめるため、クラスでよく使われます。","asamalar":{"giris":"片足を両手の間に踏み出し、後ろの膝を床に下ろして足の甲を床に置きます。息を吸いながら上体を起こし、両腕を上に伸ばします。","kalis":"腰はわずかに前へ移動しますが、骨盤はニュートラルに保ちます。尾骨は下へ伸ばし、肋骨は引き込みます。5〜8呼吸キープします。","cikis":"息を吐きながら両手を床に下ろし、腰を後ろへ引いて前脚を戻します。"},"hata":{"ne":"腰を前に落とし、腰の反りを強めてしまう。","neden":"股関節屈筋群が伸びないまま深さを求めると骨盤が前傾し、腰のカーブが伸びの代わりになってしまいます。","yonlendirme":"尾骨は下へ、そけい部は前へ。"},"soylenecekler":["後ろの膝の下にブランケットを敷いて、楽にしましょう。","尾骨を床の方へ伸ばしてください。","腰ではなく、股関節の前側で伸びを感じましょう。"],"eller":{"nereye":"片手を仙骨に、もう片方の手を同じ側の下部肋骨の前に当てます。","nasil":"仙骨をやさしく下へ導き、肋骨を内へ引き込みます。腰を前へ押さないでください。","ne_zaman_degil":"膝のお皿の痛みがある場合、妊娠中で腰に不安がある場合、または生徒の同意がない場合は触れないでください。"},"kolay":"後ろの膝の下にたたんだブランケットを敷き、両手を前の太ももかブロックに置きます。","zor":"後ろの足を同じ側の手でつかみ、かかとをお尻に近づけます。","dikkat":"膝のお皿に不安がある場合は、後ろの膝の下を厚めにサポートします。股関節や腰に痛みがある場合は、医師や理学療法士に相談するよう勧めてください。","s":17,"fig":true},{"n":13,"bolum":1,"ad":"女神のポーズ（ウトゥカタ・コーナーサナ）","aile":"立位","seviye":"初級","yogunluk":[3,5,7],"calisan":["大腿四頭筋","大殿筋","中殿筋・小殿筋"],"dengeleyen":["腹横筋","骨盤底筋群","脊柱起立筋"],"uzayan":["内転筋群"],"ozet":"広く外向きの土台の上で、上体をまっすぐに保ったまま深くしゃがむことを教えます。股関節の外旋と脚の持久力を養う力強いポーズです。","asamalar":{"giris":"足を大きく開き、つま先を約45度外に向けます。息を吐きながら膝を曲げ、お尻を膝と同じ高さへ向けて下ろします。腕はサボテンの形か胸の前にします。","kalis":"膝はつま先と同じ方向に向け、骨盤はニュートラル、上体はまっすぐに保ちます。5〜8呼吸キープし、吐く息で骨盤底筋群を軽く引き上げます。","cikis":"息を吸いながら足で床を押して脚を伸ばし、つま先を内側に戻してステップで足をそろえます。"},"hata":{"ne":"膝が内側に崩れてしまう。","neden":"股関節の外旋筋群や中殿筋が十分に働かないと、太ももが内旋します。","yonlendirme":"膝は小指の方向へ開きます。"},"soylenecekler":["膝を小指の方向へ開きましょう。","上体をまっすぐに保ち、尾骨は床に向けてください。","足裏で床を左右に押し広げましょう。"],"eller":{"nereye":"両手を膝の内側に、軽く当てます。","nasil":"膝をつま先の方向へ外に導きます。無理に開かず、方向を感じてもらうだけにしてください。","ne_zaman_degil":"そけい部の張りや膝の痛みを訴えている場合、または同意がない場合は触れないでください。太ももの内側に触れる場合は、必ず事前に確認してください。"},"kolay":"曲げる深さを浅くするか、背中を壁につけます。両手は太ももに置きます。","zor":"かかとを浮かせて母趾球で同じ深さを保つか、腕を頭上に上げたままにします。","dikkat":"膝やそけい部に不安がある場合は浅く曲げます。妊娠中はスタンスの幅を快適さに合わせて調整します。痛みがある場合は、医師や理学療法士に相談するよう勧めてください。","s":18,"fig":true},{"n":14,"bolum":1,"ad":"下向きの犬のポーズ（アド・ムカ・シュヴァーナーサナ）","aile":"立位","seviye":"初級","yogunluk":[3,5,6],"calisan":["前鋸筋","三角筋","大腿四頭筋"],"dengeleyen":["広背筋","ハムストリングス","腹横筋"],"uzayan":["ハムストリングス","腓腹筋・ヒラメ筋","広背筋"],"ozet":"手からお尻へ、お尻からかかとへと伸びる2本の長いラインをつくることを教えます。フローの中で休息と移行のポーズとして、すべてのレベルで使われます。","asamalar":{"giris":"四つんばいからつま先を立てます。息を吐きながらお尻を上と後ろへ持ち上げ、山のような三角形をつくります。","kalis":"手は肩幅で指を広げ、お尻は天井へ伸ばします。背骨は長く、首はリラックスさせます。かかとは床の方へ向けますが、無理はしません。5〜8呼吸キープします。","cikis":"息を吐きながら膝を床に下ろしてチャイルドポーズに移るか、両手の間に足を踏み出します。"},"hata":{"ne":"かかとを床につけようとして背中を丸めてしまう。","neden":"ハムストリングスやふくらはぎが硬いと骨盤が後傾し、腰椎が丸まります。","yonlendirme":"まず背中を長く、かかとはそのあとで。"},"soylenecekler":["膝は遠慮なく曲げてください。まずは背中を長くしましょう。","手で床を押して、お尻を後ろへ送りましょう。","頭は両腕の間で力を抜いてください。"],"eller":{"nereye":"両手を仙骨の上部に、または左右の腰骨の後ろ側に当てます。","nasil":"お尻を上と後ろへ、尾骨の方向へ導きます。下へ押さないでください。","ne_zaman_degil":"手首や肩の痛み、高血圧、妊娠後期の場合、または同意がない場合は触れないでください。"},"kolay":"膝をしっかり曲げるか、両手をブロックに置きます。","zor":"片脚を上げて腰を正面にそろえるか、吐く息で鼻を両手の前まで運んでから戻ります。","dikkat":"手首に不安がある場合は、体重を指の付け根に分散させるか、前腕をついたバリエーションに変えます。肩や手首に痛みがある場合は、医師や理学療法士に相談するよう勧めてください。","s":19,"fig":true},{"n":15,"bolum":1,"ad":"立位の側屈","aile":"立位","seviye":"初級","yogunluk":[1,3,4],"calisan":["腹斜筋","腰方形筋"],"dengeleyen":["中殿筋・小殿筋","腹横筋"],"uzayan":["広背筋","腹斜筋","腰方形筋"],"ozet":"立った姿勢で、純粋な側方の面の中で体側のラインを伸ばすことを教えます。ウォームアップや立位のシークエンスの合間に、呼吸を体側の肋骨へ導くために使います。","asamalar":{"giris":"山のポーズで立ちます。息を吸いながら両腕を上に伸ばして手のひらを合わせ、息を吐きながら腰を少し反対側へずらし、上体を横に倒します。","kalis":"腰は足の上に保ち、胸は前にも後ろにも回しません。両足に均等に体重をのせます。3〜5呼吸キープし、伸びている側の肋骨へ呼吸を送ります。","cikis":"息を吸いながら上体を中央に戻し、息を吐きながら腕を下ろして反対側へ移ります。"},"hata":{"ne":"横に倒れるときに上体が前や後ろへ回ってしまう。","neden":"体側のラインが硬いと、体は背骨の回旋や屈曲で動きを補おうとします。","yonlendirme":"2枚のガラスの間で倒れます。"},"soylenecekler":["2枚のガラスの間に立っているように、真横にだけ倒れましょう。","まず上へ伸びて、それから横へ。","上側の肋骨が広がるのを感じましょう。"],"eller":{"nereye":"片手を伸びている側の腰に、もう片方の手を同じ側の肋骨に当てます。","nasil":"腰が安定するよう軽く導き、肋骨には上へ伸びる方向を示します。横へ押さないでください。","ne_zaman_degil":"肩の痛みや腰の痛みを訴えている場合、または同意がない場合は触れないでください。"},"kolay":"片手を腰に置き、片腕だけを上に伸ばします。","zor":"片足をもう片方の足の後ろで交差させ、体側のラインをかかとまで伸ばします。","dikkat":"肩に不調がある場合は、腕を低めに保ちます。腰に刺すような感覚がある場合は倒す角度を小さくし、医師や理学療法士に相談するよう勧めてください。","s":20,"fig":true},{"n":16,"bolum":1,"ad":"ねじった椅子のポーズ（パリヴリッタ・ウトゥカターサナ）","aile":"ねじり","seviye":"中級","yogunluk":[4,6,7],"calisan":["大腿四頭筋","腹斜筋","大殿筋"],"dengeleyen":["内転筋群","多裂筋","腹横筋"],"uzayan":["菱形筋"],"ozet":"椅子のポーズの脚の力を保ったまま、胸郭からねじることを教えます。バランス、筋力、回旋を同時に養います。","asamalar":{"giris":"椅子のポーズで胸の前で手を合わせます。息を吸いながら背骨を伸ばし、息を吐きながらねじって反対側のひじを太ももの外側にかけます。","kalis":"膝は横に並べたまま、腰は同じ高さで後ろに保ちます。背骨は長い軸を中心に回旋します。手のひらは胸骨の前に置き、5呼吸キープします。","cikis":"息を吸いながら中央に戻り、息を吐きながら手をほどいて脚を伸ばし、立ち上がります。"},"hata":{"ne":"ねじる間に片方の膝が前へずれ、腰の位置がそろわなくなる。","neden":"回旋を胸郭ではなく骨盤から始めると内転筋群のコントロールが失われ、骨盤も一緒に回ってしまいます。","yonlendirme":"膝は横並び、ねじりは胸から。"},"soylenecekler":["膝の位置をそろえ、片方が前に出ないようにしましょう。","まず頭のてっぺんへ伸び、吐く息でねじりましょう。","手のひらを押し合わせ、胸を親指の方向へ開いてください。"],"eller":{"nereye":"片手を膝の前に（位置をそろえるため）、もう片方の手を上側の肩甲骨に当てます。","nasil":"膝を軽く同じ位置にそろえ、肩甲骨はねじる方向へ導きます。回して無理にねじりを深めないでください。","ne_zaman_degil":"妊娠中、腰の痛みや椎間板の問題を申告している場合、または同意がない場合は触れないでください。"},"kolay":"片手を腰に、もう片方の手を太ももに置き、ねじりを小さくします。","zor":"腕を開き、下の手を足の外側の床へ、上の腕を天井へ伸ばします。","dikkat":"妊娠中は、この閉じたねじりの代わりに開いたねじりを選びます。腰や膝に痛みがある場合は、医師や理学療法士に相談するよう勧めてください。","s":21,"fig":true},{"n":17,"bolum":1,"ad":"ハンブル・ウォーリア","aile":"立位","seviye":"中級","yogunluk":[4,6,7],"calisan":["大腿四頭筋","大殿筋","僧帽筋中部・下部"],"dengeleyen":["中殿筋・小殿筋","腹横筋","菱形筋"],"uzayan":["大胸筋・小胸筋","腸腰筋"],"ozet":"戦士のポーズⅠの土台から前膝の内側へ上体を倒し、胸の前側を開くことを教えます。脚の力、肩の開き、ゆだねる感覚をひとつのポーズで組み合わせます。","asamalar":{"giris":"戦士のポーズⅠから背中で両手を組み、息を吸いながら胸を開きます。息を吐きながら上体を前膝の内側へ下ろし、腕は天井へ伸ばします。","kalis":"前膝は足首の上で安定させ、後ろ脚は長く保ちます。前側の肩は膝の内側へ下り、首はリラックスさせます。5呼吸キープします。","cikis":"息を吸いながら脚で床を押して上体を起こし、息を吐きながら手をほどいて反対側へ移ります。"},"hata":{"ne":"上体を下ろすときに前膝が内側へ崩れてしまう。","neden":"上体の重さが前脚の内側にかかると中殿筋が支えきれず、太ももが内旋します。","yonlendirme":"肩は膝の内側へ、膝は安定したまま。"},"soylenecekler":["前の膝を、第2趾の上で安定させましょう。","肩を膝の内側へゆだねてください。","組んだ手を頭の上の方へ伸ばし、首はリラックスさせましょう。"],"eller":{"nereye":"片手を前膝の外側に、もう片方の手を組んだ手の手首に当てます。","nasil":"膝が第2趾のラインに保たれるよう軽く導きます。腕にはごくわずかに上へ伸びる方向を示し、決して引っぱらないでください。","ne_zaman_degil":"肩の不安定さ、高血圧、めまいがある場合、または同意がない場合は触れないでください。"},"kolay":"手を組む代わりにストラップを持つか、両手を前の床に置きます。","zor":"組んだ腕をさらに遠くへ伸ばし、8呼吸キープします。","dikkat":"頭が下がる姿勢になるため、血圧やめまいの不安を訴える生徒は上体を高い位置に保ちます。肩に痛みがある場合は、医師や理学療法士に相談するよう勧めてください。","s":22,"fig":true},{"n":18,"bolum":1,"ad":"太陽礼拝Ａ（スーリヤ・ナマスカーラＡ）","aile":"立位","seviye":"初級","yogunluk":[2,4,6],"calisan":["前鋸筋","上腕三頭筋","大腿四頭筋","脊柱起立筋"],"dengeleyen":["腹横筋","回旋筋腱板（ローテーターカフ）","大胸筋・小胸筋"],"uzayan":["ハムストリングス","腓腹筋・ヒラメ筋"],"ozet":"ひとつひとつの動きをひと呼吸に合わせて体を温める、古典的なフローを教えます。クラスの始まりに、リズム、呼吸、基本のポーズの流れを定着させます。","asamalar":{"giris":"山のポーズから、息を吸いながら両腕を上げ（ウールドゥヴァ・ハスターサナ）、息を吐きながら前屈し（ウッターナーサナ）、息を吸いながら半分起こして背中を伸ばし（アルダ・ウッターナーサナ）、息を吐きながら足を後ろへ引いてチャトランガへ下ります。","kalis":"息を吸いながら上向きの犬のポーズに移り、息を吐きながら下向きの犬のポーズで5呼吸キープします。流れ全体を通して、肩は耳から遠ざけ、お腹の中心は働かせ、呼吸と動きを一致させます。","cikis":"息を吸いながら両手の間に足を踏み出して半分起こし、息を吐きながら前屈し、息を吸いながら両腕を上げて起き上がり、息を吐きながら山のポーズで手を下ろします。"},"hata":{"ne":"チャトランガで肩がひじの高さより下に落ちてしまう。","neden":"上腕三頭筋や前鋸筋が疲れると上体の重さが肩の前にかかり、上腕骨頭が前へずれます。","yonlendirme":"肩はひじの高さ、胸は前へ。"},"soylenecekler":["ひとつの動きにひと呼吸。息を止めないでください。","チャトランガではひじを肋骨に近づけ、肩はひじの高さに保ちましょう。","必要なら膝を床につけましょう。深さよりリズムが大切です。"],"eller":{"nereye":"下向きの犬のポーズでは両手を仙骨の上部に当てます。チャトランガでは触れずに、言葉だけで導きます。","nasil":"犬のポーズではお尻を上と後ろへ軽く導きます。移行の流れを止めないよう、触れる時間は短くしてください。","ne_zaman_degil":"移行の最中、手首や肩の痛みがある場合、妊娠中、または同意がない場合は触れないでください。"},"kolay":"チャトランガの代わりに膝・胸・あごを床につけて下り、上向きの犬のポーズの代わりにコブラのポーズを行います。","zor":"ステップの代わりにジャンプで移行するか、各ポーズで3呼吸ずつキープしてゆっくり行います。","dikkat":"手首、肩、腰に不安がある場合は、チャトランガと上向きの犬のポーズを置き換えます。妊娠中はうつ伏せになる移行を省きます。痛みがある場合は、医師や理学療法士に相談するよう勧めてください。","s":23,"fig":true},{"n":19,"bolum":1,"ad":"太陽礼拝Ｂ（スーリヤ・ナマスカーラＢ）","aile":"立位","seviye":"中級","yogunluk":[3,5,7],"calisan":["大腿四頭筋","大殿筋","上腕三頭筋","前鋸筋"],"dengeleyen":["腹横筋","回旋筋腱板（ローテーターカフ）","中殿筋・小殿筋"],"uzayan":["ハムストリングス","腸腰筋"],"ozet":"太陽礼拝Ａに椅子のポーズと戦士のポーズⅠを加え、熱と持久力を高めるフローを教えます。長い流れの中で、脚の力と呼吸のリズムを保つ練習になります。","asamalar":{"giris":"山のポーズから、息を吸いながら膝を曲げて腕を上げ（ウトゥカターサナ）、息を吐きながら前屈し、息を吸いながら半分起こし、息を吐きながらチャトランガへ下り、息を吸いながら上向きの犬のポーズ、息を吐きながら下向きの犬のポーズへ移ります。","kalis":"息を吸いながら右足を前に踏み出して戦士のポーズⅠで立ち上がり、息を吐きながらヴィンヤサで下向きの犬のポーズに戻ります。左側も同様に行い、下向きの犬のポーズで5呼吸キープします。戦士のポーズⅠでは腰を正面に向け、呼吸と動きを一致させます。","cikis":"息を吸いながら両手の間に足を踏み出して半分起こし、息を吐きながら前屈し、息を吸いながら椅子のポーズで腰を下ろしてから立ち上がり、息を吐きながら山のポーズで腕を下ろします。"},"hata":{"ne":"呼吸が動きから離れ、息を止めてしまう。","neden":"流れが長くなるにつれて脚や腕の筋肉が疲れ、横隔膜ではなく首や肩で呼吸し始めます。","yonlendirme":"ひとつの動きにひと呼吸。"},"soylenecekler":["呼吸が速くなったら、犬のポーズで止まってリズムを取り戻しましょう。","戦士のポーズⅠでは、左右の腰骨を正面に向けましょう。","椅子のポーズでは後ろに座り、体重はかかとにのせてください。"],"eller":{"nereye":"戦士のポーズⅠでは片手を後ろ側の腰の横に、下向きの犬のポーズでは両手を仙骨に当てます。","nasil":"戦士のポーズⅠでは後ろの腰を軽く前へ導き、犬のポーズではお尻を上と後ろへ示します。移行中は触れないでください。","ne_zaman_degil":"移行の最中、疲労のサインがはっきり見える場合、妊娠中、または同意がない場合は触れないでください。"},"kolay":"チャトランガは膝をついて行い、戦士のポーズⅠの代わりにローランジを選び、回数を減らします。","zor":"戦士のポーズⅠで3呼吸キープするか、ヴィンヤサをジャンプでつなぎます。","dikkat":"心臓や血管の不安、またはめまいを訴える生徒はテンポを落とします。手首、肩、膝に痛みがある場合は、医師や理学療法士に相談するよう勧めてください。","s":24,"fig":true},{"n":20,"bolum":1,"ad":"立位前屈（ウッターナーサナ）","aile":"前屈","seviye":"初級","yogunluk":[2,4,6],"calisan":["大腿四頭筋","脊柱起立筋"],"dengeleyen":["ハムストリングス","腓腹筋・ヒラメ筋","前脛骨筋"],"uzayan":["ハムストリングス","腓腹筋・ヒラメ筋","脊柱起立筋"],"ozet":"股関節から前に折りたたみ、背骨を重力にゆだねることを教えます。フローの中で落ち着きをもたらす移行のポーズであり、ハムストリングスの状態を知るポーズでもあります。","asamalar":{"giris":"山のポーズで両手を腰に置きます。息を吸いながら背骨を伸ばし、息を吐きながら膝をゆるめて股関節から前に折りたたみます。","kalis":"腰は足首の上、体重は足の中央に保ちます。上体は太ももの方へゆだね、首は力を抜きます。5〜8呼吸キープします。","cikis":"膝を曲げて両手を腰に置き、息を吸いながら背中を長く保って起き上がります。"},"hata":{"ne":"膝をロックして、腰にぶら下がってしまう。","neden":"ハムストリングスが硬いと骨盤が前傾せず、上体の重さが腰椎にかかります。","yonlendirme":"膝はやわらかく、股関節から倒れます。"},"soylenecekler":["膝を曲げて、お腹を太ももに近づけましょう。","頭の力を抜いて、軽くうなずいたり首を振ったりしてみましょう。","腰を足首の真上に保ってください。"],"eller":{"nereye":"両手を仙骨の上部に、またはお尻の後ろ側に当てます。","nasil":"腰を足首の真上の方へ、軽く前に導きます。背中から下へ押さないでください。","ne_zaman_degil":"腰の痛み、高血圧、めまいを訴えている場合、または同意がない場合は触れないでください。"},"kolay":"膝をしっかり曲げ、両手をブロックに置くか、反対側のひじをつかみます。","zor":"足の親指を人差し指と中指でつかむか、手のひらを足裏の下に入れます。","dikkat":"腰に不安がある場合は膝を曲げたままにし、ゆっくり起き上がります。血圧やめまいの不安がある場合は頭を高い位置に保ちます。痛みが続く場合は、医師や理学療法士に相談するよう勧めてください。","s":25,"fig":true},{"n":21,"bolum":2,"ad":"木のポーズ（ヴリクシャーサナ）","aile":"バランス","seviye":"初級","yogunluk":[2,3,5],"calisan":["中殿筋・小殿筋","前脛骨筋","腓腹筋・ヒラメ筋"],"dengeleyen":["内転筋群","腹横筋","骨盤底筋群"],"uzayan":["内転筋群"],"ozet":"片足で、まっすぐ静かに立ち、骨盤を水平に保つことを教えます。クラスで集中とバランスの練習を始めるための、安全な入り口です。","asamalar":{"giris":"山のポーズで体重を片足に移します。息を吸いながら、もう片方の足裏を内くるぶし、ふくらはぎの内側、または太ももの内側に置き、膝を横に開きます。","kalis":"軸脚側の腰は外へずらさず、骨盤は水平に保ちます。足裏と脚で互いを同じ力で押し合います。両手は胸の前か頭上に置き、5〜8呼吸キープします。","cikis":"息を吐きながら手を下ろし、上げた足をゆっくり床に下ろして反対側へ移ります。"},"hata":{"ne":"足を膝の横に押し当ててしまう。","neden":"膝関節は横方向の動きに向いていないため、足裏からの横の圧が関節の内側と外側の靭帯に負担をかけます。","yonlendirme":"膝の上か下に。膝の上には決して置きません。"},"soylenecekler":["足はふくらはぎか太ももに置きましょう。膝には置かないでください。","足と脚で、同じ力で押し合いましょう。","視線は前方の動かない一点に向けましょう。"],"eller":{"nereye":"片手を軸脚側の腰の外側に、もう片方の手を開いている膝の外側に当てます。","nasil":"腰を正中線の方へ軽く引き寄せます。膝の開きは方向を示すだけにし、下へ押さないでください。","ne_zaman_degil":"生徒が転倒への不安を感じている場合や同意がない場合は触れないでください。バランスのポーズで予告なく触れると、転倒につながることがあります。"},"kolay":"足を足首に置いてつま先を床につけたままにする（キックスタンド）か、片手を壁につきます。","zor":"両腕を上に伸ばして目を閉じるか、膝に問題がなければ半蓮華の木のポーズを試します。","dikkat":"足首や膝に不安がある場合は、足を低い位置に置きます。めまいを訴える生徒は壁のそばで行います。痛みがある場合は、医師や理学療法士に相談するよう勧めてください。","s":27,"fig":true},{"n":22,"bolum":2,"ad":"戦士のポーズⅢ（ヴィーラバドラーサナⅢ）","aile":"バランス","seviye":"中級","yogunluk":[5,6,8],"calisan":["大殿筋","ハムストリングス","脊柱起立筋","中殿筋・小殿筋"],"dengeleyen":["腹横筋","腓腹筋・ヒラメ筋","腹斜筋"],"uzayan":["ハムストリングス"],"ozet":"片脚で立ち、上体と後ろ脚を床と平行な一直線に保つことを教えます。体の後面の筋力と股関節のコントロールを養う力強いバランスポーズです。","asamalar":{"giris":"ハイランジから体重を前足に移します。息を吐きながら上体を前へ伸ばし、後ろ脚を持ち上げて上体と一直線にそろえます。","kalis":"骨盤は床と平行で正面にそろえ、上げた脚のつま先は床に向けます。背骨は長く、首はニュートラルに保ちます。5呼吸キープします。","cikis":"息を吐きながら上げた脚を曲げて床に下ろし、息を吸いながら上体を起こして山のポーズに戻ります。"},"hata":{"ne":"上げた脚側の腰が天井の方へ開いてしまう。","neden":"脚を高く上げようとすると股関節が外旋し、中殿筋が骨盤を水平に保てなくなります。","yonlendirme":"腰骨は床に向け、つま先も床に向けます。"},"soylenecekler":["後ろ足のつま先を床に向けましょう。","頭のてっぺんから後ろのかかとまで、一本のラインを伸ばしましょう。","軸脚の膝はロックせず、少しやわらかく保ってください。"],"eller":{"nereye":"片手を上げた脚側の腰の上に、もう片方の手を軸脚側の腰に当てます。","nasil":"上げた脚側の腰を、骨盤が水平になるよう軽く床の方へ導きます。脚を持ち上げないでください。","ne_zaman_degil":"バランスを崩している場合、転倒のおそれがある場合、ハムストリングスの張りや痛みを訴えている場合、または同意がない場合は触れないでください。"},"kolay":"両手をブロックか壁につき、上げる脚を低めに保ちます。","zor":"両腕を耳の横から前方へ伸ばすか、呼吸に合わせて軸脚の曲げ伸ばしを行います。","dikkat":"腰や膝に不安がある場合は、手をサポートについたままにします。血圧やめまいの不安を訴える生徒はキープ時間を短くします。痛みがある場合は、医師や理学療法士に相談するよう勧めてください。","s":28,"fig":true},{"n":23,"bolum":2,"ad":"半月のポーズ（アルダ・チャンドラーサナ）","aile":"バランス","seviye":"中級","yogunluk":[4,6,7],"calisan":["中殿筋・小殿筋","大腿四頭筋","腹斜筋"],"dengeleyen":["前脛骨筋","腹横筋","前鋸筋"],"uzayan":["内転筋群","ハムストリングス"],"ozet":"片脚で立ちながら骨盤と胸を横に開き、バランスを保つことを教えます。お尻の外側の筋力と、開いた胸のラインを同時に養います。","asamalar":{"giris":"三角のポーズから前膝を曲げ、前の手を足の手のひらひとつ分ほど前に置いたブロックにつきます。息を吸いながら後ろ脚を腰の高さまで上げ、軸脚を伸ばします。","kalis":"左右の腰を縦に積み重ね、胸は横に開きます。上げた脚はアクティブに保ち、足首を曲げます。上の腕は天井へ伸ばし、5呼吸キープします。","cikis":"息を吐きながら軸脚の膝を曲げ、上げた脚をコントロールしながら下ろして、三角のポーズか戦士のポーズⅡに戻ります。"},"hata":{"ne":"上体が床の方へ崩れ、胸が閉じてしまう。","neden":"中殿筋や腹斜筋が十分に働かないと、体重が下の手にかかり、上体が床の方へ回ってしまいます。","yonlendirme":"後ろの壁にもたれるように開きます。"},"soylenecekler":["背中で後ろの壁にもたれるように、体を開きましょう。","下の手はブロックに軽く触れるだけ。体重は軸脚にのせてください。","上げた脚のかかとで後ろへ押しましょう。"],"eller":{"nereye":"片手を上側の腰の横に、もう片方の手を背中の上部（左右の肩甲骨の間）に当てます。","nasil":"上側の腰を軽く後ろへ、胸が開く方向へ導きます。生徒があなたにもたれてバランスをとらないようにしてください。","ne_zaman_degil":"バランスを崩しているとき、足首に不安がある場合、または同意がない場合は触れないでください。"},"kolay":"背中を壁につけて行い、下の手は高めのブロックに置きます。","zor":"上げた脚の足を上の手でつかみ、サトウキビのポーズ（アルダ・チャンドラ・チャーパーサナ）のバリエーションへ移ります。","dikkat":"首に不安がある場合は、視線を床か前方に向けます。足首や股関節に痛みがある場合は、医師や理学療法士に相談するよう勧めてください。","s":29,"fig":true},{"n":24,"bolum":2,"ad":"鷲のポーズ（ガルダーサナ）","aile":"バランス","seviye":"中級","yogunluk":[3,5,6],"calisan":["大腿四頭筋","内転筋群","中殿筋・小殿筋"],"dengeleyen":["前脛骨筋","腹横筋","腓腹筋・ヒラメ筋"],"uzayan":["菱形筋","僧帽筋中部・下部","梨状筋"],"ozet":"腕と脚を巻きつけて体を正中線に集め、狭い土台の上でバランスをとることを教えます。肩の後ろ側を開きながら、集中力も養います。","asamalar":{"giris":"膝を軽く曲げます。息を吸いながら片脚をもう片方の脚の上に交差させ、腕も反対側から交差させてひじを巻きつけます。","kalis":"お尻は後ろに座り、上体はまっすぐ、腰は水平に保ちます。ひじは肩の高さで前に置きます。5呼吸キープし、呼吸を背中の上部へ送ります。","cikis":"息を吐きながら腕と脚をほどき、山のポーズでひと呼吸おいてから反対側へ移ります。"},"hata":{"ne":"上の足を下のふくらはぎに無理に引っかけてしまう。","neden":"股関節の外旋筋群が硬いのに無理に足を引っかけると、回旋の負担が膝関節に移ります。","yonlendirme":"足を引っかけなくても大丈夫。太ももを締めます。"},"soylenecekler":["つま先を床やブロックに置いても、まったく問題ありません。","太ももを互いに締め合い、お尻は後ろに座りましょう。","ひじを持ち上げ、手を顔から遠ざけてください。"],"eller":{"nereye":"片手を軸脚側の腰の外側に、もう片方の手を左右の肩甲骨の間に当てます。","nasil":"腰を正中線に集めるように軽く導き、背中には広がる方向を示すだけにします。","ne_zaman_degil":"膝や肩の痛みがある場合、転倒への不安がある場合、または同意がない場合は触れないでください。"},"kolay":"上の足のつま先を床に置き（キックスタンド）、腕は巻きつける代わりに反対側の肩をつかみます。","zor":"巻きつけたまま上体を前に折りたたみ、ひじを膝に近づけます。","dikkat":"膝に不安がある場合は、足を引っかけないようにします。肩に痛みがある場合は、腕は反対側の肩をつかむだけにします。痛みが続く場合は、医師や理学療法士に相談するよう勧めてください。","s":30,"fig":true},{"n":25,"bolum":2,"ad":"踊り子のポーズ（ナタラージャーサナ）","aile":"バランス","seviye":"中級","yogunluk":[5,7,8],"calisan":["大殿筋","ハムストリングス","脊柱起立筋","中殿筋・小殿筋"],"dengeleyen":["前脛骨筋","腹横筋","腓腹筋・ヒラメ筋"],"uzayan":["大腿四頭筋","腸腰筋","大胸筋・小胸筋"],"ozet":"片脚で立ちながら後屈し、足で手を押して胸の前側を開くことを教えます。バランス、体の後面の筋力、前面のラインの伸びをひとつにまとめます。","asamalar":{"giris":"山のポーズで片膝を曲げ、同じ側の手で足首の内側をつかみます。息を吸いながら反対の腕を前へ伸ばし、息を吐きながら足で手を押しつつ上体を少し前へ傾けます。","kalis":"上げた膝は腰幅に保ち、骨盤はできるだけ床と水平に近づけます。胸は開き、腰は押しつぶしません。5呼吸キープします。","cikis":"息を吸いながら上体を起こし、息を吐きながら足を離して膝をゆっくり床の方へ下ろします。"},"hata":{"ne":"上げた膝が横に開いてしまう。","neden":"足を高く上げようとすると股関節が外旋し、骨盤が横に回ってしまいます。","yonlendirme":"膝は腰のラインに、足は手を押します。"},"soylenecekler":["足で手を押しましょう。手で足を引っぱらないでください。","上げた膝は、腰のラインに保ちましょう。","胸を、前に伸ばした手の方へ開いていきましょう。"],"eller":{"nereye":"片手を上げた脚の膝の外側に、もう片方の手を軸脚側の腰に当てます。","nasil":"膝を軽く正中線の方へ導きます。脚を持ち上げたり、後ろへ引っぱったりしないでください。","ne_zaman_degil":"腰の痛み、転倒への不安、肩の不安定さがある場合、または同意がない場合は触れないでください。"},"kolay":"足をつかむためにストラップを使い、前の手は壁につきます。","zor":"両手で頭上から足をつかみます（完成形の踊り子のポーズ）。","dikkat":"腰に不安がある場合は、後屈を小さく保ちます。肩や膝に痛みがある場合はストラップを使い、医師や理学療法士に相談するよう勧めてください。","s":31,"fig":true},{"n":26,"bolum":2,"ad":"立位で足の親指をつかむポーズ（ウッティタ・ハスタ・パーダングシュターサナ）","aile":"バランス","seviye":"中級","yogunluk":[4,6,8],"calisan":["腸腰筋","大腿四頭筋","中殿筋・小殿筋"],"dengeleyen":["前脛骨筋","腹横筋","脊柱起立筋"],"uzayan":["ハムストリングス","腓腹筋・ヒラメ筋"],"ozet":"背骨をまっすぐに保ったまま、片脚を前に上げてつかむことを教えます。股関節屈筋群の筋力とハムストリングスの伸びをバランスよく組み合わせます。","asamalar":{"giris":"山のポーズで体重を片足に移します。息を吸いながら反対の膝を胸に引き寄せ、同じ側の手の指で足の親指をつかみ、息を吐きながら脚を前へ伸ばします。","kalis":"軸脚は長く、骨盤は水平に保ちます。背骨はまっすぐ、肩は腰の真上に置きます。脚は必要なだけ曲げたまま、5呼吸キープします。","cikis":"息を吐きながら膝を曲げて足を離し、脚をゆっくり床に下ろして反対側へ移ります。"},"hata":{"ne":"脚を上げようとして背中を丸め、軸脚を曲げてしまう。","neden":"ハムストリングスが硬いと骨盤が後傾し、体は背骨を丸めることで高さを求めようとします。","yonlendirme":"まず背骨を長く、脚はそのあとで。"},"soylenecekler":["上げた膝は、遠慮なく曲げてください。","胸を持ち上げ、肩は腰の真上に置きましょう。","軸脚側の腰を正中線に引き寄せましょう。"],"eller":{"nereye":"片手を軸脚側の腰に、もう片方の手を背中の中央に当てます。","nasil":"腰は正中線に集まる方向へ、背中はまっすぐになる方向へ軽く導きます。脚を持ち上げないでください。","ne_zaman_degil":"ハムストリングスの張りや痛み、腰の痛み、転倒のおそれがある場合、または同意がない場合は触れないでください。"},"kolay":"足にストラップをかけるか、膝を曲げたまま手を膝の上に置きます。サポートに壁を使います。","zor":"伸ばした脚を横に開き、視線を反対側の肩へ向けて、さらに5呼吸キープします。","dikkat":"腰に不安がある場合は、膝を曲げたままにします。太ももの裏を痛めたことがある生徒はストラップを使います。痛みがある場合は、医師や理学療法士に相談するよう勧めてください。","s":32,"fig":true},{"n":27,"bolum":2,"ad":"立位スプリット（ウールドゥヴァ・プラサーリタ・エーカ・パーダーサナ）","aile":"バランス","seviye":"中級","yogunluk":[5,7,8],"calisan":["大殿筋","ハムストリングス","大腿四頭筋"],"dengeleyen":["中殿筋・小殿筋","前脛骨筋","腹横筋"],"uzayan":["ハムストリングス","腸腰筋","腓腹筋・ヒラメ筋"],"ozet":"立位前屈から片脚を上へ伸ばし、両脚の間に深い伸びをつくることを教えます。バランス、柔軟性、股関節のコントロールを同時に必要とします。","asamalar":{"giris":"立位前屈から体重を片足に移し、両手を床かブロックに置きます。息を吸いながら反対の脚を上に持ち上げます。","kalis":"腰は床に対して正面にそろえ、上げた脚の膝は床に向けます。上体は軸脚に近づけます。5呼吸キープします。","cikis":"息を吐きながら上げた脚をコントロールして下ろし、両足で立位前屈になってひと呼吸おきます。"},"hata":{"ne":"脚を高く上げようとして腰が天井の方へ開いてしまう。","neden":"高さを求めると股関節が外旋し、骨盤が正面にそろわなくなります。","yonlendirme":"高さではなく、腰をそろえることを優先します。"},"soylenecekler":["上げた脚の膝とつま先を床に向けましょう。","高さではなく、左右の腰を同じ高さにそろえましょう。","軸脚の膝は、少しゆるめてもかまいません。"],"eller":{"nereye":"片手を上げた脚側の腰に、もう片方の手を軸脚側の腰に当てます。","nasil":"上げた脚側の腰を軽く下へ導き、骨盤を正面にそろえます。脚を上へ押さないでください。","ne_zaman_degil":"ハムストリングスの張りや痛み、高血圧、めまいがある場合、または同意がない場合は触れないでください。"},"kolay":"両手を高めのブロックに置き、上げる脚を低めに保ちます。軸脚の膝は曲げておきます。","zor":"反対の手で軸脚の足首をつかみ、上体を脚に近づけます。","dikkat":"頭が心臓より低くなるため、血圧やめまいの不安を訴える生徒はキープ時間を短くします。ハムストリングスに痛みがある場合は、医師や理学療法士に相談するよう勧めてください。","s":33,"fig":true},{"n":28,"bolum":2,"ad":"サイドプランク（ヴァシシュターサナ）","aile":"アームバランス","seviye":"中級","yogunluk":[4,6,7],"calisan":["腹斜筋","前鋸筋","三角筋","中殿筋・小殿筋"],"dengeleyen":["回旋筋腱板（ローテーターカフ）","腰方形筋","腹横筋"],"uzayan":[],"ozet":"片手と足の外側で体を支え、側方の面で体を一直線に保つことを教えます。肩の安定性と体側の筋力を養う基本のポーズです。","asamalar":{"giris":"プランクから体重を右手に移し、足の外側に体を回します。息を吸いながらお尻を持ち上げ、左腕を天井へ伸ばします。","kalis":"支える手は肩の少し前に置き、肩は耳から遠ざけます。お尻は落とさず、頭からかかとまでまっすぐなラインをつくります。3〜5呼吸キープします。","cikis":"息を吐きながら上の手を床に下ろしてプランクに戻り、反対側へ移ります。"},"hata":{"ne":"お尻が床の方へ垂れ下がってしまう。","neden":"体側の筋肉や中殿筋が疲れると、骨盤が重力に負けて負担が肩にかかります。","yonlendirme":"お尻を上げて、頭からかかとまで一直線に。"},"soylenecekler":["下の手で床を押し、肩を耳から遠ざけましょう。","お尻を天井の方へ持ち上げましょう。","頭のてっぺんからかかとまで、一本のラインを伸ばしましょう。"],"eller":{"nereye":"片手を下側の腰の横に、軽く当てます。","nasil":"腰をごくわずかに上へ導いてラインを示します。体重を支えないでください。","ne_zaman_degil":"手首や肩の痛み、肩の不安定さがある場合、または同意がない場合は触れないでください。"},"kolay":"下側の膝を床につけるか、前腕をついて行います。","zor":"上の脚を持ち上げるか、上の手で足の親指をつかんで脚を上に伸ばします。","dikkat":"手首や肩に不安がある場合は、前腕をついたバリエーションを選びます。痛みを訴えた場合は、医師や理学療法士に相談するよう勧めてください。","s":34,"fig":true},{"n":29,"bolum":2,"ad":"舟のポーズ（ナーヴァーサナ）","aile":"バランス","seviye":"中級","yogunluk":[4,6,8],"calisan":["腹直筋","腸腰筋","大腿四頭筋"],"dengeleyen":["腹横筋","脊柱起立筋","腹斜筋"],"uzayan":["ハムストリングス"],"ozet":"坐骨の上でバランスをとりながら、背骨を長く、お腹の中心をアクティブに保つことを教えます。クラスの筋力パートで体幹の練習に使います。","asamalar":{"giris":"膝を曲げて座り、両手を太ももの裏に添えます。息を吸いながら胸を持ち上げ、少し後ろに傾いて足を床から浮かせ、すねを床と平行にします。","kalis":"体重は坐骨のすぐ後ろにのせ、背骨は長く、胸は開きます。両腕は床と平行に前へ伸ばします。呼吸を止めずに、5呼吸キープします。","cikis":"息を吐きながら足を床に下ろし、両手を膝に置いて背中をゆるめます。"},"hata":{"ne":"背中が丸まり、仙骨の上に崩れてしまう。","neden":"股関節屈筋群や腹筋が支えきれないと、骨盤が後傾して負担が腰椎に移ります。","yonlendirme":"坐骨の前にのり、胸は上へ。"},"soylenecekler":["胸を持ち上げて、背中を長く保ちましょう。","膝は曲げたままでも、まったく問題ありません。","息を止めないでください。お腹は働かせて、呼吸は流したままにしましょう。"],"eller":{"nereye":"片手を背中の中央（肩甲骨の下）に、手のひらを平らにして当てます。","nasil":"背中に上と前へ伸びる方向を軽く示します。生徒の体重を支えないでください。","ne_zaman_degil":"腰の痛みがある場合、妊娠中、最近お腹の手術を受けた場合、または同意がない場合は触れないでください。"},"kolay":"足を床につけたままにするか、両手で太ももの裏を支え続けます。","zor":"脚をまっすぐ伸ばして上体と脚で鋭い角をつくるか、呼吸に合わせてハーフボートまで下りてから戻ります。","dikkat":"妊娠中や、最近お腹の手術を受けた場合は、このポーズの代わりに別の体幹の練習を選びます。腰に痛みがある場合は、医師や理学療法士に相談するよう勧めてください。","s":35,"fig":true},{"n":30,"bolum":2,"ad":"カラスのポーズ（バカーサナ）","aile":"アームバランス","seviye":"中級","yogunluk":[5,7,8],"calisan":["前鋸筋","上腕三頭筋","腹直筋","腸腰筋"],"dengeleyen":["回旋筋腱板（ローテーターカフ）","内転筋群","腹横筋"],"uzayan":[],"ozet":"お腹の中心を引き締め、体重を両手の上へ移して腕でバランスをとることを教えます。アームバランスの入門と、自信を育てる練習に使います。","asamalar":{"giris":"しゃがんで両手を肩幅で床に置き、指を広げます。膝を上腕に置き、息を吐きながら体重を前へ移して、片足ずつ床から浮かせます。","kalis":"背中は丸め、お腹は引き込みます。ひじは手首の真上に保ち、視線は両手の前に向けます。3〜5呼吸キープします。","cikis":"息を吐きながら足をコントロールして床に下ろし、手を離してしゃがんだ姿勢で手首をゆるめます。"},"hata":{"ne":"頭を落として前に突っ込んでしまう。","neden":"体重を前に移すときにお腹の中心が引き締まらないと、頭が重心を越えて体が前に倒れます。","yonlendirme":"視線は前へ、背中は丸く。"},"soylenecekler":["視線は両手の前の床に向けましょう。","背中を丸めて、お腹を引き込みましょう。","まず片足、それからもう片方の足。急がなくて大丈夫です。"],"eller":{"nereye":"生徒の前でひざまずき、両手を肩の前側にごく軽く添えます。","nasil":"生徒が前に行きすぎたときに、肩を軽く支えます。体重を支えたり持ち上げたりしないでください。","ne_zaman_degil":"手首の痛み、肩の不安定さがある場合、妊娠中、または同意がない場合は触れないでください。"},"kolay":"足をブロックにのせた状態から始め、顔の前にクッションを置きます。足は片方ずつ浮かせます。","zor":"腕を伸ばして、腕を曲げたカラスのポーズ（カーカーサナ）からひじを伸ばしたカラスのポーズ（バカーサナ）へ移るか、チャトランガへジャンプバックします。","dikkat":"手首に不安がある場合は体重を指の付け根に分散させ、キープ時間を短くします。妊娠中は行いません。手首や肩に痛みがある場合は、医師や理学療法士に相談するよう勧めてください。","s":36,"fig":true},{"n":31,"bolum":2,"ad":"つま先立ちの椅子のポーズ","aile":"バランス","seviye":"中級","yogunluk":[4,6,7],"calisan":["大腿四頭筋","腓腹筋・ヒラメ筋","大殿筋"],"dengeleyen":["前脛骨筋","腹横筋","内転筋群"],"uzayan":[],"ozet":"母趾球の上で深くしゃがみながら、上体をまっすぐに保つことを教えます。足首の安定性、脚の筋力、集中力を養うために使います。","asamalar":{"giris":"足をそろえて立ち、かかとを持ち上げます。息を吐きながら膝を曲げ、お尻をゆっくりかかとの方へ下ろし、胸の前で手を合わせます。","kalis":"左右のかかとを触れ合わせ、体重は親指の付け根にのせます。膝は近づけ、上体はまっすぐに保ちます。5呼吸キープします。","cikis":"息を吸いながら足で床を押してゆっくり立ち上がり、かかとを床に下ろして山のポーズで立ちます。"},"hata":{"ne":"かかとが横にずれ、足首が外側に倒れてしまう。","neden":"ふくらはぎと前脛骨筋のバランスがとれないと、足首が外側の縁へ倒れます。","yonlendirme":"かかとは触れ合わせ、体重は親指の付け根に。"},"soylenecekler":["左右のかかとを押し合わせましょう。","体重を親指の付け根にのせてください。","上体はまっすぐ、視線は動かない一点に向けましょう。"],"eller":{"nereye":"生徒の後ろに立ち、両手を腰の横に当てます。","nasil":"腰が垂直に中央を保てるよう、ごく軽く支えます。下へ押さないでください。","ne_zaman_degil":"膝の痛み、足首の不安定さ、転倒への不安がある場合、または同意がない場合は触れないでください。"},"kolay":"かかとの下にたたんだブランケットを敷くか、片手を壁につきます。しゃがむ深さを浅くします。","zor":"両腕を上に伸ばすか、このポーズから膝を横に開いて女神のポーズへ、そこから立ち上がります。","dikkat":"膝や足首に不安がある場合は、浅くしゃがみます。痛みを訴えた場合は、医師や理学療法士に相談するよう勧めてください。","s":37,"fig":true},{"n":32,"bolum":2,"ad":"ねじった半月のポーズ（パリヴリッタ・アルダ・チャンドラーサナ）","aile":"バランス","seviye":"上級","yogunluk":[5,7,8],"calisan":["大殿筋","腹斜筋","中殿筋・小殿筋","多裂筋"],"dengeleyen":["前脛骨筋","腹横筋","大腿四頭筋"],"uzayan":["ハムストリングス"],"ozet":"片脚でバランスをとりながら、上体を軸脚の方へねじることを教えます。ねじり、バランス、体の後面の筋力を同時に必要とする上級のポーズです。","asamalar":{"giris":"戦士のポーズⅢから、反対側の手を肩の下に置いたブロックにつきます。息を吸いながら背骨を伸ばし、息を吐きながら胸を軸脚の側へ回して、上の腕を天井へ伸ばします。","kalis":"骨盤は床と平行で水平に保ち、上げた脚はアクティブにします。回旋は胸郭から行います。3〜5呼吸キープします。","cikis":"息を吐きながら上の手をブロックか腰に下ろし、上げた脚をゆっくり床に下ろして立位前屈へ移ります。"},"hata":{"ne":"上げた脚が外に回り、足が天井を向いてしまう。","neden":"ねじりを深めると骨盤も一緒に回り、上げた脚が腰とともに外へ開いてしまいます。","yonlendirme":"後ろ足のつま先は床に向けます。"},"soylenecekler":["上げた足のつま先を床に向けましょう。","まず伸びて、それから胸を回しましょう。","下の手はブロックに触れるだけ。体重は軸脚にのせてください。"],"eller":{"nereye":"片手を上げた脚側の腰に、もう片方の手を軸脚側の腰に当てます。","nasil":"腰が水平に保たれる方向へ、ごく軽く導きます。ねじりを深めるために回さないでください。","ne_zaman_degil":"腰や仙腸関節の痛みがある場合、妊娠中、転倒のおそれがある場合、または同意がない場合は触れないでください。"},"kolay":"下の手を高めのブロックに置き、上の手は腰に置いたまま、視線は床に向けます。","zor":"上の腕を天井へ伸ばして視線を上に向け、5呼吸キープします。","dikkat":"妊娠中はこの閉じたねじりは行いません。腰や足首に痛みがある場合、またバランスが不安定な生徒は壁を使います。痛みがある場合は、医師や理学療法士に相談するよう勧めてください。","s":38,"fig":true},{"n":33,"bolum":3,"ad":"座位前屈（パスチモッターナーサナ）","aile":"座位","seviye":"初級","yogunluk":[2,4,6],"calisan":["ハムストリングス","脊柱起立筋","大腿四頭筋"],"dengeleyen":["腓腹筋・ヒラメ筋","腹横筋"],"uzayan":["ハムストリングス","腓腹筋・ヒラメ筋","脊柱起立筋"],"ozet":"股関節から前に折りたたみ、背中の長さを保つことを学びます。クラスのクールダウンで、脚の後ろ側のつながりに意識を向けるために使います。","asamalar":{"giris":"杖のポーズで坐骨の上に座ります。息を吸いながら背骨を伸ばし、息を吐きながら骨盤を前に傾けて、股関節から上体を前に倒します。","kalis":"胸骨は足のほうへ伸び、骨盤は前傾を保ち、首は背骨の延長にあります。吸う息ごとに伸び、吐く息ごとに少しずつゆるめ、5〜10呼吸キープします。","cikis":"息を吸いながら両手を脚に沿って戻し、背骨を一つずつ積み上げて座位に戻ります。息を吐きながら膝を軽く曲げます。"},"hata":{"ne":"足に向かって体を引っ張り、背中を丸めてしまう。","neden":"ハムストリングスが硬いと骨盤が後傾し、動きが股関節ではなく腰椎から起こります。","yonlendirme":"ブランケットの上に座り、背中を長く伸ばします。"},"soylenecekler":["坐骨を感じて、その少し前に座りましょう。","胸を足のほうへ伸ばしましょう。鼻を膝につける必要はありません。","膝は曲げてもかまいません。まっすぐな脚より、長い背中が大切です。"],"eller":{"nereye":"仙骨の上端と腰の両側。","nasil":"同意を得てから、骨盤の前傾に寄り添うように、仙骨をやさしく前下方へ導きます。背中の中央から下へ押すことは絶対にしないでください。","ne_zaman_degil":"生徒の同意が得られないとき、腰やハムストリングスに痛みを訴えたとき、または妊娠中。"},"kolay":"たたんだブランケットに座り、膝を曲げて足裏にストラップをかけます。","zor":"膝を伸ばしたまま両手を足の先で組み、お腹を太ももに近づけます。背中は長く保ちます。","dikkat":"椎間板ヘルニアの既往、坐骨神経痛のような痛み、ハムストリングスの肉離れを訴える生徒には、膝を曲げたまま深さを控えてもらいます。痛みが続く場合は、医師や理学療法士に相談するよう勧めてください。妊娠中は脚を開いてお腹のスペースを確保します。","s":40,"fig":true},{"n":34,"bolum":3,"ad":"頭を膝につけるポーズ（ジャーヌ・シルシャーサナ）","aile":"前屈","seviye":"初級","yogunluk":[2,4,6],"calisan":["ハムストリングス","脊柱起立筋","腹斜筋"],"dengeleyen":["大腿四頭筋","腰方形筋"],"uzayan":["ハムストリングス","内転筋群","腰方形筋"],"ozet":"片脚の上で前屈し、上体を伸ばした脚の中心にそろえることを学びます。左右を別々に行うため、左右差に気づかせるのに役立ちます。","asamalar":{"giris":"右脚を伸ばし、左足の裏を右の内ももに置きます。息を吸いながら上体を右脚のほうへ向けて伸ばし、息を吐きながら股関節から前に倒します。","kalis":"おへそと胸骨は伸ばした脚の中心を向き、曲げた膝側の腰も長く保ちます。5〜8呼吸キープし、吸う息ごとに伸びます。","cikis":"息を吸いながら上体を起こし、息を吐きながら曲げた脚を伸ばして反対側へ移ります。"},"hata":{"ne":"上体が曲げた膝の側に崩れ、伸ばした脚に向かって横に倒れてしまう。","neden":"曲げた脚の股関節が外旋すると骨盤がその方向に開き、上体が中心からずれます。","yonlendirme":"おへそは伸ばした膝の中心へ。"},"soylenecekler":["曲げた膝の下にサポートを置いてもかまいません。","まず上体を伸ばした脚に向けてから、前に倒れましょう。","左右の腰の長さをそろえましょう。"],"eller":{"nereye":"曲げた脚側のお尻の後ろと、同じ側の肋骨の横。","nasil":"同意を得てから、お尻をやさしく後ろ下方に安定させながら、肋骨を伸ばした脚のほうへ導きます。引っ張らず、寄り添うだけにします。","ne_zaman_degil":"曲げた膝に痛みや半月板の不調を訴えたとき、または生徒が触れられることを望まないとき。"},"kolay":"ブランケットに座り、伸ばした膝の下に丸めたブランケットを置き、足にストラップをかけます。","zor":"伸ばした脚の足を両手でつかみ、額をすねに近づけます。背中は長く保ちます。","dikkat":"膝の痛みを訴える生徒には、曲げた膝をブロックで支えます。膝の詰まり感が続く場合は、医師や理学療法士に相談するよう勧めてください。","s":41,"fig":true},{"n":35,"bolum":3,"ad":"開脚座位前屈（ウパヴィシュタ・コーナーサナ）","aile":"前屈","seviye":"中級","yogunluk":[3,5,7],"calisan":["内転筋群","ハムストリングス","脊柱起立筋"],"dengeleyen":["大腿四頭筋","腹横筋"],"uzayan":["内転筋群","ハムストリングス"],"ozet":"脚を大きく開いた状態で骨盤を前傾させることを学びます。内ももとハムストリングスの伸びを、あせらずに探るために使います。","asamalar":{"giris":"無理なく開ける範囲で脚を開き、膝のお皿とつま先を天井に向けます。息を吸いながら坐骨の上に座り、息を吐きながら両手を前に歩かせます。","kalis":"骨盤は前傾し、腰の自然なカーブを保ち、膝のお皿は天井を向いたままです。8〜10呼吸キープし、吐く息ごとに指一本分ずつ進みます。","cikis":"息を吸いながら両手を戻して上体を起こします。息を吐きながら両手を膝の下に添え、ゆっくり脚を閉じます。"},"hata":{"ne":"脚を開きすぎて、膝が内側に向いてしまう。","neden":"内転筋群が張るにつれて大腿骨が内旋し、負担が膝の内側に移ります。","yonlendirme":"膝のお皿は天井へ。"},"soylenecekler":["脚の幅を少し狭めて、背中を長く保ちましょう。","両手が前に進むとき、胸も一緒に前へ運びましょう。","求めるのは深さではなく、楽な呼吸です。"],"eller":{"nereye":"仙骨の上とお尻の後ろ側。","nasil":"同意を得てから、骨盤の前傾を助ける程度に、ごく軽く前方へ導きます。肩から押すことは絶対にしないでください。","ne_zaman_degil":"鼠径部や内ももに張りを訴えたとき、妊娠中、または生徒の同意が得られないとき。"},"kolay":"高めのブランケットに座り、膝を軽く曲げて、前に置いたブロックに両手を置きます。","zor":"両手を足の親指へ伸ばし、お腹と胸を床に近づけます。","dikkat":"鼠径部の張りや膝の内側の痛みを訴える生徒には、脚の開きを狭くしてもらいます。痛みが引かない場合は、医師や理学療法士に相談するよう勧めてください。","s":42,"fig":true},{"n":36,"bolum":3,"ad":"合せきの前屈（バッダ・コーナーサナ）","aile":"前屈","seviye":"初級","yogunluk":[2,3,5],"calisan":["脊柱起立筋","中殿筋・小殿筋"],"dengeleyen":["腹横筋","骨盤底筋群"],"uzayan":["内転筋群","脊柱起立筋"],"ozet":"足裏を合わせた状態で股関節から前屈することを学びます。内ももと背中の長さに意識を向けさせ、クラスの始めや終わりに適しています。","asamalar":{"giris":"足裏を合わせ、かかとを無理のない距離に引き寄せて、両手で足を持ちます。息を吸いながら背骨を伸ばし、息を吐きながら股関節から前に倒します。","kalis":"胸は足のほうへ伸び、膝は自分の重さで下がり、肩は耳から離れています。8〜10呼吸キープします。","cikis":"息を吸いながら上体を起こし、息を吐きながら両手で膝を閉じて脚を伸ばします。"},"hata":{"ne":"膝を床につけようとして、ひじで太ももを押してしまう。","neden":"股関節が外旋の限界に達すると、圧力が膝関節と鼠径部に伝わります。","yonlendirme":"膝は自分の重さで下ろします。"},"soylenecekler":["足の裏を本のページのように開いてもかまいません。","頭ではなく、胸を足のほうへ近づけましょう。","膝の高さは気にしなくて大丈夫です。今の位置のままにしておきましょう。"],"eller":{"nereye":"肩甲骨の間と仙骨。","nasil":"同意を得てから、片手で仙骨を床のほうへ安定させ、もう一方の手を背中に平らに置いて伸びに寄り添います。下へ押さないでください。","ne_zaman_degil":"鼠径部や膝に痛みがあるとき、妊娠中、または生徒が触れられることを望まないとき。"},"kolay":"ブランケットに座り、膝の下にブロックを置いて、かかとを鼠径部から遠ざけます。","zor":"かかとを鼠径部に近づけ、額を足へ下ろします。背中は長く保ちます。","dikkat":"膝や鼠径部の痛みを訴える生徒には、膝をブロックで支えて前屈の深さを控えてもらいます。妊娠中は上体を起こしたまま行います。痛みが続く場合は、医師や理学療法士に相談するよう勧めてください。","s":43,"fig":true},{"n":37,"bolum":3,"ad":"半分の前屈（アルダ・ウッターナーサナ）","aile":"前屈","seviye":"初級","yogunluk":[2,3,4],"calisan":["脊柱起立筋","多裂筋","僧帽筋中部・下部"],"dengeleyen":["大腿四頭筋","腹横筋"],"uzayan":["ハムストリングス","腓腹筋・ヒラメ筋"],"ozet":"立位前屈から背中をまっすぐにして半分まで起き上がることを学びます。太陽礼拝で背中の筋肉を目覚めさせる移行のポーズです。","asamalar":{"giris":"立位前屈で両手をすねかブロックに置きます。息を吸いながら胸を前に伸ばし、背骨を床と平行にします。","kalis":"頭・胸・骨盤は一直線で、腰は丸まりすぎず反りすぎず、視線は一歩先です。3〜5呼吸キープします。","cikis":"息を吐きながら上体を立位前屈に戻すか、両手を腰に当てて背中をまっすぐにしたまま立ち上がります。"},"hata":{"ne":"頭を持ち上げて、首の後ろを詰めてしまう。","neden":"胸を開こうとする意図が背中ではなく首から来ると、頸椎が伸びずに後ろに折れます。","yonlendirme":"うなじを長く、視線は斜め前の床へ。"},"soylenecekler":["両手はすねに置き、胸を前へ伸ばしましょう。","尾骨から頭のてっぺんまで、まっすぐな線をイメージしてください。","膝を曲げると、背中をまっすぐ保ちやすくなります。"],"eller":{"nereye":"仙骨と肩甲骨の間。","nasil":"同意を得てから、仙骨をやさしく後ろへ、胸のあたりを前へ導き、その間で伸びを感じてもらいます。","ne_zaman_degil":"腰の痛みを訴えたとき、または生徒の同意が得られないとき。"},"kolay":"両手を高いブロックか壁に置き、膝を曲げます。","zor":"指先を床につけるか、腕を耳の横で前に伸ばしたまま背中をまっすぐ保ちます。","dikkat":"腰の痛みやめまいがある生徒には、両手を高いサポートに置いて短めに行ってもらいます。不調が続く場合は、医師や理学療法士に相談するよう勧めてください。","s":44,"fig":true},{"n":38,"bolum":3,"ad":"ラグドール","aile":"前屈","seviye":"初級","yogunluk":[1,3,4],"calisan":["大腿四頭筋","ハムストリングス"],"dengeleyen":["腓腹筋・ヒラメ筋","前脛骨筋"],"uzayan":["脊柱起立筋","ハムストリングス","菱形筋"],"ozet":"膝をゆるめ、ひじを抱えて立位で前にぶら下がることを学びます。積極的なストレッチではなく、背中と首をゆだねる時間です。","asamalar":{"giris":"足を腰幅に開き、膝をたっぷり曲げます。息を吐きながら上体を太ももの上にゆだね、反対側のひじを持ちます。","kalis":"お腹は太ももに近く、頭と首は完全にぶら下がり、体重は足裏の前側にあります。軽く左右に揺れながら5〜10呼吸キープします。","cikis":"手を離して膝をさらに曲げ、息を吸いながら背骨を一つずつ転がすように起き上がります。頭は最後に上げます。"},"hata":{"ne":"膝を伸ばしきって、体重をかかとにかけてしまう。","neden":"膝をロックするとハムストリングスが張り、骨盤が後ろにずれて腰が負担を担います。","yonlendirme":"膝は曲げて、お腹は太ももに。"},"soylenecekler":["うなずいたり首を振ったりするように、頭をそっと揺らしましょう。","体重を少し前、つま先のほうへのせましょう。","ここでは何もしなくて大丈夫です。ただぶら下がりましょう。"],"eller":{"nereye":"仙骨の両側、または肩甲骨の上。","nasil":"同意を得てから、手のひらでごくわずかな重みをのせ、ゆだねる感覚をサポートします。下へ押さないでください。","ne_zaman_degil":"高血圧、めまい、眼圧の問題を訴えたとき、または同意がないとき。"},"kolay":"ひじを持つ代わりに、前腕を太ももの上に置きます。","zor":"両手をかかとの後ろに置き、膝を少し伸ばします。お腹は太ももから離しません。","dikkat":"高血圧、めまい、緑内障を訴える生徒には、頭を心臓より高く保つ半分の前屈を提案し、ゆっくり起き上がるよう伝えてください。","s":45,"fig":true},{"n":39,"bolum":3,"ad":"子犬のポーズ（ウッターナ・シショーサナ）","aile":"前屈","seviye":"初級","yogunluk":[2,4,5],"calisan":["前鋸筋","三角筋","僧帽筋中部・下部"],"dengeleyen":["腹横筋","大腿四頭筋"],"uzayan":["広背筋","大胸筋・小胸筋","上腕三頭筋"],"ozet":"お尻を膝の上に保ったまま、胸を床へとろけさせることを学びます。肩と上背部を開くポーズで、チャイルドポーズと下向きの犬のポーズの間をつなぎます。","asamalar":{"giris":"四つ這いから両手を数十センチ前に歩かせ、お尻を膝の真上に保ちます。息を吐きながら胸を床に向けて下ろし、額かあごをマットにつけます。","kalis":"お尻は膝の上、腕は肩幅でしっかり働かせ、腰は反りすぎません。5〜8呼吸キープし、呼吸を肋骨の後ろ側へ送ります。","cikis":"息を吸いながら両手を戻して四つ這いに戻るか、お尻をかかとに下ろしてチャイルドポーズで休みます。"},"hata":{"ne":"胸を下げるために、腰を反らせてしまう。","neden":"肩関節の可動域が限られていると、開きが胸椎ではなく腰椎で代償されます。","yonlendirme":"肋骨は内へ、胸は床へ。"},"soylenecekler":["お尻は膝の上に保ちましょう。","手のひらでマットを押し、ひじを床から浮かせてください。","胸がやわらかく床へとけていくのを感じましょう。"],"eller":{"nereye":"腰骨の上、または左右の肩甲骨の間。","nasil":"同意を得てから、お尻をやさしく後ろへ導き、背骨の伸びを感じてもらいます。胸を床へ押しつけないでください。","ne_zaman_degil":"肩の痛み、肩の脱臼歴、膝の痛みを訴えたとき、または同意がないとき。"},"kolay":"両手の下にブロックを、膝の下にたたんだブランケットを置きます。","zor":"手のひらを合わせてひじを曲げ、親指を首の後ろに置いて肩の開きを深めます。","dikkat":"肩の痛みや可動域の制限を訴える生徒には、両手をブロックに置き、腕の幅を広げてもらいます。膝に敏感さがあればサポートを加えます。痛みが続く場合は、医師や理学療法士に相談するよう勧めてください。","s":46,"fig":true},{"n":40,"bolum":3,"ad":"チャイルドポーズ（バーラーサナ）","aile":"リストラティブ","seviye":"初級","yogunluk":[1,1,2],"calisan":["横隔膜","腹横筋"],"dengeleyen":["骨盤底筋群","内転筋群"],"uzayan":["脊柱起立筋","腰方形筋","大腿四頭筋"],"ozet":"クラス中いつでも戻ってこられる休息のポーズです。呼吸を背中側へ送ることを生徒に教えます。","asamalar":{"giris":"膝を床につけ、足の親指同士を触れ合わせます。息を吐きながらお尻をかかとへ下ろし、上体を太ももの上か間にゆだねて額を床につけます。","kalis":"額は床かブロックに、腕は前か体の横に置き、肩はやわらかく。吸う息で背中が広がるのを感じ、1〜3分キープします。","cikis":"両手を肩の下に置き、息を吸いながら背骨を一つずつ起こして座位か四つ這いに戻ります。"},"hata":{"ne":"お尻がかかとに下りていないのに、無理に額を床につけようとする。","neden":"膝と足首の曲がりが限られていると、体重が首と肩にかかります。","yonlendirme":"床が届かなければ、床を高くします。"},"soylenecekler":["膝は好きなだけ開いてかまいません。","呼吸を背中の、腎臓のあたりへ送りましょう。","このポーズはいつでもここにあります。好きなときに戻ってきてください。"],"eller":{"nereye":"仙骨の上に、手のひらを平らに置きます。","nasil":"同意を得てから、吐く息でごくわずかな重みをのせて仙骨をかかとのほうへ導き、吸う息で手をゆるめます。","ne_zaman_degil":"膝の痛みがあるとき、妊娠中、または休息中の生徒が触れられることを望まないとき。休息のポーズでは、必ず先に言葉で許可を取ってください。"},"kolay":"お尻とかかとの間にたたんだブランケットを、額の下にブロックを、または上体の下に縦にボルスターを置きます。","zor":"腕を前に伸ばし、手のひらで床をしっかり押して、肩と体側に伸びをつくります。","dikkat":"膝の痛みを訴える生徒には、膝の裏にブランケットをはさむか、膝を胸に抱えるポーズを提案してください。妊娠中は膝を大きく開いてお腹のスペースを確保します。","s":47,"fig":true},{"n":41,"bolum":3,"ad":"仰向けで足の親指をつかむポーズ（スプタ・パーダングシュターサナ）","aile":"仰向け","seviye":"初級","yogunluk":[2,4,6],"calisan":["大腿四頭筋","腸腰筋","腹直筋"],"dengeleyen":["腹横筋","中殿筋・小殿筋"],"uzayan":["ハムストリングス","腓腹筋・ヒラメ筋"],"ozet":"背中を床につけ、骨盤をニュートラルに保ったまま、ハムストリングスを片脚ずつ伸ばすことを学びます。腰が床に支えられているため、コントロールしやすい脚の後ろ側の伸びが得られます。","asamalar":{"giris":"仰向けになり、右足の裏にストラップをかけます。息を吸いながら右脚を天井へ持ち上げ、左脚は床の上で長く伸ばしたままにします。","kalis":"骨盤は床と平らで、床側の太ももはマットを押し、肩はリラックスしています。上げた脚は膝が少し曲がっていても長く保ち、5〜10呼吸キープします。","cikis":"息を吐きながらストラップをゆるめ、膝を曲げて足を床に下ろします。反対側へ移ります。"},"hata":{"ne":"脚を近づけようとして、お尻を床から浮かせてしまう。","neden":"ハムストリングスが限界に達すると骨盤が後傾し、動きが腰椎に移ります。","yonlendirme":"骨盤は床に、脚はストラップ一本分遠くへ。"},"soylenecekler":["ストラップは引っ張らず、腕を長くして持ちましょう。","床にある脚の太ももでマットを押してください。","上げた脚は高さではなく、長さを感じましょう。"],"eller":{"nereye":"床にある脚の太ももの前と、上げた脚のかかと。","nasil":"同意を得てから、床側の太ももをやさしく下へ安定させます。上げた脚は生徒のコントロールに任せ、支えるだけにして押さないでください。","ne_zaman_degil":"ハムストリングスの肉離れや坐骨神経痛のような痛みを訴えたとき、または生徒が許可しないとき。"},"kolay":"床側の膝を曲げて足裏を床につけ、上げた脚の膝はやわらかく保ちます。","zor":"ストラップを外して足の親指を2本の指でつかむか、脚を横に開いて2つ目のバリエーションへ進みます。","dikkat":"坐骨神経痛のような痛みや椎間板ヘルニアの既往を訴える生徒には、脚を低く、膝を曲げたまま保ってもらいます。しびれやピリピリ感が出たらポーズから出て、医師や理学療法士に相談するよう勧めてください。","s":48,"fig":true},{"n":42,"bolum":3,"ad":"ハーフスプリット（アルダ・ハヌマーナーサナ）","aile":"前屈","seviye":"初級","yogunluk":[2,4,6],"calisan":["ハムストリングス","脊柱起立筋","大腿四頭筋"],"dengeleyen":["中殿筋・小殿筋","腹横筋"],"uzayan":["ハムストリングス","腓腹筋・ヒラメ筋"],"ozet":"ローランジから前脚を伸ばし、お尻を後ろに残したまま前屈することを学びます。スプリットのための基本の準備ポーズです。","asamalar":{"giris":"ローランジで後ろの膝を床につけ、両手を前足の両側かブロックに置きます。息を吐きながらお尻を後ろの膝の上へ戻し、前脚を伸ばします。","kalis":"お尻は後ろの膝の上、前の足首は曲げ、背中は長く。上体は前脚の上に折りたたまれます。5〜8呼吸キープします。","cikis":"息を吸いながら前の膝を曲げ、お尻を前に戻してローランジに戻るか、両手を肩の下に置いて四つ這いへ移ります。"},"hata":{"ne":"お尻を後ろの膝より前に残したまま、前脚に崩れ込んでしまう。","neden":"お尻が膝のラインより前にずれるとハムストリングスは伸びず、体重が前の膝と腰にかかります。","yonlendirme":"お尻は後ろの膝の真上に。"},"soylenecekler":["前足のつま先を自分のほうへ引き寄せましょう。","お尻は後ろへ、胸は前へ送りましょう。","前の膝は曲げてもかまいません。背中の長さを優先しましょう。"],"eller":{"nereye":"後ろ脚側の腰骨の前と仙骨。","nasil":"同意を得てから、お尻をやさしく後ろへ、後ろの膝の上へ導きます。上体を前に押さないでください。","ne_zaman_degil":"ハムストリングスの肉離れや膝の痛みがあるとき、または同意がないとき。"},"kolay":"後ろの膝の下にたたんだブランケットを、両手の下に高いブロックを2つ置きます。","zor":"ブロックを外し、前腕を床に下ろして上体をすねに近づけます。","dikkat":"膝のお皿に圧迫を感じる生徒には、後ろの膝をブランケットで支えます。ハムストリングスに鋭い感覚があればポーズから出て、続く場合は医師や理学療法士に相談するよう勧めてください。","s":49,"fig":true},{"n":43,"bolum":3,"ad":"スプリット（ハヌマーナーサナ）","aile":"前屈","seviye":"上級","yogunluk":[5,7,9],"calisan":["大腿四頭筋","中殿筋・小殿筋","腹横筋"],"dengeleyen":["内転筋群","骨盤底筋群"],"uzayan":["ハムストリングス","腸腰筋","大腿四頭筋"],"ozet":"前脚のハムストリングスと後ろ脚の股関節屈筋群を、同時に可動域の終わりまで伸ばします。骨盤を正面に保ち、ブロックで深さを調整しながら、あせらずに練習します。","asamalar":{"giris":"ハーフスプリットから前のかかとを前へ、後ろの膝を後ろへすべらせ、両手を両脇のブロックに置きます。息を吐きながら骨盤をゆっくり床へ下ろします。","kalis":"骨盤は前を向いて正面に保ち、後ろ脚の膝のお皿は床を、前脚の膝のお皿は天井を向きます。上体はまっすぐか少し前傾で、5呼吸キープします。","cikis":"両手でブロックを押し、息を吸いながら前の膝を曲げてお尻を後ろの膝の上へ引き戻し、ローランジからポーズを出ます。"},"hata":{"ne":"床に下りるために骨盤を横に開き、後ろ脚を外に回してしまう。","neden":"腸腰筋とハムストリングスが限界に達すると、体は骨盤を回して楽な道を探します。","yonlendirme":"腰骨は前へ。床は自然に近づいてきます。"},"soylenecekler":["前の太ももの下にブロックかボルスターを置きましょう。","後ろ脚の足の甲を、まっすぐマットにつけてください。","ここで急ぐ必要はありません。吐く息ごとに1ミリずつ進みましょう。"],"eller":{"nereye":"後ろ脚側の腰骨。","nasil":"同意を得てから、腰骨を前に向けて、骨盤が正面を保てるよう助けます。下へ押さないでください。","ne_zaman_degil":"過可動性のある生徒、ハムストリングスや鼠径部の肉離れがあるとき、妊娠中。深いポーズでは決して下へ押さないでください。"},"kolay":"前の太ももの下にボルスターを、両手の下に高いブロックを置くか、ハーフスプリットにとどまります。","zor":"サポートを外し、腕を上に伸ばして軽く後ろに反り、後ろ脚の股関節屈筋群を開きます。","dikkat":"ハムストリングスや鼠径部の肉離れ、股関節の不調を訴える生徒には、ハーフスプリットにとどまってもらいます。過可動性のある生徒は、サポートで深さを制限します。痛みがある場合は、医師や理学療法士に相談するよう勧めてください。","s":50,"fig":true},{"n":44,"bolum":3,"ad":"キャタピラー","aile":"リストラティブ","seviye":"初級","yogunluk":[1,3,4],"calisan":["横隔膜","腹直筋"],"dengeleyen":["骨盤底筋群","腹横筋"],"uzayan":["脊柱起立筋","ハムストリングス","腓腹筋・ヒラメ筋"],"ozet":"陰ヨガのスタイルで、筋力を使わずに脚を伸ばしたまま前に丸まるポーズです。背骨の後ろ側に、長くて受動的な伸びをもたらします。","asamalar":{"giris":"脚を前に伸ばして座り、必要なら膝の下に丸めたブランケットを置きます。息を吐きながら背中を丸めて上体を脚の上にゆだね、頭はぶら下げたままにします。","kalis":"背中は丸く、筋肉はゆるみ、両手は脚の横で休ませます。呼吸はゆっくり自然に。3〜5分キープし、ときどき心地よさを確認します。","cikis":"両手で床を押し、息を吸いながらとてもゆっくり、背骨を一つずつ転がして座位に戻ります。その後しばらく仰向けになって休みます。"},"hata":{"ne":"受動的であるべきポーズで、足に手を伸ばして体を引っ張ってしまう。","neden":"能動的に引っ張ると筋肉が緊張し、長くキープする目的であるゆるみが妨げられます。","yonlendirme":"手を伸ばさず、ゆだねてぶら下がります。"},"soylenecekler":["ここでは何もする必要はありません。","頭の下にボルスターかブロックを置いてもかまいません。","感覚の強さは、10段階で4を超えないようにしましょう。"],"eller":{"nereye":"背中の中央、肩甲骨のすぐ下。","nasil":"同意を得てから、手のひらを平らに置き、重みをかけずに、ぬくもりと気づきのためだけに触れます。","ne_zaman_degil":"椎間板ヘルニアの既往や骨粗しょう症を訴えたとき、または長いキープ中に触れられることを望まないとき。"},"kolay":"膝を曲げて太ももの上にボルスターを置き、上体をボルスターにゆだねます。","zor":"サポートを使わず、膝を伸ばしたまま5分までキープします。","dikkat":"椎間板ヘルニアの既往、坐骨神経痛のような症状、骨粗しょう症を訴える生徒には、背中を丸めて長くキープする代わりに、膝を曲げてサポートを使うバリエーションを提案してください。必要に応じて、医師や理学療法士に相談するよう勧めてください。","s":51,"fig":true},{"n":45,"bolum":3,"ad":"座位の側屈（パリヴリッタ・ジャーヌ・シルシャーサナ）","aile":"座位","seviye":"中級","yogunluk":[3,5,7],"calisan":["腹斜筋","脊柱起立筋"],"dengeleyen":["腹横筋","回旋筋腱板（ローテーターカフ）"],"uzayan":["広背筋","腰方形筋","ハムストリングス"],"ozet":"胸を天井に開いたまま、伸ばした脚のほうへ体を横に倒すことを学びます。体の側面、特に上側の肋骨と腰を伸ばします。","asamalar":{"giris":"右脚を横に伸ばし、左足を鼠径部に引き寄せます。息を吐きながら右の前腕を右脚の内側に下ろし、息を吸いながら左腕を耳の横から右足のほうへ伸ばします。","kalis":"胸は天井を向き、上の腕は耳の横で伸び、両方の坐骨は床に残ります。5〜8呼吸キープし、吸う息で上側の肋骨にスペースをつくります。","cikis":"息を吸いながら上の腕を上に伸ばして上体を起こし、息を吐きながら腕を下ろして反対側へ移ります。"},"hata":{"ne":"胸を床に向けて、ポーズを前屈にしてしまう。","neden":"体側とハムストリングスが張ってくると、上体は楽な前屈の方向へ流れます。","yonlendirme":"上の肩は後ろへ、胸は天井へ。"},"soylenecekler":["下の前腕を、脚の内側にあずけましょう。","上の腕は肩からではなく、肋骨から伸ばしてください。","曲げた膝側の坐骨で、床を押しましょう。"],"eller":{"nereye":"上側の肩の後ろと、曲げた脚側の腰骨。","nasil":"同意を得てから、お尻を床に安定させながら、肩をやさしく後ろへ開きます。深めるために下へ押さないでください。","ne_zaman_degil":"肩や首に痛みがあるとき、膝に不調があるとき、または同意がないとき。"},"kolay":"ブランケットに座り、下の手をブロックに置いて、上の手は腰に当てます。","zor":"上の手で伸ばした足の外側を、下の手で内側をつかみ、胸を天井へ向けます。","dikkat":"首に敏感さがある場合は視線を床か前に向けてもらい、肩の痛みがある場合は上の手を腰に当てたままにします。痛みが続く場合は、医師や理学療法士に相談するよう勧めてください。","s":52,"fig":true},{"n":46,"bolum":3,"ad":"うさぎのポーズ（ササンガーサナ）","aile":"前屈","seviye":"中級","yogunluk":[3,5,6],"calisan":["腹直筋","腹斜筋","僧帽筋中部・下部"],"dengeleyen":["菱形筋","腹横筋"],"uzayan":["脊柱起立筋","多裂筋","僧帽筋上部"],"ozet":"頭頂を床につけたまま、背骨を完全に屈曲させることを学びます。背中の後ろ側を一つずつ開き、逆転のポーズへのやさしい入り口にもなります。","asamalar":{"giris":"かかとの上に座り、両手でかかとをつかみます。息を吐きながらあごを胸に近づけ、額を膝の前に、頭頂を床につけます。","kalis":"額は膝の近くにあり、体重の大部分は頭ではなく膝と腕にかかります。息を吸いながらお尻を持ち上げて背中を丸め、3〜5呼吸キープします。","cikis":"息を吐きながらお尻をかかとに下ろし、額を床につけてしばらくチャイルドポーズで休んでから、ゆっくり起き上がります。"},"hata":{"ne":"頭頂に体重をかけてしまう。","neden":"腕でかかとを十分に引いていないと、上体の重さが頸椎にかかります。","yonlendirme":"頭は床に触れるだけ、体重は腕に。"},"soylenecekler":["かかとをしっかりつかみましょう。","額をできるだけ膝に近づけてください。","首に圧迫を感じたら、お尻を下ろしましょう。"],"eller":{"nereye":"仙骨とお尻の上。","nasil":"同意を得てから、お尻が上がる動きをやさしく導きます。体重を頭のほうへ押すことは絶対にしないでください。","ne_zaman_degil":"首に不調があるとき、高血圧、めまい、妊娠中、または同意がないとき。"},"kolay":"頭の下にたたんだブランケットを置き、お尻は半分の高さに保ちます。","zor":"お尻を完全に持ち上げ、腕をまっすぐにしてかかとを引き、背骨をさらに丸めます。","dikkat":"首の不調、高血圧、緑内障、めまいを訴える生徒には、頭に体重がかからないチャイルドポーズを提案してください。妊娠中は行いません。不調がある場合は、医師や理学療法士に相談するよう勧めてください。","s":53,"fig":true},{"n":47,"bolum":4,"ad":"キャット＆カウ（マールジャーリャーサナ・ビティラーサナ）","aile":"後屈","seviye":"初級","yogunluk":[1,2,3],"calisan":["脊柱起立筋","腹直筋","前鋸筋"],"dengeleyen":["腹横筋","三角筋","回旋筋腱板（ローテーターカフ）"],"uzayan":["腹直筋","脊柱起立筋"],"ozet":"呼吸に合わせて、背骨を屈曲と伸展の間で動かすことを学びます。クラスの始めに背中を温め、呼吸と動きのつながりをつくるのに最適です。","asamalar":{"giris":"手首を肩の下、膝を股関節の下に置いて四つ這いになります。息を吸いながら骨盤を前傾させて胸を開き（カウ）、息を吐きながら尾骨を内側に入れて背中を丸めます（キャット）。","kalis":"動きは骨盤から始まり、背骨を一つずつ伝って頭まで届きます。手と膝は動かしません。呼吸のペースで5〜10回くり返します。","cikis":"背骨をニュートラルな平らな背中に戻し、数呼吸とどまってから、お尻をかかとに下ろして休みます。"},"hata":{"ne":"頭と首だけで動きをつくってしまう。","neden":"胸椎が硬いと、最も動きやすい首と腰が動きを肩代わりします。","yonlendirme":"尾骨から始めて、頭は最後に。"},"soylenecekler":["息を吸って胸を前へ、息を吐いておへそを背骨へ近づけましょう。","キャットでは、肩甲骨の間を広げましょう。","呼吸のペースで動きましょう。呼吸を止めて待たないでください。"],"eller":{"nereye":"肩甲骨の間と仙骨。","nasil":"同意を得てから、両手を軽く置き、生徒がどこから動きを始めているかを感じられるよう助けます。導いても、こちらで動かさないでください。","ne_zaman_degil":"手首や膝の痛みがあるとき、妊娠後期、または同意がないとき。"},"kolay":"膝の下にたたんだブランケットを置きます。手首に敏感さがあれば前腕をつくか、椅子に座って行います。","zor":"骨盤で円を描き、背骨を横方向や円の動きで探ります。","dikkat":"手首の痛みにはこぶしか前腕のバリエーションを提案し、腰に敏感さがあればカウの動きを小さくしてもらいます。妊娠中はカウでお腹を下に落とさないようにします。痛みがある場合は、医師や理学療法士に相談するよう勧めてください。","s":55,"fig":true},{"n":48,"bolum":4,"ad":"スフィンクスのポーズ（サーランバ・ブジャンガーサナ）","aile":"後屈","seviye":"初級","yogunluk":[1,3,4],"calisan":["脊柱起立筋","僧帽筋中部・下部","前鋸筋"],"dengeleyen":["大殿筋","腹横筋"],"uzayan":["腹直筋","腸腰筋","大胸筋・小胸筋"],"ozet":"前腕の支えを使い、強度の低い背中の伸展を学びます。後屈の準備や、陰ヨガのクラスでの長いキープに適しています。","asamalar":{"giris":"うつ伏せになり、ひじを肩の下に、前腕を平行に前へ置きます。息を吸いながら胸を前上方へすべらせます。恥骨は床に残します。","kalis":"ひじは肩の下、肩は耳から離し、うなじは長く。脚は腰幅でリラックスさせます。5〜10呼吸、陰ヨガのスタイルなら2〜3分キープします。","cikis":"息を吐きながら胸を下ろし、額を腕の上にのせて、お尻を軽く左右に揺らします。"},"hata":{"ne":"肩を耳のほうへすくめてしまう。","neden":"前鋸筋が働いていないと、上体が肩甲骨の間に落ち込みます。","yonlendirme":"前腕で床を押し、胸は前へ。"},"soylenecekler":["前腕でマットを押し、胸を前へ引き出しましょう。","恥骨は床に、お尻はやわらかくしましょう。","腰に詰まりを感じたら、ひじを少し前に出しましょう。"],"eller":{"nereye":"肩甲骨の下端。","nasil":"同意を得てから、肩甲骨をやさしく下へ、腰のほうへ導きます。胸を上に引き上げないでください。","ne_zaman_degil":"腰の痛みを訴えたとき、妊娠中、または同意がないとき。"},"kolay":"ひじを肩より少し前に置くか、胸の下にたたんだブランケットを入れます。","zor":"前腕でしっかり押して胸をさらに前へ運び、脚を床から少し持ち上げます。","dikkat":"腰に敏感さがある場合は高さを下げ、ひじを前に出してもらいます。妊娠中はうつ伏せのポーズの代わりに、四つ這いで胸を開く動きを提案してください。痛みがある場合は、医師や理学療法士に相談するよう勧めてください。","s":56,"fig":true},{"n":49,"bolum":4,"ad":"コブラのポーズ（ブジャンガーサナ）","aile":"後屈","seviye":"初級","yogunluk":[2,4,5],"calisan":["脊柱起立筋","大殿筋","僧帽筋中部・下部"],"dengeleyen":["ハムストリングス","腹横筋"],"uzayan":["腹直筋","大胸筋・小胸筋","腸腰筋"],"ozet":"腕ではなく背中の筋肉の力で胸を持ち上げることを学びます。太陽礼拝では、上向きの犬のポーズよりもコントロールしやすい代わりのポーズです。","asamalar":{"giris":"うつ伏せになり、両手を肩の下に置いて、ひじを体に近づけます。足の甲で床を押し、息を吸いながら背中の筋肉で胸を持ち上げます。","kalis":"恥骨は床に、ひじは軽く曲げて後ろへ、肩は下げます。うなじは長く、視線は前方。3〜5呼吸キープします。","cikis":"息を吐きながら胸をゆっくり床に下ろし、額を床につけて1呼吸休みます。"},"hata":{"ne":"腕で押し上げて、腰を詰めてしまう。","neden":"背中の筋肉が十分に働かないと腕が上体を持ち上げ、伸展が最も動きやすい腰椎に集中します。","yonlendirme":"胸は手ではなく、背中で持ち上げます。"},"soylenecekler":["一瞬、手を床から浮かせてみましょう。そこで上がれる高さが、あなたのコブラです。","足の甲、特に小指側で床を押してください。","ひじは後ろへ、肋骨のほうへ引きましょう。"],"eller":{"nereye":"肩甲骨の下端と仙骨。","nasil":"同意を得てから、肩甲骨を下へ、仙骨をかかとのほうへやさしく導き、腰に長さをつくります。","ne_zaman_degil":"腰の痛みを訴えたとき、妊娠中、または同意がないとき。"},"kolay":"ローコブラ：手を床から少し浮かせ、背中の筋肉だけで胸を数センチ持ち上げます。","zor":"両手を少し前に置き、恥骨を床に残したまま胸をさらに高く上げます。","dikkat":"腰の痛みを訴える生徒にはローコブラにとどまってもらい、手首に敏感さがあれば手にかける体重を減らします。妊娠中はうつ伏せの代わりに、四つ這いで胸を開く動きを提案してください。痛みがある場合は、医師や理学療法士に相談するよう勧めてください。","s":57,"fig":true},{"n":50,"bolum":4,"ad":"上向きの犬のポーズ（ウールドゥヴァ・ムカ・シュヴァーナーサナ）","aile":"後屈","seviye":"中級","yogunluk":[4,5,6],"calisan":["上腕三頭筋","脊柱起立筋","大腿四頭筋","前鋸筋"],"dengeleyen":["大殿筋","回旋筋腱板（ローテーターカフ）"],"uzayan":["腹直筋","腸腰筋","大胸筋・小胸筋"],"ozet":"両手と足の甲だけを床につけ、胸を腕の間から前に開くことを学びます。ヴィンヤサの流れの主要な後屈で、強い腕と活動的な脚が求められます。","asamalar":{"giris":"うつ伏せかチャトランガから、両手を腰の横に置きます。息を吸いながら腕を伸ばし、足の甲に乗りかえて太ももを床から持ち上げます。","kalis":"手首は肩の下、太ももは床から浮き、大腿四頭筋は働いています。胸は腕の間から前へ、肩は後ろ下方へ。1〜3呼吸キープします。","cikis":"息を吐きながらお尻を後ろ上方へ持ち上げ、つま先を返して下向きの犬のポーズへ移るか、膝を床に下ろします。"},"hata":{"ne":"肩を耳にうずめて、腕にぶら下がってしまう。","neden":"前鋸筋と僧帽筋中部・下部が働いていないと、上体が肩の間に落ち込みます。","yonlendirme":"床を押して、胸は腕の間から前へ。"},"soylenecekler":["太ももを床から浮かせ、脚を目覚めさせましょう。","手のひらで床を後ろへ引きずるように押してください。","短めにとどまりましょう。1呼吸で十分です。"],"eller":{"nereye":"生徒の前に立ち、左右の肩の先。","nasil":"同意を得てから、肩をやさしく後ろ下方へ導きます。上体を上に引き上げないでください。","ne_zaman_degil":"手首、肩、腰に痛みがあるとき、妊娠中、または同意がないとき。"},"kolay":"コブラにとどまるか、膝を床につけたまま半分の上向きの犬のポーズを行います。","zor":"キープを5呼吸に延ばし、吐く息ごとに脚をより活動的に保ちながら胸を前へ運びます。","dikkat":"手首、肩、腰の痛みを訴える生徒には、コブラを提案してください。妊娠中は行いません。痛みが続く場合は、医師や理学療法士に相談するよう勧めてください。","s":58,"fig":true},{"n":51,"bolum":4,"ad":"バッタのポーズ（シャラバーサナ）","aile":"後屈","seviye":"初級","yogunluk":[3,5,6],"calisan":["脊柱起立筋","大殿筋","ハムストリングス","僧帽筋中部・下部"],"dengeleyen":["多裂筋","内転筋群"],"uzayan":["腹直筋","大胸筋・小胸筋"],"ozet":"腕の支えをまったく使わずに、背面の筋肉のつながりを強めることを学びます。より深い後屈の前に、背中の筋肉を目覚めさせるために使います。","asamalar":{"giris":"うつ伏せになり、腕を体の横に置いて手のひらを床に向けます。息を吸いながら胸、腕、脚を同時に床から持ち上げます。","kalis":"恥骨と下腹は床に、脚は長く腰幅に、うなじは背骨の延長で、視線は斜め前の床。3〜5呼吸キープし、2〜3回くり返します。","cikis":"息を吐きながら先に脚を、次に胸をゆっくり床に下ろします。頭を横に向け、お尻を揺らしてゆるめます。"},"hata":{"ne":"高さを出すために頭を後ろに倒し、首を詰めてしまう。","neden":"背中の筋肉が十分に強くないと、持ち上げる動きが首の伸展で代償されます。","yonlendirme":"うなじは長く、視線は斜め前の床へ。"},"soylenecekler":["求めるのは高さではなく、長さです。","つま先で、後ろの壁へ伸びていきましょう。","肩甲骨を寄せて、下へ下ろしましょう。"],"eller":{"nereye":"手首の上、またはかかとの後ろ。","nasil":"同意を得てから、伸びる方向を感じてもらうため、手首かかかとをやさしく後ろへ引きます。上に持ち上げないでください。","ne_zaman_degil":"腰の痛みがあるとき、妊娠中、または同意がないとき。"},"kolay":"胸だけ、または片脚だけを持ち上げます。恥骨の下にたたんだブランケットを置きます。","zor":"背中で両手を組んで腕を背中から遠ざけるか、腕を前に伸ばしてスーパーマンのバリエーションを行います。","dikkat":"腰の痛みを訴える生徒には、片脚だけ、または胸だけのバリエーションを提案してください。妊娠中はうつ伏せのポーズを行いません。痛みがある場合は、医師や理学療法士に相談するよう勧めてください。","s":59,"fig":true},{"n":52,"bolum":4,"ad":"弓のポーズ（ダヌラーサナ）","aile":"後屈","seviye":"中級","yogunluk":[5,6,8],"calisan":["大腿四頭筋","大殿筋","脊柱起立筋","ハムストリングス"],"dengeleyen":["回旋筋腱板（ローテーターカフ）","菱形筋"],"uzayan":["大胸筋・小胸筋","腹直筋","腸腰筋"],"ozet":"脚で手を後ろへ押し返すことで、全身を弓のように開くことを学びます。腕は受け身にして、力を脚から生み出すことを示します。","asamalar":{"giris":"うつ伏せになって膝を曲げ、両手で足首の外側をつかみます。息を吸いながら足を手のほうへ後ろに押し、胸と太ももを床から持ち上げます。","kalis":"膝は腰幅を超えず、腕はまっすぐでリラックスし、体重はお腹の上にあります。お腹が圧迫されて呼吸が浅くなるので、落ち着いて3〜5呼吸キープします。","cikis":"息を吐きながら太ももと胸を床に下ろし、足首を離して脚を伸ばし、額を手の上にのせます。"},"hata":{"ne":"腕で足を引っ張り、膝を横に開いてしまう。","neden":"力が脚の押しではなく腕の引きから来ると、肩が前に引かれ、膝のアライメントが失われます。","yonlendirme":"足で手を押し、手は引っ張りません。"},"soylenecekler":["足で手のほうへ、後ろに蹴り出しましょう。","膝は腰幅に保ってください。","呼吸が浅くなったら、高さを下げましょう。"],"eller":{"nereye":"膝のお皿のすぐ上、太ももの外側。","nasil":"同意を得てから、膝が腰幅に保たれるよう、両側からやさしく内側へ導きます。上に持ち上げないでください。","ne_zaman_degil":"腰や膝に痛みがあるとき、妊娠中、食後すぐ、または同意がないとき。"},"kolay":"足首にストラップをかけてストラップを持つか、片脚ずつ半分の弓のポーズを行います。","zor":"手を逆手（親指が外側）に持ちかえ、ひじを上に向けます。","dikkat":"腰や膝の痛みを訴える生徒には、半分の弓のポーズかバッタのポーズを提案してください。妊娠中は行いません。痛みが続く場合は、医師や理学療法士に相談するよう勧めてください。","s":60,"fig":true},{"n":53,"bolum":4,"ad":"橋のポーズ（セツ・バンダ・サルヴァーンガーサナ）","aile":"後屈","seviye":"中級","yogunluk":[3,5,7],"calisan":["大殿筋","ハムストリングス","脊柱起立筋"],"dengeleyen":["内転筋群","腹横筋"],"uzayan":["腸腰筋","大腿四頭筋","大胸筋・小胸筋"],"ozet":"足で床を押して骨盤を持ち上げ、殿筋で股関節の伸展を生み出すことを学びます。車輪のポーズの準備として、またはサポート付きでリストラティブとして使います。","asamalar":{"giris":"仰向けになって膝を曲げ、足を腰幅に開き、かかとを指先に近づけます。息を吸いながら足で床を押し、骨盤を背骨一つずつ持ち上げます。","kalis":"膝は腰幅で足首の真上に。体重は首ではなく肩と足にかかります。頭はまっすぐ保ち、5〜8呼吸キープします。","cikis":"息を吐きながら背骨を上背部から一つずつ床に下ろします。最後に仙骨を床につけます。"},"hata":{"ne":"骨盤を持ち上げるときに、膝が開いてしまう。","neden":"内転筋群が働かず、股関節の外旋筋が優位になると、持ち上げる途中で膝が外に逃げます。","yonlendirme":"膝は腰幅に。"},"soylenecekler":["足裏の四隅で床を押しましょう。","頭は動かさず、視線は天井へ向けましょう。","膝の間にブロックをはさんでいるように感じてください。"],"eller":{"nereye":"膝の外側、またはサポートとして仙骨の下。","nasil":"同意を得てから、膝をやさしく互いのほうへ導きます。骨盤を上に引き上げないでください。","ne_zaman_degil":"首の痛みがあるとき、妊娠後期、または同意がないとき。"},"kolay":"仙骨の下にブロックを置き、サポート付きの橋のポーズで休みます。","zor":"片脚の橋のポーズ：骨盤の高さを保ったまま、片脚を天井へ伸ばします。","dikkat":"首に敏感さがある場合は肩の下にたたんだブランケットを置き、頭を動かさないようにします。膝の痛みがある場合は、かかとを少し遠くに置きます。痛みがある場合は、医師や理学療法士に相談するよう勧めてください。","s":61,"fig":true},{"n":54,"bolum":4,"ad":"車輪のポーズ（ウールドゥヴァ・ダヌラーサナ）","aile":"後屈","seviye":"上級","yogunluk":[6,8,9],"calisan":["上腕三頭筋","大殿筋","脊柱起立筋","三角筋"],"dengeleyen":["回旋筋腱板（ローテーターカフ）","前鋸筋","内転筋群"],"uzayan":["大胸筋・小胸筋","腹直筋","腸腰筋"],"ozet":"手と足で床を押して体の前面全体を開く、完全な後屈です。肩の柔軟性、股関節の伸展、腕の力を同時に必要とするため、クラスのピークで十分にウォームアップしてから教えます。","asamalar":{"giris":"仰向けで膝を曲げ、足は腰幅に。指先が肩を向くように両手を耳の横に置きます。息を吸いながらまず骨盤を持ち上げて頭頂を床につけ、もう一度息を吸って腕を伸ばします。","kalis":"足は平行、膝は腰幅、ひじは肩幅。体重は手と足に分散します。3〜5呼吸キープします。","cikis":"あごを胸に近づけ、息を吐きながらひじを曲げて、まず上背部、次に骨盤を一つずつ床に下ろします。膝を胸に引き寄せます。"},"hata":{"ne":"ひじを横に開いたまま、頭頂で止まってしまう。","neden":"肩の屈曲と上腕三頭筋の力が不足していると、ひじが外に逃げて腕を伸ばしきれません。","yonlendirme":"ひじは平行に、胸は後ろの壁へ。"},"soylenecekler":["まず頭頂を床につけ、ひじを平行にしてから押し上げましょう。","足は平行に、つま先が外に逃げないようにしましょう。","胸を両手の間から、後ろの壁へ送りましょう。"],"eller":{"nereye":"生徒の頭側に立ち、肩甲骨の下。","nasil":"同意を得たうえで、生徒が望み、準備のポーズを済ませている場合に限り、肩甲骨の下をやさしく上へ導きます。体重をすべて持ち上げることは絶対にしないでください。","ne_zaman_degil":"手首、肩、腰、首に痛みがあるとき、妊娠中、頭頂で不安定なとき、または同意がないとき。"},"kolay":"橋のポーズにとどまるか、壁に立てかけた2つのブロックに手を置いて車輪のポーズを練習します。","zor":"足を手のほうへ歩かせるか、骨盤の高さを保ったまま片脚を天井へ伸ばします。","dikkat":"手首、肩、腰、首の痛みを訴える生徒には、橋のポーズを提案してください。高血圧の場合や妊娠中は行いません。痛みが続く場合は、医師や理学療法士に相談するよう勧めてください。","s":62,"fig":true},{"n":55,"bolum":4,"ad":"ラクダのポーズ（ウシュトラーサナ）","aile":"後屈","seviye":"中級","yogunluk":[5,6,8],"calisan":["大殿筋","脊柱起立筋","ハムストリングス"],"dengeleyen":["腹直筋","内転筋群"],"uzayan":["大腿四頭筋","腸腰筋","大胸筋・小胸筋"],"ozet":"膝立ちでお尻を前に保ったまま、胸を後ろに開くことを学びます。太ももの前と胸を大きく開くポーズで、段階を追って導入する必要があります。","asamalar":{"giris":"膝を腰幅に開き、お尻を膝の上に置いて、両手を仙骨に当てます。息を吸いながら胸骨を引き上げ、息を吐きながら片手ずつかかとへ下ろします。","kalis":"お尻は膝の上に保ち、胸は上へ、腰は長く。首はニュートラルか少し後ろへ。3〜5呼吸キープします。","cikis":"両手を仙骨に戻し、あごを胸に近づけ、息を吸いながら胸から起き上がります。その後チャイルドポーズで休みます。"},"hata":{"ne":"お尻をかかとのほうへ後ろに落としてしまう。","neden":"腸腰筋と大腿四頭筋が硬いと骨盤が後ろに逃げ、伸展が腰椎に集中します。","yonlendirme":"お尻は膝の上、胸は上へ。"},"soylenecekler":["まず上へ、それから後ろへ向かいましょう。","手をかかとまで下ろさなくてもかまいません。仙骨に置いたままで大丈夫です。","頭を後ろに倒す前に、まず胸を開きましょう。"],"eller":{"nereye":"仙骨と胸郭の後ろ下部。","nasil":"同意を得てから、生徒の後ろに立ち、肋骨の後ろをやさしく上へ導き、お尻が前に保たれるよう寄り添います。下へ押さないでください。","ne_zaman_degil":"腰や首に痛みがあるとき、めまい、妊娠中、または同意がないとき。"},"kolay":"つま先を立ててかかとを高くするか、かかとの横にブロックを置きます。","zor":"足の甲を床に平らにつけ、手をかかとに置いたまま胸をさらに高く上げます。","dikkat":"腰や首の痛みを訴える生徒には、手を腰に置いた準備の段階にとどまってもらいます。めまいがあれば、ゆっくり出るよう伝えます。妊娠中は行いません。不調が続く場合は、医師や理学療法士に相談するよう勧めてください。","s":63,"fig":true},{"n":56,"bolum":4,"ad":"手を腰に置いたラクダの準備","aile":"後屈","seviye":"初級","yogunluk":[2,4,5],"calisan":["大殿筋","脊柱起立筋","僧帽筋中部・下部"],"dengeleyen":["腹直筋","腹横筋"],"uzayan":["大腿四頭筋","腸腰筋"],"ozet":"ラクダのポーズの最初の段階です。手は腰に、お尻は前に、胸は上に。後屈を腰ではなく上背部から始めることを生徒に教えます。","asamalar":{"giris":"膝を腰幅に開き、お尻を膝の上に置きます。指先を下に向けて両手を仙骨に当て、息を吸いながらひじを寄せて胸を引き上げます。","kalis":"お尻は前で膝の上、胸は上で少し後ろへ、あごは軽く引きます。腰は長く保ち、5呼吸キープします。","cikis":"息を吐きながら上体をまっすぐに戻し、手を下ろしてお尻をかかとにゆだねます。"},"hata":{"ne":"胸を持ち上げないまま、腰から後ろに折れてしまう。","neden":"胸椎の伸展が限られていると、曲がりが腰椎に集中します。","yonlendirme":"ひじを寄せて、胸は天井へ。"},"soylenecekler":["両手で仙骨を下へ、尾骨のほうへすべらせましょう。","後ろでひじを寄せてください。","ここにとどまるのも、立派なラクダのポーズです。"],"eller":{"nereye":"肩甲骨のすぐ下。","nasil":"同意を得てから、手のひらで上背部をやさしく上前方へ導き、胸が開くのに寄り添います。","ne_zaman_degil":"膝や腰に痛みがあるとき、または同意がないとき。"},"kolay":"膝の下にたたんだブランケットを置き、後屈をごく小さくします。","zor":"片腕を上から後ろへ伸ばし、片手で同じ側のかかとに触れます。","dikkat":"膝に敏感さがある場合は膝の下にサポートを置きます。腰の痛みがある場合は、動きを胸を引き上げるだけにとどめます。痛みがある場合は、医師や理学療法士に相談するよう勧めてください。","s":64,"fig":true},{"n":57,"bolum":4,"ad":"魚のポーズ（マツヤーサナ）","aile":"後屈","seviye":"初級","yogunluk":[2,4,5],"calisan":["脊柱起立筋","僧帽筋中部・下部","菱形筋"],"dengeleyen":["大腿四頭筋","上腕三頭筋"],"uzayan":["大胸筋・小胸筋","胸鎖乳突筋","腹直筋"],"ozet":"仰向けで胸郭を上に開くことを学びます。肩立ちのカウンターポーズとして、またはブロックを使ったサポート付きの胸を開くポーズとして使います。","asamalar":{"giris":"仰向けになり、手のひらを下にして両手をお尻の下に入れます。息を吸いながら前腕で床を押し、胸を持ち上げて頭頂をそっと床に下ろします。","kalis":"体重は前腕とひじにあり、頭にはごくわずか。脚は長く伸ばして働かせます。5呼吸キープし、呼吸を胸に満たします。","cikis":"前腕で押して頭を床から持ち上げ、あごを胸に近づけ、息を吐きながら背中をゆっくり床に下ろします。"},"hata":{"ne":"体重をすべて頭と首にかけてしまう。","neden":"前腕と背中の筋肉が胸を支えていないと、負担が頸椎にかかります。","yonlendirme":"胸は上へ、頭は軽く。"},"soylenecekler":["ひじで床を押し、胸を天井へ開きましょう。","頭の下に紙が一枚あるつもりで、重みをかけないでください。","首に圧迫を感じたら、頭をブロックにのせましょう。"],"eller":{"nereye":"頭の後ろ、または肩甲骨の下のブロック。","nasil":"同意を得てから、手のひらで頭の後ろを支え、首にかかる負担を減らします。胸を上に引き上げないでください。","ne_zaman_degil":"首の痛みがあるとき、めまい、または同意がないとき。"},"kolay":"肩甲骨の下と頭の下にそれぞれブロックを置き、サポート付きの魚のポーズを行います。","zor":"脚を床から45度持ち上げ、腕を太ももと平行に伸ばします。","dikkat":"首の不調を訴える生徒には頭を支えるか、頭が床で休めるサポート付きのバリエーションを提案してください。高血圧やめまいがある場合は注意します。痛みがある場合は、医師や理学療法士に相談するよう勧めてください。","s":65,"fig":true},{"n":58,"bolum":4,"ad":"ブロックを使ったラクダのポーズ","aile":"後屈","seviye":"初級","yogunluk":[3,5,6],"calisan":["大殿筋","脊柱起立筋","上腕三頭筋"],"dengeleyen":["腹直筋","内転筋群"],"uzayan":["大腿四頭筋","腸腰筋","大胸筋・小胸筋"],"ozet":"かかとの横に置いたブロックのおかげで、より短い距離でラクダのポーズを学べます。お尻を膝の上に保つことを身につける、最も安全な方法です。","asamalar":{"giris":"膝を腰幅に開き、2つのブロックを一番高い向きで足首の外側に置きます。両手を仙骨に当て、息を吸いながら胸を引き上げ、息を吐きながら片手ずつブロックへ下ろします。","kalis":"お尻は膝の上、腕はまっすぐでブロックを押し、胸は上へ。首はニュートラル。5呼吸キープします。","cikis":"片手ずつ仙骨に戻し、息を吸いながら胸から起き上がって、チャイルドポーズで休みます。"},"hata":{"ne":"ブロックに届かせるために、お尻を後ろに落としてしまう。","neden":"太ももの前と股関節屈筋群が限界に達すると、骨盤が後ろに逃げます。","yonlendirme":"お尻は前に。ブロックのほうから近づいてきます。"},"soylenecekler":["両手でブロックを押し、胸を持ち上げましょう。","必要なら、ブロックをもう一段高くしてください。","太ももは床と垂直に保ちましょう。"],"eller":{"nereye":"太ももの前、お尻のすぐ下。","nasil":"同意を得てから、太ももをやさしく前へ導き、お尻が膝の上に保たれるよう助けます。","ne_zaman_degil":"膝や腰に痛みがあるとき、妊娠中、または同意がないとき。"},"kolay":"ブロックを壁に立てかけるか、椅子のようにより高いサポートを使います。","zor":"ブロックを一番低い向きにし、少しずつブロックなしでかかとへ移ります。","dikkat":"膝の痛みがある場合は膝の下にブランケットを置き、腰や首の痛みがある場合は手を腰に置くバリエーションに戻ります。妊娠中は行いません。痛みが続く場合は、医師や理学療法士に相談するよう勧めてください。","s":66,"fig":true},{"n":59,"bolum":4,"ad":"サイドプランクからのチャマトカーラーサナ","aile":"後屈","seviye":"中級","yogunluk":[4,6,7],"calisan":["中殿筋・小殿筋","大殿筋","三角筋","前鋸筋"],"dengeleyen":["回旋筋腱板（ローテーターカフ）","腹斜筋"],"uzayan":["大胸筋・小胸筋","腸腰筋","大腿四頭筋"],"ozet":"サイドプランクから片足を後ろに踏み込み、胸を天井に向けることを学びます。支える肩の安定と体の前面の開きを組み合わせた、流れるような後屈です。","asamalar":{"giris":"右手でサイドプランクになります。息を吸いながら上の脚の膝を曲げ、足を下の脚の後ろに踏み込んで、お尻を持ち上げます。","kalis":"支える手は肩の少し前、指はしっかり働かせます。お尻は高く、胸は天井に開き、上の腕は頭の上へ伸びます。3〜5呼吸キープします。","cikis":"息を吐きながらお尻を下ろし、上の手を床に戻して下向きの犬のポーズに戻ります。反対側へ移ります。"},"hata":{"ne":"支える肩に沈み込んでしまう。","neden":"前鋸筋と回旋筋腱板（ローテーターカフ）が働いていないと、上体の重さが肩関節にぶら下がります。","yonlendirme":"床を押し、肩は耳から遠くへ。"},"soylenecekler":["手のひら全体、特に人さし指の付け根で床を押しましょう。","お尻を天井へ持ち上げると、胸は自然に開きます。","上の腕で、長い弧を描きましょう。"],"eller":{"nereye":"腰骨の横。","nasil":"同意を得てから、お尻が上がるのに寄り添うよう、やさしく上へ導きます。肩のコントロールは生徒に任せます。","ne_zaman_degil":"手首や肩に痛みがあるとき、肩の脱臼歴があるとき、妊娠中、または同意がないとき。"},"kolay":"下の膝を床につけたハーフのサイドプランクから、小さく胸を開くことから始めます。","zor":"片脚の下向きの犬のポーズから回転して流れの中で入り、このポーズから車輪のポーズへの移行に挑戦します。","dikkat":"手首や肩の痛み、肩の脱臼歴を訴える生徒には、ハーフのサイドプランクのバリエーションを提案してください。妊娠中は行いません。痛みがある場合は、医師や理学療法士に相談するよう勧めてください。","s":67,"fig":true},{"n":60,"bolum":4,"ad":"後屈を加えたローランジ","aile":"後屈","seviye":"初級","yogunluk":[3,5,6],"calisan":["大腿四頭筋","大殿筋","脊柱起立筋"],"dengeleyen":["中殿筋・小殿筋","内転筋群","腹横筋"],"uzayan":["腸腰筋","大腿四頭筋","腹直筋"],"ozet":"ローランジで腕を上に伸ばし、胸を後ろに開いて、後ろ脚の股関節屈筋群を伸ばすことを学びます。深い後屈の前のよいウォームアップです。","asamalar":{"giris":"右足を前に、左膝を床につけてローランジになります。息を吸いながら腕を上に伸ばし、息を吐きながら骨盤を少し前へすべらせて胸を後ろに開きます。","kalis":"前の膝は足首の上、後ろの太ももは長く、下腹は軽く働かせます。胸は上へ、腰は長く。5呼吸キープします。","cikis":"息を吐きながら両手を前足の両側に下ろし、後ろのつま先を立てて下向きの犬のポーズへ移ります。反対側へ移ります。"},"hata":{"ne":"胸を開かないまま、腰から後ろに折れてしまう。","neden":"股関節屈筋群が硬いと骨盤が前傾し、後屈が腰椎に集中します。","yonlendirme":"尾骨は下へ、胸は上へ。"},"soylenecekler":["後ろの膝の下に、ブランケットを置いてもかまいません。","尾骨を床のほうへ伸ばし、鼠径部の前を開きましょう。","腕は上に、前の肋骨は内側へ引き込みましょう。"],"eller":{"nereye":"後ろ脚側の腰骨の前と仙骨。","nasil":"同意を得てから、仙骨をやさしく下へ導きながら、腰骨を前に向けます。骨盤を前に押さないでください。","ne_zaman_degil":"膝や腰に痛みがあるとき、または同意がないとき。"},"kolay":"両手を前の太ももか2つのブロックに置き、胸をまっすぐ起こすだけにします。","zor":"後ろの膝を曲げ、同じ側の手で後ろの足をつかんで、太ももの前の伸びを深めます。","dikkat":"膝に敏感さがある場合は、後ろの膝の下にサポートを置きます。腰の痛みを訴える生徒には後屈を小さくし、手を腰に当てたままにするよう提案してください。痛みがある場合は、医師や理学療法士に相談するよう勧めてください。","s":68,"fig":true},{"n":61,"bolum":4,"ad":"逆テーブルのポーズ（アルダ・プールヴォッターナーサナ）","aile":"後屈","seviye":"初級","yogunluk":[3,4,6],"calisan":["大殿筋","ハムストリングス","上腕三頭筋","僧帽筋中部・下部"],"dengeleyen":["回旋筋腱板（ローテーターカフ）","菱形筋","大腿四頭筋"],"uzayan":["大胸筋・小胸筋","三角筋","腸腰筋"],"ozet":"両手と両足で骨盤を持ち上げ、テーブルのような平らな胴体をつくることを学びます。前屈やチャトランガの後に、肩の前側を開くカウンターポーズです。","asamalar":{"giris":"膝を曲げて座り、指先を前に向けて両手をお尻の後ろに置きます。息を吸いながら手と足で床を押し、骨盤を膝と同じ高さまで持ち上げます。","kalis":"手首は肩の下、膝は足首の上。胴体は床と平行なテーブルのように。うなじは長く、頭はニュートラルか少し後ろへ。5呼吸キープします。","cikis":"息を吐きながら骨盤をゆっくり床に下ろし、手を離して手首を振ってゆるめます。"},"hata":{"ne":"お尻を持ち上げきれず、骨盤が下に垂れてしまう。","neden":"大殿筋が働いていないと股関節の伸展が完了せず、負担が肩にかかります。","yonlendirme":"お尻を引き締めて、おへそは天井へ。"},"soylenecekler":["足の裏で床を押しましょう。","胸をあごのほうへ持ち上げてください。","首に違和感があれば、あごを軽く引いておきましょう。"],"eller":{"nereye":"仙骨の下。","nasil":"同意を得てから、手のひらで仙骨をやさしく上へ支え、骨盤のあるべき高さを示します。持ち上げないでください。","ne_zaman_degil":"手首や肩に痛みがあるとき、首に不調があるとき、または同意がないとき。"},"kolay":"指先を横に向けるか、こぶしで支えて、短時間とどまります。","zor":"片脚を床と平行に伸ばして、片脚の逆テーブルを行います。","dikkat":"手首や肩の痛みを訴える生徒には、短いキープか橋のポーズを提案してください。首に敏感さがある場合は、頭を後ろに倒さないようにします。痛みがある場合は、医師や理学療法士に相談するよう勧めてください。","s":69,"fig":true},{"n":62,"bolum":4,"ad":"逆プランク（プールヴォッターナーサナ）","aile":"後屈","seviye":"中級","yogunluk":[4,6,7],"calisan":["大殿筋","ハムストリングス","上腕三頭筋","大腿四頭筋"],"dengeleyen":["回旋筋腱板（ローテーターカフ）","僧帽筋中部・下部","内転筋群"],"uzayan":["大胸筋・小胸筋","三角筋","前脛骨筋"],"ozet":"脚をまっすぐにし、足裏を床へ伸ばしながら、体の前面全体を一直線に持ち上げることを学びます。座位前屈の自然なカウンターポーズです。","asamalar":{"giris":"脚を前に伸ばして座り、指先を足のほうへ向けて両手をお尻の後ろに置きます。息を吸いながら手とかかとで床を押し、骨盤を持ち上げます。","kalis":"手首は肩の下、脚はまっすぐそろえ、足裏は床のほうへ。お尻は肩と一直線に。3〜5呼吸キープします。","cikis":"息を吐きながら骨盤をゆっくり床に下ろし、短い座位前屈で背中のバランスを整えます。"},"hata":{"ne":"お尻が落ちて、体がくの字に曲がってしまう。","neden":"殿筋とハムストリングスが股関節を完全な伸展に保てないと、骨盤が下に垂れます。","yonlendirme":"足裏は床へ、おへそは天井へ。"},"soylenecekler":["足の裏をマットのほうへ伸ばしましょう。","お尻を肩と同じラインまで持ち上げてください。","両手で床を押し、胸を開きましょう。"],"eller":{"nereye":"仙骨の下と肩の前側。","nasil":"同意を得てから、仙骨をやさしく上へ支え、肩を後ろへ導きます。生徒の体重を代わりに支えることはしないでください。","ne_zaman_degil":"手首、肩、首に不調があるとき、妊娠中、または同意がないとき。"},"kolay":"逆テーブルから始めるか、両手の下にブロックを置きます。","zor":"骨盤の高さを保ったまま、片脚を天井へ持ち上げます。","dikkat":"手首や肩の痛みを訴える生徒には、逆テーブルを提案してください。首に不調がある場合は頭を後ろに倒さず、あごを引いたままにします。痛みが続く場合は、医師や理学療法士に相談するよう勧めてください。","s":70,"fig":true},{"n":63,"bolum":5,"ad":"座位のねじり（アルダ・マツイェーンドラーサナ）","aile":"ねじり","seviye":"初級","yogunluk":[2,4,5],"calisan":["腹斜筋","多裂筋"],"dengeleyen":["脊柱起立筋","腹横筋"],"uzayan":["梨状筋","中殿筋・小殿筋"],"ozet":"座って行う代表的なねじりのポーズです。背骨をまず伸ばしてからねじる順序を学べます。クラスでは前屈のあとに背中をニュートラルに戻すつなぎとして役立ちます。","asamalar":{"giris":"右足を左膝の外側に置き、両方の坐骨を床に下ろします。息を吸いながら背骨を頭頂方向へ伸ばし、息を吐きながらおへそから右へねじります。","kalis":"骨盤を安定させ、左右の坐骨に均等に体重をのせます。吸う息ごとに少し伸び、吐く息でねじりを保ちます。5〜8呼吸キープします。","cikis":"息を吸いながら、まず頭、次に胸、最後におへそを正面に戻します。脚を伸ばし、反対側に移る前に1呼吸休みます。"},"hata":{"ne":"腕をてこにしてねじりを無理に深めること。","neden":"腕で膝を押すと、回旋が胸郭ではなく肩から生まれ、最も回旋に向かない腰椎に過剰な負担がかかります。","yonlendirme":"まず伸びて、それからねじります。"},"soylenecekler":["坐骨を床に根づかせ、頭のてっぺんを天井へ伸ばしましょう。","おへそからねじり始め、胸が続き、頭は最後についてきます。","腕はねじりを支えるだけにして、腕の力でねじらないようにしましょう。"],"eller":{"nereye":"片手は肩甲骨の間の背骨の後ろ、もう片方の手はねじる側の肩の前に置きます。","nasil":"同意を得てから、後ろの手で上方向へ軽く伸びる方向を示し、前の手で肩がひらくよう促すだけにします。ねじりを指導者が深めることはしないでください。","ne_zaman_degil":"生徒の同意が得られていない場合、腰や背中の痛みを訴えている場合、妊娠中の場合は触れないでください。"},"kolay":"下側の脚を伸ばし、坐骨の下にたたんだブランケットを敷きます。腕で膝を抱えるようにします。","zor":"下側の腕を膝の外側から通し、背中側から回した手とつなぎます（半バインドのねじり）。胸はひらいたまま保ちます。","dikkat":"腰椎椎間板ヘルニアの既往がある場合、最近お腹の手術を受けた場合、妊娠中は、ねじりを浅くするか、ひらいたねじりに変えてください。痛みがある場合は、医師や理学療法士に相談するよう勧めてください。","s":72,"fig":true},{"n":64,"bolum":5,"ad":"簡単な座位のねじり","aile":"ねじり","seviye":"初級","yogunluk":[1,3,4],"calisan":["腹斜筋","多裂筋"],"dengeleyen":["脊柱起立筋","横隔膜"],"uzayan":["菱形筋","腰方形筋"],"ozet":"あぐらで行う最もシンプルなねじりです。初心者に、回旋が胸郭から生まれる感覚をつかんでもらうのに最適です。クラスの始めのウォームアップとしても使えます。","asamalar":{"giris":"あぐらで座り、右手を左膝の上に、左手を後ろの床に置きます。息を吸いながら背骨を伸ばし、息を吐きながらゆっくり左へねじります。","kalis":"肩を耳から遠ざけ、あごは床と平行に保ちます。吸う息で胸郭を左右に広げます。片側5呼吸ずつキープします。","cikis":"息を吸いながら正面に戻り、脚の組み方を替えて反対側も行います。"},"hata":{"ne":"あごでねじろうとして首に無理をかけること。","neden":"胸郭が動かないと、回旋が最も動きやすい首に移り、首の筋肉が緊張します。","yonlendirme":"胸がねじれ、頭はそれに付き添うだけです。"},"soylenecekler":["少し背が高くなったと感じるまで待ってから、ねじりましょう。","息を吸いながら、肋骨を左右に広げましょう。","視線はやわらかく、あごの力を抜いてください。"],"eller":{"nereye":"生徒の後ろに立ち、両手を両肩の上に、または片手をねじる側の肩甲骨の上に置きます。","nasil":"同意を得てから、肩を下げて広く保つよう促す軽いタッチで十分です。ねじる方向に圧をかけないでください。","ne_zaman_degil":"同意が得られていない場合、首の痛みを訴えている場合、めまいがある場合は触れないでください。"},"kolay":"坐骨の下にブロックかブランケットを敷き、背中を壁にあずけてねじります。","zor":"両手を頭の後ろで組み、肘を横にひらいたまま、腕の支えなしでねじります。","dikkat":"首がデリケートな生徒は、頭を正面に残してください。痛みがある場合は、医師や理学療法士に相談するよう勧めてください。","s":73,"fig":true},{"n":65,"bolum":5,"ad":"マリーチのポーズ（マリーチャーサナⅢ）","aile":"ねじり","seviye":"中級","yogunluk":[3,5,7],"calisan":["腹斜筋","多裂筋","回旋筋腱板（ローテーターカフ）"],"dengeleyen":["脊柱起立筋","腹横筋"],"uzayan":["大殿筋","大胸筋・小胸筋"],"ozet":"片脚を伸ばし、もう片方の膝を曲げて座る深いねじりです。骨盤と胸郭を分けて動かすことと、コントロールされた回旋を学べます。","asamalar":{"giris":"左脚を伸ばし、右足を右の坐骨の前に置きます。息を吸いながら左腕を上へ伸ばし、息を吐きながら左肘を右膝の外側にかけて右へねじります。","kalis":"伸ばした脚のつま先は天井に向け、骨盤が後ろに倒れないようにします。吸う息ごとに伸び、吐く息で胸をひらきます。5呼吸キープします。","cikis":"息を吸いながらバインドや腕をほどき、まず胸、次に頭を正面に戻します。両脚を伸ばして1呼吸休みます。"},"hata":{"ne":"骨盤を後ろに倒し、背中を丸めること。","neden":"ハムストリングスやお尻の後ろ側が硬いと骨盤が後傾し、腰椎が丸まってねじりを補おうとします。","yonlendirme":"まず坐骨、それからねじりです。"},"soylenecekler":["伸ばした脚のかかとを前へ押し出しましょう。","肘は膝に添えるだけで、押さないようにしてください。","胸の前を広げ、肩を後ろに落ち着けましょう。"],"eller":{"nereye":"片手は仙骨のすぐ上、もう片方の手はねじる側の肩甲骨の外縁に置きます。","nasil":"同意を得てから、仙骨の手で前上方へ軽く方向を示し、肩甲骨の手は肩が後ろに落ち着くことを思い出させるだけにします。","ne_zaman_degil":"同意が得られていない場合、生徒がバインドを無理に組もうとしている場合、肩や腰に痛みがある場合、妊娠中の場合は触れないでください。"},"kolay":"坐骨の下にブランケットを敷き、膝を抱えてねじります。バインドはしません。","zor":"腕を膝のまわりと背中の後ろで組み、胸をひらいたまま視線を後ろの肩越しに送ります。","dikkat":"肩が不安定な生徒はバインドを省いてください。腰やお尻に痛みがある場合は、医師や理学療法士に相談するよう勧めてください。","s":74,"fig":true},{"n":66,"bolum":5,"ad":"仰向けのねじり（スプタ・マツイェーンドラーサナ）","aile":"ねじり","seviye":"初級","yogunluk":[1,3,4],"calisan":["腹斜筋","横隔膜"],"dengeleyen":["腹横筋","大胸筋・小胸筋"],"uzayan":["中殿筋・小殿筋","大胸筋・小胸筋","腰方形筋"],"ozet":"仰向けで重力にゆだねる受動的なねじりです。クラスの終わり、クロージングに入る前に背骨をリラックスさせるために使います。","asamalar":{"giris":"仰向けになり、右膝を胸に引き寄せます。息を吐きながら右膝を左側へ下ろし、右腕を肩の高さで横に広げます。","kalis":"右肩を床に近づけたまま、膝を無理に床へ押しつけないようにします。長く穏やかな呼吸で8〜10呼吸、または1分キープします。","cikis":"息を吸いながら膝を天井に戻し、脚を伸ばします。反対側に移る前に、両脚を伸ばして長めに1呼吸休みます。"},"hata":{"ne":"膝を床につけるために肩を床から浮かせること。","neden":"胸や肩の前側が硬いと、膝を下ろす動きを反対側の肩を床から離すことで補ってしまいます。","yonlendirme":"肩は床に、膝は止まったところが正解です。"},"soylenecekler":["膝の下にブロックを置いてもかまいません。ゆだねやすくなります。","吐く息ごとに、胸が少しずつ床に落ち着いていくのを感じましょう。","ここでは何もしなくて大丈夫です。ただ呼吸を続けてください。"],"eller":{"nereye":"広げた腕側の肩の前、または曲げた膝の外側に置きます。","nasil":"同意を得てから、肩の前にごく軽く、床方向への安定した重さをのせます。膝を下へ押さないでください。","ne_zaman_degil":"同意が得られていない場合、人工股関節、仙腸関節のデリケートさ、妊娠がある場合は触れないでください。"},"kolay":"曲げた膝の下にブロックやクッションを置きます。両膝をそろえて曲げたままでもかまいません。","zor":"上の脚をまっすぐ伸ばして反対の手で足をつかみ、視線を広げた腕の方へ向けます。","dikkat":"妊娠中は仰向けの時間を短くするか、横向きに変えてください。腰に痛みがある場合は、医師や理学療法士に相談するよう勧めてください。","s":75,"fig":true},{"n":67,"bolum":5,"ad":"ねじったローランジ（パリヴリッタ・アンジャネーヤーサナ）","aile":"ねじり","seviye":"中級","yogunluk":[3,5,7],"calisan":["腹斜筋","大腿四頭筋","大殿筋"],"dengeleyen":["中殿筋・小殿筋","腹横筋","内転筋群"],"uzayan":["腸腰筋"],"ozet":"ローランジで胸の前で手を合わせて行うねじりです。バランス、股関節の安定、回旋をまとめて練習できます。","asamalar":{"giris":"右足を前にしてローランジに入り、後ろの膝を床につけます。胸の前で手を合わせ、息を吸いながら伸び、息を吐きながら左肘を右膝の外側にかけます。","kalis":"前の膝は足首の真上、骨盤は正面に向けたままにします。手のひら同士を押し合い、胸をひらきます。5呼吸キープします。","cikis":"息を吸いながら上体を正面に戻し、両手を前足の両側に置いて後ろの膝を解放し、反対側に移ります。"},"hata":{"ne":"前の膝が内側に倒れること。","neden":"ねじる間に前脚側の股関節外旋筋や中殿筋・小殿筋がゆるむと、膝が内側へ入ります。","yonlendirme":"膝は足首の上、太ももは安定させます。"},"soylenecekler":["後ろの膝の下はやわらかく保ちましょう。ブランケットを敷いてもかまいません。","手のひらを押し合い、胸を親指の方へひらきましょう。","前の膝は動かさず、上体だけをねじりましょう。"],"eller":{"nereye":"前の膝の外側と、後ろ脚側の腰骨の横に置きます。","nasil":"同意を得てから、膝にはごく軽く外向きの方向を示し、骨盤には正面を保つための接触だけにします。上体をねじらないでください。","ne_zaman_degil":"同意が得られていない場合、後ろの膝に痛みがある場合、生徒が不安定な場合や妊娠中の場合は触れないでください。"},"kolay":"肘をかける代わりに両手を前の太ももに置き、胸を軽く回すだけにします。","zor":"後ろの膝を床から上げてハイランジで行うか、腕をひらいて片手を床に、もう片手を天井へ伸ばします。","dikkat":"膝や股関節に不安のある生徒は、後ろの膝をしっかり支えてください。痛みがある場合は、医師や理学療法士に相談するよう勧めてください。","s":76,"fig":true},{"n":68,"bolum":5,"ad":"ねじった体側を伸ばすポーズ（パリヴリッタ・パールシュヴァコーナーサナ）","aile":"ねじり","seviye":"上級","yogunluk":[4,6,8],"calisan":["腹斜筋","大腿四頭筋","大殿筋"],"dengeleyen":["内転筋群","腹横筋","中殿筋・小殿筋"],"uzayan":["腸腰筋","腓腹筋・ヒラメ筋"],"ozet":"足を大きく開いた姿勢で、上体を前の太ももの上へねじる力強い立位のねじりです。脚の筋力、バランス、そして長い背骨のままねじる力が求められます。","asamalar":{"giris":"大きなランジで右膝を曲げ、後ろのかかとを上げます。息を吸いながら伸び、息を吐きながら上体を右の太ももの上へねじり、左手を足の外側の床かブロックに置きます。","kalis":"後ろ脚は力強くまっすぐ、前の膝は足首の真上に保ちます。頭頂から後ろのかかとまで一本の線をイメージします。5呼吸キープします。","cikis":"息を吸いながら上の腕を下ろして上体を正面に戻し、両手を床について後ろ足を前へ運び、前屈で休みます。"},"hata":{"ne":"床に手を届かせようとして背中を丸め、胸を太ももに落とすこと。","neden":"股関節の屈曲や胸椎の回旋が足りないまま手を床につけようとすると、腰を曲げることで補ってしまいます。","yonlendirme":"床よりブロック、ねじりより長さです。"},"soylenecekler":["後ろのかかとを後方へ押し、脚を働かせ続けましょう。","胸を天井へひらき、下の腕は支えるだけにしましょう。","呼吸が浅くなったら、一段階やさしいかたちに戻りましょう。"],"eller":{"nereye":"後ろ脚側のお尻の横と、上側の肩の後ろに置きます。","nasil":"同意を得てから、後ろのお尻に軽く下後方への方向を示し、肩にはひらく方向を示すだけにします。ねじる力を加えることは決してしないでください。","ne_zaman_degil":"同意が得られていない場合、生徒がバランスを崩している場合、腰・膝・首に痛みがある場合、妊娠中の場合は触れないでください。"},"kolay":"後ろの膝を床に下ろし、下の手をブロックに置きます。合掌したまま肘を膝の外側にかけます。","zor":"腕を前脚の下と背中の後ろで組み、視線を天井へ向けます。","dikkat":"高血圧、めまい、妊娠中の場合は頭を下げすぎず、短時間にしてください。痛みがある場合は、医師や理学療法士に相談するよう勧めてください。","s":77,"fig":true},{"n":69,"bolum":5,"ad":"糸通しのポーズ","aile":"ねじり","seviye":"初級","yogunluk":[2,3,5],"calisan":["腹斜筋","回旋筋腱板（ローテーターカフ）"],"dengeleyen":["前鋸筋","腹横筋"],"uzayan":["菱形筋","僧帽筋中部・下部","三角筋"],"ozet":"四つ這いから片腕をもう片方の腕の下へすべらせ、肩と背中の上部をねじるやさしいねじりです。デスクワークの多い生徒にとって、背中上部の動きを穏やかに練習できる方法です。","asamalar":{"giris":"四つ這いになります。息を吸いながら右腕を天井へひらき、息を吐きながら右腕を左腕の下へすべらせ、右肩とこめかみを床に下ろします。","kalis":"お尻は膝の真上に保ち、左手で床を押します。首はリラックスさせ、体重は頭ではなく肩にのせます。5〜8呼吸キープします。","cikis":"左手で床を押しながら息を吸い、右腕を引き戻して四つ這いに戻り、反対側を行います。"},"hata":{"ne":"体重を頭と首にあずけること。","neden":"お尻が横にずれて背中上部が十分にねじれないと、上体の重さが頭と頸椎にかかります。","yonlendirme":"お尻は膝の上、体重は肩にのせます。"},"soylenecekler":["すべらせた腕の肩を床に落ち着け、頭はただ休ませましょう。","支えの手で床を押し、肩甲骨がひらくのを感じましょう。","息を吐きながら少しずつゆだね、何も無理はしないでください。"],"eller":{"nereye":"お尻の横と、上側に残る肩甲骨の上縁に置きます。","nasil":"同意を得てから、お尻が膝の上にとどまるよう軽く中央に整えます。肩甲骨には、ごく軽く広い面での接触で十分です。","ne_zaman_degil":"同意が得られていない場合、肩の痛みや最近の肩のけががある場合、首がデリケートな場合、妊娠中で床に近い姿勢がつらい場合は触れないでください。"},"kolay":"頭の下にブランケットかブロックを置き、お尻を少し後ろに引いておきます。","zor":"上の腕を背中に回して手を内ももへ伸ばすか、腕を頭の上の方向へ前に伸ばします。","dikkat":"膝がデリケートな場合は膝の下にブランケットを敷いてください。肩に痛みがある場合は、医師や理学療法士に相談するよう勧めてください。","s":78,"fig":true},{"n":70,"bolum":5,"ad":"椅子に座ったねじり","aile":"ねじり","seviye":"初級","yogunluk":[1,3,4],"calisan":["腹斜筋","多裂筋"],"dengeleyen":["脊柱起立筋","腹横筋"],"uzayan":["腰方形筋","菱形筋"],"ozet":"椅子に座って行う、誰でも取り組みやすいねじりです。床に座れない方、シニアのクラスやオフィスヨガのグループで、ねじりの基本を教えるのに使います。","asamalar":{"giris":"椅子の前のほうに座り、足を腰幅にして床に置きます。息を吸いながら背骨を伸ばし、息を吐きながら右へねじって右手を背もたれに、左手を右膝に置きます。","kalis":"両膝はそろえて正面に向け、左右の坐骨に均等に体重をのせます。吸う息ごとに伸びます。5呼吸キープします。","cikis":"息を吸いながら正面に戻り、両手を膝に置いて1呼吸休んでから左側へ移ります。"},"hata":{"ne":"膝までねじりに加わり、横へずれてしまうこと。","neden":"骨盤が安定していないと、回旋が股関節から生まれ、背骨はほとんどねじれません。","yonlendirme":"膝は正面、上体がねじれます。"},"soylenecekler":["両足で床を踏みしめ、膝をそろえておきましょう。","背もたれは体をねじるためではなく、まっすぐ座るためにつかみましょう。","息を吸って伸び、息を吐いてもう少しねじりましょう。"],"eller":{"nereye":"膝の外側、または生徒の後ろに立って肩甲骨の間に置きます。","nasil":"同意を得てから、膝がそろうよう軽く安定させるか、背中に上方向へ伸びる方向を示します。ねじらないでください。","ne_zaman_degil":"同意が得られていない場合、生徒がバランスやめまいの不安を訴えている場合、背中に痛みがある場合は触れないでください。"},"kolay":"両手は膝に置いたまま、ねじりを小さくします。","zor":"腕を胸の前で交差させ、手の支えなしでねじり、視線を後ろの肩へ送ります。","dikkat":"椅子が安定していて、キャスターがないことを確認してください。腰に痛みがある場合は、医師や理学療法士に相談するよう勧めてください。","s":79,"fig":true},{"n":71,"bolum":5,"ad":"ねじった頭を膝につけるポーズ","aile":"ねじり","seviye":"中級","yogunluk":[3,5,7],"calisan":["腹斜筋","広背筋"],"dengeleyen":["腰方形筋","腹横筋"],"uzayan":["ハムストリングス","内転筋群","広背筋"],"ozet":"脚を広げて座り、上体を伸ばした脚の方へ横に倒しながら胸を天井へ向ける、側屈とねじりを組み合わせたポーズです。体側のラインと、肋骨の間に入る呼吸を練習します。","asamalar":{"giris":"左脚を横に伸ばし、右足の裏を内ももに置きます。息を吸いながら右腕を上へ伸ばし、息を吐きながら左脚の方へ体を横に倒し、胸を天井へ向けます。","kalis":"下の肩は脚の内側に、胸は天井へひらいたまま保ちます。上の腕は耳の横から伸ばします。右の肋骨に息を吸い込むようにして5呼吸キープします。","cikis":"息を吸いながら上の腕の力で上体を起こし、正面に戻ります。脚を替える前に1呼吸まっすぐ座ります。"},"hata":{"ne":"胸を床の方へ閉じ、前屈に変えてしまうこと。","neden":"ハムストリングスや内転筋群が硬いと、上体が横ではなく前へずれ、ねじりが失われます。","yonlendirme":"胸は天井へ、腕は耳の横です。"},"soylenecekler":["曲げた膝を後ろへひらき、両方の坐骨を床につけておきましょう。","上の腕で弧を描くように伸びていきましょう。","足に届かなくても大丈夫です。大切なのは体側の長さです。"],"eller":{"nereye":"上側の胸郭の側面と、曲げた脚側のお尻に置きます。","nasil":"同意を得てから、お尻に床方向へ軽く重さをのせ、肋骨には天井へひらく方向を示すだけにします。","ne_zaman_degil":"同意が得られていない場合、ハムストリングスや鼠径部を最近痛めた場合、妊娠中の場合は触れないでください。"},"kolay":"伸ばした脚の膝を曲げ、下の肘を太ももかブロックにのせます。","zor":"下の手で伸ばした脚の足を内側からつかみ、上の手も足へ伸ばして胸を完全に天井へ向けます。","dikkat":"鼠径部やハムストリングスのけがの既往がある場合は、膝を曲げたまま行ってください。痛みがある場合は、医師や理学療法士に相談するよう勧めてください。","s":80,"fig":true},{"n":72,"bolum":5,"ad":"ねじりを加えたローランジ","aile":"ねじり","seviye":"初級","yogunluk":[2,4,6],"calisan":["腹斜筋","大腿四頭筋"],"dengeleyen":["中殿筋・小殿筋","腹横筋","前鋸筋"],"uzayan":["腸腰筋","大胸筋・小胸筋"],"ozet":"後ろの膝を床につけ、片手を床に、もう片手を天井へ伸ばすひらいたねじりです。股関節の前側を伸ばしながら胸をひらくことを、初心者に安全に教えられます。","asamalar":{"giris":"右足を前にしてローランジに入り、左手を右足の内側の床かブロックに置きます。息を吸いながら右腕を天井へひらき、胸を右へ向けます。","kalis":"骨盤を少し下に落ち着け、前の膝は足首の真上に保ちます。下の手で床を押し、肩を耳から遠ざけます。5呼吸キープします。","cikis":"息を吐きながら上の腕を下ろし、両手を前足の横に置きます。後ろの膝を床から上げる前に1呼吸待ちます。"},"hata":{"ne":"下側の肩が耳の方へ沈むこと。","neden":"支えの腕で前鋸筋が働かないと、肩甲骨が胸郭から離れて肩が上がります。","yonlendirme":"床を押して、肩を遠ざけます。"},"soylenecekler":["下の手で床を押し、その手から胸を持ち上げましょう。","後ろ脚側の股関節の前がひらくのを感じましょう。","胸を上の手の方へ向けましょう。視線は楽なところでかまいません。"],"eller":{"nereye":"後ろ脚側のお尻の後ろ面と、上の腕の肩先に置きます。","nasil":"同意を得てから、お尻に軽く前下方への方向を示し、肩先には後ろへひらくことを思い出させるだけにします。","ne_zaman_degil":"同意が得られていない場合、後ろの膝の痛み、肩のけが、妊娠がある場合は触れないでください。"},"kolay":"下の手を高めのブロックに置き、上の手は腰に添えたままにします。","zor":"上の腕を耳の横から前へ伸ばすか、後ろの足をつかんで大腿四頭筋のストレッチを加えます。","dikkat":"膝がデリケートな場合は、後ろの膝の下にたたんだブランケットを敷いてください。痛みがある場合は、医師や理学療法士に相談するよう勧めてください。","s":81,"fig":true},{"n":73,"bolum":5,"ad":"膝を曲げた仰向けのねじり","aile":"ねじり","seviye":"初級","yogunluk":[1,2,3],"calisan":["腹斜筋","横隔膜"],"dengeleyen":["腹横筋","内転筋群"],"uzayan":["腰方形筋","中殿筋・小殿筋"],"ozet":"仰向けで両膝をそろえて左右に倒す、最もシンプルなねじりです。腰まわりをやさしく動かし、呼吸をゆっくりにするため、クラスの始めや終わりに使います。","asamalar":{"giris":"仰向けになり、足裏を床につけて腕を横に広げます。息を吐きながら両膝をそろえて右へ倒し、お好みで頭を左へ向けます。","kalis":"膝と足はそろえたまま、両肩は床で休ませます。息を吸うときにお腹と肋骨が広がるのを観察します。片側5〜8呼吸ずつキープします。","cikis":"息を吸いながらお腹を軽く引き入れ、膝を中央に戻します。反対側に移る前に1呼吸待ちます。"},"hata":{"ne":"膝を左右に勢いよく倒すこと。","neden":"お腹の深層の筋肉がコントロールをやめると、脚の重さが腰椎をコントロールなく回旋させます。","yonlendirme":"ゆっくり倒し、お腹から戻ります。"},"soylenecekler":["膝をそろえておきましょう。間にブロックをはさんでもかまいません。","反対側の肩は床に近づけておきましょう。","呼吸のペースで、膝をゆっくり運びましょう。"],"eller":{"nereye":"倒した膝の外側、または反対側の肩の前に置きます。","nasil":"同意を得てから、膝が下りる動きに付き添うだけにします。肩には軽く安定した接触で、床にとどまることを思い出させます。","ne_zaman_degil":"同意が得られていない場合、腰の痛み、仙腸関節のデリケートさ、妊娠がある場合は触れないでください。"},"kolay":"膝の下にクッションかブロックを置き、動きを小さくします。","zor":"膝を股関節の高さに保ち、脚を床から浮かせたまま、コントロールして左右に倒します。","dikkat":"妊娠中は仰向けの時間を短くしてください。腰に痛みがある場合は、医師や理学療法士に相談するよう勧めてください。","s":82,"fig":true},{"n":74,"bolum":5,"ad":"四つ這いのねじり","aile":"ねじり","seviye":"初級","yogunluk":[2,3,5],"calisan":["腹斜筋","前鋸筋","回旋筋腱板（ローテーターカフ）"],"dengeleyen":["腹横筋","中殿筋・小殿筋"],"uzayan":["大胸筋・小胸筋"],"ozet":"四つ這いから片腕を天井へひらくアクティブなねじりです。支える側の肩の安定と、背中上部の回旋をあわせて学べます。アームバランスの準備としても使えます。","asamalar":{"giris":"手は肩の下、膝は股関節の下にして四つ這いになります。息を吸いながら右腕を横から天井へひらき、胸を右へ向けます。","kalis":"お尻は膝の上で安定させ、支えの腕で床を押します。回旋は背中上部から生まれるようにします。3〜5呼吸キープするか、呼吸に合わせて5回ひらいて閉じます。","cikis":"息を吐きながら腕を床に下ろし、両方の手のひらで均等に床を押して、反対の腕に移ります。"},"hata":{"ne":"お尻までねじりに加わり、横へずれること。","neden":"胸椎の回旋が制限されていると、動きを骨盤で補い、体が中心からずれます。","yonlendirme":"お尻は安定、胸が回ります。"},"soylenecekler":["支えの手の指すべてで床を押しましょう。","お尻は膝の上に保ち、胸だけをひらきましょう。","息を吸ってひらき、息を吐いて戻りましょう。"],"eller":{"nereye":"お尻の両側に置きます。","nasil":"同意を得てから、両手でお尻を軽く中央に保ち、生徒がねじる間は動かない目印になるだけにします。","ne_zaman_degil":"同意が得られていない場合、支えの手首や肩に痛みがある場合、生徒が膝の不快感を訴えている場合は触れないでください。"},"kolay":"ひらく手を頭の後ろに添え、肘を天井へ向けます。","zor":"腕を天井へ伸ばしたあと、反対の脚を後ろへ伸ばし、バランスを保ったままねじります。","dikkat":"手首がデリケートな場合は前腕をつくか、手のひらの下にたたんだマットを敷いてください。痛みがある場合は、医師や理学療法士に相談するよう勧めてください。","s":83,"fig":true},{"n":75,"bolum":6,"ad":"鳩のポーズ（エーカ・パーダ・ラージャカポターサナ準備）","aile":"股関節ひらき","seviye":"中級","yogunluk":[3,5,7],"calisan":["脊柱起立筋","中殿筋・小殿筋"],"dengeleyen":["梨状筋","腸腰筋","腹横筋"],"uzayan":["梨状筋","腸腰筋","大殿筋"],"ozet":"前脚の股関節は外旋、後ろ脚の股関節は伸展になる代表的な股関節ひらきのポーズです。股関節をひらきながら膝を守ることを教えられ、ラージャカポターサナへの準備になります。","asamalar":{"giris":"下向きの犬のポーズから右膝を右手首の後ろへ運び、左脚を後ろへ伸ばします。息を吸いながら両手で床を押して背骨を伸ばし、骨盤を左右均等に落ち着けます。","kalis":"骨盤は正面に、後ろ脚はまっすぐ保ちます。前の足首はアクティブにし、吐く息でお尻を少しずつ床へ落ち着けます。上体を起こすか前に倒して8〜10呼吸キープします。","cikis":"息を吸いながら両手で床を押して上体を起こし、後ろ足のつま先を立てて前脚を後ろへ戻し、下向きの犬のポーズに戻ります。"},"hata":{"ne":"体重をお尻ではなく前の膝にあずけること。","neden":"股関節の外旋が足りないと、ひらきを膝で探してしまい、膝関節が横からの負担を受けます。","yonlendirme":"膝を守って、股関節をひらきます。"},"soylenecekler":["前の足をフレックスにして、足首が倒れないようにしましょう。","お尻が床につかなければ、下にブロックを置いて体重をそこにのせましょう。","膝に刺すような感覚があればポーズから出ましょう。探したいのは、お尻に広がる感覚です。"],"eller":{"nereye":"前脚側の腰骨の横と、後ろ脚側のお尻に置きます。","nasil":"同意を得てから、左右の腰の高さがそろうよう軽く方向を示します。生徒を下へ押したり、体重をかけたりしないでください。","ne_zaman_degil":"同意が得られていない場合、生徒が膝の痛みを訴えている場合、人工股関節や妊娠がある場合は触れないでください。"},"kolay":"前脚側のお尻の下にブロックかブランケットを敷くか、仰向けの鳩のポーズ（4の字のポーズ）に替えます。","zor":"後ろの膝を曲げ、同じ側の手で足をつかんで胸をひらき、片脚の鳩のポーズに近づけます。","dikkat":"膝のけが、人工股関節、仙腸関節のデリケートさがある場合は、仰向けのバリエーションを使ってください。痛みがある場合は、医師や理学療法士に相談するよう勧めてください。","s":85,"fig":true},{"n":76,"bolum":6,"ad":"仰向けの鳩のポーズ（4の字のポーズ）","aile":"股関節ひらき","seviye":"初級","yogunluk":[2,3,5],"calisan":["腸腰筋","腹横筋"],"dengeleyen":["横隔膜","脊柱起立筋"],"uzayan":["梨状筋","大殿筋","中殿筋・小殿筋"],"ozet":"仰向けになり、片方の足首を反対の膝の上にのせる股関節ひらきのポーズです。膝を守る必要がある生徒や、床に座るのが難しい生徒にとって、鳩のポーズの安全な代わりになります。","asamalar":{"giris":"仰向けになり、両足の裏を床につけます。右の足首を左膝の上にのせ、息を吐きながら左足を床から上げて、左の太ももの裏を抱えます。","kalis":"仙骨と後頭部は床に、肩はリラックスさせます。右足はフレックスにし、膝を軽く外へひらきます。8〜10呼吸キープします。","cikis":"息を吸いながら左足を床に下ろし、右の足首を膝から外します。脚を伸ばして1呼吸休んでから反対側に移ります。"},"hata":{"ne":"太ももを引き寄せようとして、頭と肩を床から浮かせること。","neden":"お尻の後ろ側が硬いと、脚に届かせるために首や肩の筋肉が働き、上半身が緊張します。","yonlendirme":"頭は床に。脚にはストラップを使うか、足を壁につけます。"},"soylenecekler":["尾骨を床に近づけましょう。","上の足をフレックスにしましょう。膝を守ってくれます。","手が届かなければストラップを使い、頭は床に置いたままにしましょう。"],"eller":{"nereye":"ひらいた脚の膝のすぐ上、太もも側の内側に置きます。","nasil":"同意を得てから、膝の上、太ももの軸に沿ってごく軽く外向きの方向を示します。下へ押さず、膝に直接圧をかけることは決してしないでください。","ne_zaman_degil":"同意が得られていない場合、膝や股関節に痛みがある場合、人工股関節や妊娠がある場合は触れないでください。"},"kolay":"下側の足は床か壁につけたままにし、足首を膝の上にのせるだけにします。","zor":"お尻を軽く床から浮かせて仙骨をひらくか、ストラップを使わずに太ももを胸へもっと近づけます。","dikkat":"妊娠中は仰向けの時間を短くしてください。膝に痛みがある場合は、医師や理学療法士に相談するよう勧めてください。","s":86,"fig":true},{"n":77,"bolum":6,"ad":"トカゲのポーズ（ウッターン・プリシュターサナ）","aile":"股関節ひらき","seviye":"中級","yogunluk":[3,5,7],"calisan":["大腿四頭筋","前鋸筋"],"dengeleyen":["腹横筋","中殿筋・小殿筋"],"uzayan":["腸腰筋","内転筋群","ハムストリングス"],"ozet":"前足を手の外側に置く深いランジです。股関節屈筋と内ももを同時に伸ばし、後屈やスプリットの前の準備として使います。","asamalar":{"giris":"下向きの犬のポーズから右足を右手の外側へ運び、後ろの膝を床に下ろします。息を吸いながら背骨を伸ばし、息を吐きながら骨盤を前下方へ落ち着けます。","kalis":"前の膝は足首の真上か少し前で、外側へひらきます。胸は前へ伸び、肩は耳から遠ざけます。手か前腕をついて5〜8呼吸キープします。","cikis":"息を吸いながら手のひらで体を起こし、後ろ足のつま先を立てて前足を後ろへ戻し、下向きの犬のポーズに戻ります。"},"hata":{"ne":"前腕まで下りようとして背中を丸め、肩を落とすこと。","neden":"股関節屈筋や内転筋群が十分に伸びないまま上体を下げると、足りない動きを背中上部の丸まりで補ってしまいます。","yonlendirme":"まず手で長い背中を、前腕はそのあとです。"},"soylenecekler":["後ろの膝はブランケットの上に置いてかまいません。","前の膝を少し外へひらき、足でしっかり床を踏みましょう。","胸を前へ伸ばしましょう。下まで下りる必要はありません。"],"eller":{"nereye":"後ろ脚側のお尻の後ろ面と、前の膝の内側に置きます。","nasil":"同意を得てから、後ろのお尻にごく軽く前方向を示し、膝には外へひらくことを思い出させるだけにします。骨盤を下へ押さないでください。","ne_zaman_degil":"同意が得られていない場合、鼠径部の痛め、膝の痛み、妊娠がある場合は触れないでください。"},"kolay":"手の下にブロックを置き、後ろの膝は床につけたままにします。","zor":"後ろの膝を床から上げて脚をまっすぐにし、前腕まで下りて前の膝を外へひらきます。","dikkat":"鼠径部や股関節がデリケートな場合は、手をブロックに置いたままにしてください。痛みがある場合は、医師や理学療法士に相談するよう勧めてください。","s":87,"fig":true},{"n":78,"bolum":6,"ad":"合せきのポーズ（バッダ・コーナーサナ）","aile":"股関節ひらき","seviye":"初級","yogunluk":[2,3,5],"calisan":["脊柱起立筋","腸腰筋"],"dengeleyen":["内転筋群","骨盤底筋群","腹横筋"],"uzayan":["内転筋群"],"ozet":"足の裏を合わせて膝を横にひらく座位のポーズです。内ももの柔軟性とまっすぐ座る姿勢を練習でき、呼吸や骨盤底筋群への意識を高めるクラスでもよく使います。","asamalar":{"giris":"座って足の裏を合わせ、膝を横にひらきます。息を吸いながら坐骨に体重をのせて背骨を伸ばし、両手を足首に置きます。","kalis":"骨盤を立て、胸をひらきます。膝は自分の重さで自然に下ろします。お好みで、吐く息とともに股関節から前に倒れます。8〜10呼吸キープします。","cikis":"息を吸いながら上体を起こし、両手を膝の外側に添えて膝を閉じ、脚を前に伸ばします。"},"hata":{"ne":"膝を手で下へ押しつけること。","neden":"内転筋群が緊張しているときに膝を無理に押し下げると、鼠径部や膝の内側に過剰な負担がかかります。","yonlendirme":"膝は自分の重さで下ろします。"},"soylenecekler":["坐骨で床を押し、頭のてっぺんを上へ伸ばしましょう。","本をひらくように足の裏をひらいてもかまいませんが、膝は押さないでください。","前に倒れるときは、頭を膝へではなく、胸を足の方へ伸ばしましょう。"],"eller":{"nereye":"生徒の後ろに立ち、両手を腰の上、背骨の両側に置きます。","nasil":"同意を得てから、背骨が伸びるよう軽く上方向を示します。膝や背中を下へ押さないでください。","ne_zaman_degil":"同意が得られていない場合、鼠径部や膝の内側に痛みがある場合、骨盤まわりのデリケートさや妊娠がある場合は触れないでください。"},"kolay":"坐骨の下にブランケット、膝の下にブロックを置き、足を体から遠ざけます。","zor":"足を鼠径部に近づけ、長い背中のまま股関節から前に倒れます。","dikkat":"妊娠中は前屈を省き、上体を起こしたままにしてください。鼠径部に痛みがある場合は、医師や理学療法士に相談するよう勧めてください。","s":88,"fig":true},{"n":79,"bolum":6,"ad":"仰向けの合せき（スプタ・バッダ・コーナーサナ）","aile":"リストラティブ","seviye":"初級","yogunluk":[1,2,3],"calisan":["横隔膜","骨盤底筋群"],"dengeleyen":["内転筋群","腸腰筋"],"uzayan":["内転筋群","大胸筋・小胸筋"],"ozet":"仰向けで足の裏を合わせ、膝を支えて行うリストラティブな股関節ひらきです。クラスの終わりに神経系を落ち着かせ、呼吸への意識を高めるために使います。","asamalar":{"giris":"仰向けになり、足の裏を合わせて膝を横にひらき、太ももの下にブロックを置きます。息を吐きながら腕を横に下ろし、手のひらを上に向けます。","kalis":"腰は自然なカーブのまま、肩は広く保ちます。膝はブロックに完全にあずけます。お腹と肋骨に広がるゆっくりした呼吸で2〜5分キープします。","cikis":"息を吸いながら両手を膝の外側に添え、ゆっくり膝を閉じて足の裏を床につけ、横向きになってから座る姿勢に戻ります。"},"hata":{"ne":"支えなしで膝を無理に下ろすこと。","neden":"支えのない膝の重さが内転筋群と鼠径部を緊張させ続け、ゆるむどころか筋肉が身を守ろうとこわばります。","yonlendirme":"太ももの下にブロックを置き、ゆだねましょう。"},"soylenecekler":["膝がブロックに完全にあずけられているのを感じましょう。","息を吸うとお腹がふくらみ、吐くと背中が床に広がります。","ここではすることは何もありません。ただここにいてください。"],"eller":{"nereye":"ブロックの位置、または肩の前に置きます。","nasil":"同意を得てから、触れる代わりに、ブロックやブランケットを整えて支えます。必要であれば、肩にごく軽く安定した接触で十分です。","ne_zaman_degil":"同意が得られていない場合、生徒が目を閉じて深くリラックスしているときに声をかけずに触れることはしないでください。鼠径部の痛みや妊娠がある場合も触れないでください。"},"kolay":"背中の下に縦長にボルスターかたたんだブランケットを置き、頭の下も支えます。","zor":"ブロックを低くするか外し、完全に受動的なストレッチのままキープ時間を延ばします。","dikkat":"妊娠中は傾斜をつけたボルスターの上で上体を高くしてください。鼠径部や腰に痛みがある場合は、医師や理学療法士に相談するよう勧めてください。","s":89,"fig":true},{"n":80,"bolum":6,"ad":"花輪のポーズ（マーラーサナ）","aile":"股関節ひらき","seviye":"中級","yogunluk":[3,5,6],"calisan":["前脛骨筋","脊柱起立筋"],"dengeleyen":["内転筋群","骨盤底筋群","腹横筋"],"uzayan":["腓腹筋・ヒラメ筋","内転筋群","大殿筋"],"ozet":"足裏を床につけた深いしゃがみ姿勢です。足首の可動性、股関節のひらき、しゃがみながら背骨をまっすぐ保つことを一度に学べます。","asamalar":{"giris":"足をマット幅に置き、つま先を少し外へ向けます。息を吐きながらお尻をかかとの間に下ろし、胸の前で手のひらを合わせます。","kalis":"かかとは床に近く、膝はつま先と同じ方向に向けます。肘で膝を軽くひらきながら胸を持ち上げます。5〜8呼吸キープします。","cikis":"両手を床につき、息を吸いながらお尻を上げて前屈に移り、そこからゆっくり背骨を丸めて起き上がります。"},"hata":{"ne":"かかとが床から浮き、体重がつま先に移ること。","neden":"腓腹筋・ヒラメ筋が硬いと足首が十分に曲がらず、体重が前へずれます。","yonlendirme":"かかとの下にブランケット、体重はかかとに。"},"soylenecekler":["かかとが床につかなければ、下にたたんだブランケットを敷きましょう。","膝はつま先と同じ方向に向けましょう。","肘で膝を軽くひらき、胸を持ち上げましょう。"],"eller":{"nereye":"肩甲骨の間、背骨の両側に置きます。","nasil":"同意を得てから、胸が持ち上がるのに付き添うよう、背中に軽く上方向を示します。手で膝をひらかないでください。","ne_zaman_degil":"同意が得られていない場合、膝や足首に痛みがある場合、妊娠中でバランスがとりにくい場合は触れないでください。"},"kolay":"お尻の下にブロックを1〜2個置き、かかとの下をブランケットで支えます。","zor":"腕を膝の内側から通して脚の後ろで組むか、しゃがんだまま軽いねじりを加えます。","dikkat":"膝のけががある場合は深さを控え、ブロックを使ってください。膝や鼠径部に痛みがある場合は、医師や理学療法士に相談するよう勧めてください。","s":90,"fig":true},{"n":81,"bolum":6,"ad":"薪のポーズ（アグニスタンバーサナ）","aile":"股関節ひらき","seviye":"中級","yogunluk":[3,5,7],"calisan":["脊柱起立筋","前脛骨筋"],"dengeleyen":["腹横筋","内転筋群"],"uzayan":["梨状筋","中殿筋・小殿筋","大殿筋"],"ozet":"両すねを上下に重ねて座るポーズです。股関節外旋筋を強く伸ばすため、膝を守ることに注意が必要です。","asamalar":{"giris":"あぐらから左のすねをマットの前端と平行に置き、その上に右のすねを重ねて、右の足首が左膝の上にくるようにします。息を吸いながら坐骨に体重をのせて背骨を伸ばします。","kalis":"両足はフレックスにしてアクティブに保ち、すねは上下に重ね、骨盤を立てます。お好みで、吐く息とともに股関節から前に倒れます。8〜10呼吸キープします。","cikis":"息を吸いながら上体を起こし、上の脚を手で支えて持ち上げ、脚を前に伸ばしてから反対側に移ります。"},"hata":{"ne":"足の力を抜き、足首を曲げてしまうこと。","neden":"足がゆるむと足首が横に折れ、股関節から生まれるべき回旋が膝と足首に移ってしまいます。","yonlendirme":"足はフレックス、膝は安全に。"},"soylenecekler":["両足の裏をアクティブにして、つま先を自分の方へ引き寄せましょう。","上の膝が浮いていたら、下にブロックを置きましょう。","膝ではなく、お尻の外側に感覚を探しましょう。"],"eller":{"nereye":"上の膝の下のブロック、または生徒の後ろで背骨の両側に置きます。","nasil":"同意を得てから、必要であればブロックを置きます。背中には伸びる方向にだけ軽く触れ、膝を下へ押すことは決してしないでください。","ne_zaman_degil":"同意が得られていない場合、膝の痛み、半月板や靭帯のけがの既往、人工股関節がある場合は触れないでください。"},"kolay":"上の足を下の太ももではなく床に置いて楽なあぐらにするか、上の膝の下にブロックを置きます。","zor":"すねをしっかり重ねたまま股関節から前に倒れ、前腕を床につけます。","dikkat":"膝や股関節のけががある場合は、仰向けの鳩のポーズ（4の字のポーズ）に替えてください。痛みがある場合は、医師や理学療法士に相談するよう勧めてください。","s":91,"fig":true},{"n":82,"bolum":6,"ad":"牛の顔のポーズ（ゴームカーサナ）","aile":"股関節ひらき","seviye":"中級","yogunluk":[3,5,6],"calisan":["回旋筋腱板（ローテーターカフ）","上腕三頭筋"],"dengeleyen":["脊柱起立筋","腹横筋"],"uzayan":["中殿筋・小殿筋","大腿筋膜張筋","広背筋"],"ozet":"膝を上下に重ねる脚のかたちと、お好みで背中の後ろで腕を組むポーズです。お尻の外側を伸ばしながら、肩の可動性も練習できます。","asamalar":{"giris":"四つ這いから右膝を左膝の前に交差させ、足を左右にひらいて、足の間にお尻を下ろします。息を吸いながら背骨を伸ばします。","kalis":"両方の坐骨に均等に体重をのせ、膝は上下に重ねます。背中で腕を組む場合は、上の肘を天井へ向けます。5〜8呼吸キープします。","cikis":"息を吐きながら腕をほどき、両手を前について四つ這いになり、脚の組み方を替えて繰り返します。"},"hata":{"ne":"片方の坐骨が床から浮き、骨盤が横に傾くこと。","neden":"お尻の外側が硬いと片側が持ち上がり、背骨が横に傾いてその不均衡を補います。","yonlendirme":"両方の坐骨を床に、必要ならブロックを。"},"soylenecekler":["浮いている坐骨の下に、ブロックかブランケットを敷きましょう。","手が届かなければ、手の間にストラップを持ちましょう。","胸をひらいたまま、上の肘で頭を押さないようにしましょう。"],"eller":{"nereye":"上の腕の肘と、背中の後ろでストラップを持つ手に置きます。","nasil":"同意を得てから、ストラップを持つ手にごく小さな方向を示すだけにします。肩や肘を後ろへ押さないでください。","ne_zaman_degil":"同意が得られていない場合、肩の痛みや不安定さ、膝の痛み、妊娠がある場合は触れないでください。"},"kolay":"お尻の下にブロックを置き、腕は背中の後ろではなく膝の上に置きます。","zor":"背中の後ろで直接手を組み、長い背中のまま股関節から前に倒れます。","dikkat":"膝のけががある場合は、下の脚を伸ばしたままにしてください。肩や膝に痛みがある場合は、医師や理学療法士に相談するよう勧めてください。","s":92,"fig":true},{"n":83,"bolum":6,"ad":"カエルのポーズ（マンドゥーカーサナ）","aile":"股関節ひらき","seviye":"上級","yogunluk":[4,6,8],"calisan":["腹横筋","前鋸筋"],"dengeleyen":["脊柱起立筋","骨盤底筋群"],"uzayan":["内転筋群","大殿筋"],"ozet":"膝を大きくひらき、前腕をついてキープする強度の高い内もものストレッチです。股関節の可動性が育っている生徒向けで、長くコントロールされたキープが求められます。","asamalar":{"giris":"四つ這いから膝をゆっくり左右にひらき、足首は膝と同じ高さに保ちます。息を吐きながら前腕を床につき、お尻を膝と同じ高さに運びます。","kalis":"腰はニュートラル、お腹は軽くアクティブに保ちます。お尻は膝より前にも後ろにも出さないようにします。吐く息ごとに1センチずつゆだねながら5〜10呼吸キープします。","cikis":"息を吸いながら手のひらで体を起こし、膝を一つずつ中央に戻して、チャイルドポーズで休みます。"},"hata":{"ne":"腰を反らせてお尻を後ろへ突き出すこと。","neden":"内転筋群が緊張すると骨盤が前傾して逃げ道を探し、腰椎に圧迫がかかります。","yonlendirme":"おへそを軽く背骨へ引き寄せましょう。"},"soylenecekler":["膝の下にブランケットを敷きましょう。","ひらきは膝ではなく、呼吸で深めていきましょう。","鼠径部に鋭い感覚があれば、膝を少し近づけましょう。"],"eller":{"nereye":"仙骨の上に置きます。","nasil":"同意を得てから、仙骨に軽く安定した接触をするだけで、腰をニュートラルに保つことを思い出させます。お尻を下や後ろへ押さないでください。","ne_zaman_degil":"同意が得られていない場合、鼠径部の痛め、膝の痛み、股関節の不調、妊娠がある場合は触れないでください。"},"kolay":"膝のひらきを小さくし、お尻を少し後ろに保ち、胸の下にボルスターを置きます。","zor":"前腕を前へ伸ばして胸を床に近づけ、膝を段階的にひらいていきます。","dikkat":"鼠径部や股関節のけがの既往がある場合は、膝のひらきを小さく保ってください。痛みがある場合は、医師や理学療法士に相談するよう勧めてください。","s":93,"fig":true},{"n":84,"bolum":6,"ad":"ハッピーベイビー（アーナンダ・バーラーサナ）","aile":"股関節ひらき","seviye":"初級","yogunluk":[2,3,4],"calisan":["広背筋","腹横筋"],"dengeleyen":["横隔膜","脊柱起立筋"],"uzayan":["内転筋群","ハムストリングス","大殿筋"],"ozet":"仰向けで膝をわきの下の方へ引き寄せる、遊び心のある股関節ひらきです。腰を床に落ち着けながら、内ももとお尻の後ろ側をゆるめます。","asamalar":{"giris":"仰向けになり、膝を胸に引き寄せます。息を吐きながら膝をわきの下の方へひらき、足の裏を天井に向けて足の外側をつかみます。","kalis":"すねは床に対して垂直、足首は膝の真上に保ちます。仙骨は床に近く、肩と頭は床につけたままにします。お好みで左右に軽く揺れながら8〜10呼吸キープします。","cikis":"息を吸いながら足を離し、膝をそろえて胸に引き寄せ、足を床に下ろします。"},"hata":{"ne":"足を引くときに仙骨と頭が床から浮くこと。","neden":"お尻の後ろ側や内ももが硬いと、足に届かせるために骨盤が上へ丸まり、肩が床から浮きます。","yonlendirme":"まず仙骨を床に、足はそのあとです。"},"soylenecekler":["足に手が届かなければ、すねか太ももの裏を持ちましょう。","尾骨を床の方へ伸ばしましょう。","お好みで左右にやさしく揺れて、背中をマッサージするように感じましょう。"],"eller":{"nereye":"足の裏、または生徒の足首の上に置きます。","nasil":"同意を得てから、足が床の方へ、膝がわきの下の方へ向かう動きに、ごく軽く付き添います。下へ押さないでください。","ne_zaman_degil":"同意が得られていない場合、鼠径部や腰の痛み、人工股関節、妊娠がある場合は触れないでください。"},"kolay":"片脚ずつの半分のハッピーベイビーにするか、ストラップで足を持ちます。","zor":"仙骨を完全に床につけたまま膝を床に近づけ、キープ時間を延ばします。","dikkat":"妊娠中は仰向けの時間を短くしてください。腰や鼠径部に痛みがある場合は、医師や理学療法士に相談するよう勧めてください。","s":94,"fig":true},{"n":85,"bolum":6,"ad":"アルダ・マツイェーンドラーサナの脚","aile":"股関節ひらき","seviye":"初級","yogunluk":[2,3,5],"calisan":["脊柱起立筋","腹横筋"],"dengeleyen":["内転筋群","多裂筋"],"uzayan":["梨状筋","中殿筋・小殿筋","大腿筋膜張筋"],"ozet":"アルダ・マツイェーンドラーサナの脚のかたちを、ねじらずに使う練習です。上体を正面に保ったまま、お尻の外側と太ももの外側を伸ばすことを学べ、ねじりの準備になります。","asamalar":{"giris":"座って左脚を折りたたみ、右足を左膝の外側に置きます。息を吸いながら両手で右膝を抱え、背骨を伸ばします。","kalis":"両方の坐骨は床に、上体は正面に向けます。右膝を胸の中央の方へ軽く引き寄せます。吐く息でお尻の外側がやわらぐのを観察しながら8呼吸キープします。","cikis":"息を吐きながら膝を離し、脚を前に伸ばして、反対側に移る前に脚を軽く揺らします。"},"hata":{"ne":"膝を引き寄せるときに、上側のお尻が床から浮くこと。","neden":"梨状筋や中殿筋・小殿筋が硬いと、骨盤を横に傾けることでストレッチから逃げてしまいます。","yonlendirme":"両方の坐骨を床に。"},"soylenecekler":["膝を胸の中央の方へ近づけましょう。","お尻の外側に広がる伸びを探しましょう。","上体は正面のままで。ねじりはこのあとです。"],"eller":{"nereye":"床から浮きやすい側のお尻の上面に置きます。","nasil":"同意を得てから、お尻にごく軽く床方向を示します。膝を胸の方へ引かないでください。","ne_zaman_degil":"同意が得られていない場合、股関節や膝の痛み、人工股関節、妊娠がある場合は触れないでください。"},"kolay":"坐骨の下にブランケットを敷き、下側の脚は伸ばしたままにします。","zor":"膝を胸に近づけながら股関節から前に倒れるか、次のステップとしてねじりに移ります。","dikkat":"人工股関節の場合は、脚を体の正中線より先へ交差させないでください。痛みがある場合は、医師や理学療法士に相談するよう勧めてください。","s":95,"fig":true},{"n":86,"bolum":6,"ad":"大腿四頭筋を伸ばすローランジ","aile":"股関節ひらき","seviye":"中級","yogunluk":[3,5,7],"calisan":["ハムストリングス","大殿筋"],"dengeleyen":["腹横筋","中殿筋・小殿筋"],"uzayan":["大腿四頭筋","腸腰筋"],"ozet":"ローランジで後ろの足を手でつかみ、太ももの前を伸ばすバリエーションです。股関節屈筋と大腿四頭筋を同時に伸ばし、後屈の準備になります。","asamalar":{"giris":"右足を前にしてローランジに入り、後ろの膝の下にブランケットを敷きます。息を吐きながら後ろの膝を曲げ、左手を左足へ伸ばします。","kalis":"骨盤を軽く後ろへ傾け、尾骨を床の方へ伸ばします。かかとをお尻へ無理に引き寄せないようにします。5呼吸キープします。","cikis":"息を吸いながら足をゆっくり離し、両手を前足の横に置いて反対側に移ります。"},"hata":{"ne":"足を引くときに腰を反らせること。","neden":"大腿四頭筋や腸腰筋が硬いと骨盤が前傾し、伸びが股関節ではなく腰から生まれてしまいます。","yonlendirme":"尾骨を下へ、それから足です。"},"soylenecekler":["後ろの膝は、やわらかい支えの上に置きましょう。","おへそを軽く引き入れて、腰を長く保ちましょう。","足に手が届かなければ、ストラップを使いましょう。"],"eller":{"nereye":"後ろ脚側のお尻の上面、または持っている足にかけたストラップに置きます。","nasil":"同意を得てから、骨盤にはニュートラルを保つことを思い出させるだけにします。かかとをお尻の方へ押さないでください。","ne_zaman_degil":"同意が得られていない場合、後ろの膝の痛み、大腿四頭筋の痛め、腰のデリケートさ、妊娠がある場合は触れないでください。"},"kolay":"後ろの足にストラップをかけ、前側の手はブロックについて体を支えます。","zor":"骨盤を前に落ち着け、同じ側の手で肩越しに足をつかみ、胸をひらきます。","dikkat":"膝のけががある場合は、後ろの膝をしっかり支えるか、足をつかまないでください。痛みがある場合は、医師や理学療法士に相談するよう勧めてください。","s":96,"fig":true},{"n":87,"bolum":6,"ad":"スカンダーサナ","aile":"股関節ひらき","seviye":"中級","yogunluk":[3,5,7],"calisan":["大腿四頭筋","大殿筋"],"dengeleyen":["内転筋群","腹横筋","前脛骨筋"],"uzayan":["内転筋群","ハムストリングス"],"ozet":"足を大きく開いた姿勢で片膝に向かってしゃがみ、もう片方の脚をまっすぐ伸ばすサイドランジです。股関節の横方向の可動性、内もも、脚の筋力をあわせて練習します。","asamalar":{"giris":"足を大きく開いて立ち、つま先を軽く外へ向けます。息を吐きながら右膝を曲げてお尻を右のかかとの方へ下ろし、左脚はつま先を天井に向けて伸ばします。","kalis":"曲げた脚のかかとは床に、膝はつま先と同じ方向に保ちます。胸を持ち上げ、手は胸の前か床に置きます。3〜5呼吸キープします。","cikis":"息を吸いながら曲げた脚のかかとで床を押して中央に戻り、足を平行にそろえて反対側に移ります。"},"hata":{"ne":"曲げた膝が内側に倒れ、かかとが浮くこと。","neden":"股関節外旋筋や足首の可動性が足りないまま深くしゃがむと、膝が内側へ入ります。","yonlendirme":"膝はつま先の方向、かかとは床に。"},"soylenecekler":["まずは半分の深さまで下りましょう。深さはあとからついてきます。","手を床かブロックについて、バランスを保ちましょう。","伸ばした脚のつま先を天井に向けましょう。"],"eller":{"nereye":"曲げた脚の膝の外側と、お尻の後ろ面に置きます。","nasil":"同意を得てから、膝に軽く外向きの方向を示します。生徒をもっと深く下ろそうとして押さないでください。","ne_zaman_degil":"同意が得られていない場合、膝や鼠径部の痛み、バランスの不安、妊娠がある場合は触れないでください。"},"kolay":"手をブロックに置き、半分の深さにとどめます。かかとの下にブランケットを敷きます。","zor":"胸の前で手を合わせて支えなしで下り、呼吸に合わせて左右に流れるように移動します。","dikkat":"膝のけがや鼠径部の痛めの既往がある場合は、深さを制限してください。痛みがある場合は、医師や理学療法士に相談するよう勧めてください。","s":97,"fig":true},{"n":88,"bolum":6,"ad":"門のポーズ（パリガーサナ）","aile":"股関節ひらき","seviye":"初級","yogunluk":[2,4,5],"calisan":["腹斜筋","中殿筋・小殿筋"],"dengeleyen":["腰方形筋","腹横筋"],"uzayan":["広背筋","内転筋群","ハムストリングス"],"ozet":"片膝を床につき、もう片方の脚を横に伸ばして行う側屈です。体側のラインと内ももを伸ばし、呼吸が肋骨の間に広がる感覚をつかめます。","asamalar":{"giris":"膝立ちになり、右脚を横に伸ばして足裏を床につけます。息を吸いながら左腕を上げ、息を吐きながら右脚の方へ体を横に倒します。","kalis":"お尻は床についた膝の真上で立てたまま、胸は前ではなく横へひらきます。上の腕の方の肋骨に息を吸い込みます。5呼吸キープします。","cikis":"息を吸いながら上の腕で上体を起こし、伸ばした脚を戻します。両膝立ちで1呼吸待ってから反対側に移ります。"},"hata":{"ne":"お尻を後ろへ突き出し、上体を前に閉じること。","neden":"体側や内ももが硬いと、側屈の代わりに股関節が曲がり、上体が前へ落ちます。","yonlendirme":"お尻は膝の上、胸は横へひらきます。"},"soylenecekler":["床についた膝の下にブランケットを敷きましょう。","お尻を少し前へ押し、2枚のガラスの間に体があるとイメージしましょう。","上の腕を長く保ち、肩を耳から遠ざけましょう。"],"eller":{"nereye":"床についた膝側のお尻の横と、上の腕の肘に置きます。","nasil":"同意を得てから、お尻が膝の真上にくるよう軽く方向を示し、上の腕には伸びる感覚を伝えるだけにします。下へ引かないでください。","ne_zaman_degil":"同意が得られていない場合、膝の痛み、肩のけが、妊娠がある場合は触れないでください。"},"kolay":"伸ばした脚の膝を軽く曲げ、上の手は腰に置いたままにします。","zor":"伸ばした脚の足裏を床にぺたりとつけ、上の腕を頭の上から伸ばした脚の方へ伸ばして手のひらを合わせます。","dikkat":"膝がデリケートな場合は、膝の下にブランケットを二重に敷いてください。痛みがある場合は、医師や理学療法士に相談するよう勧めてください。","s":98,"fig":true},{"n":89,"bolum":6,"ad":"ねじりを加えたトカゲのポーズ","aile":"股関節ひらき","seviye":"中級","yogunluk":[3,5,7],"calisan":["腹斜筋","大腿四頭筋"],"dengeleyen":["前鋸筋","腹横筋","中殿筋・小殿筋"],"uzayan":["腸腰筋","内転筋群","大胸筋・小胸筋"],"ozet":"トカゲのポーズで胸を前脚の方へひらくバリエーションです。股関節のひらきに胸の回旋を加え、このパートをまとめるポーズになります。","asamalar":{"giris":"右足を右手の外側に置いてトカゲのポーズに入り、後ろの膝を床につけます。息を吸いながら右手を床から離し、息を吐きながら胸を右へひらいて右腕を天井へ伸ばします。","kalis":"左手で床を押して肩を耳から遠ざけ、前の膝は足首の真上に保ちます。回旋は胸から生まれるようにします。5呼吸キープします。","cikis":"息を吐きながら右手を床に下ろしてトカゲのポーズに戻り、後ろ足のつま先を立てて下向きの犬のポーズに戻ります。"},"hata":{"ne":"胸をひらくときに前の膝が内側に閉じること。","neden":"上体がねじれる間に前脚側の股関節外旋筋がゆるむと、膝が足と一緒に内側へ入ります。","yonlendirme":"膝は外へ、胸は上へ。"},"soylenecekler":["支えの手はブロックに置いてもかまいません。","前の膝を、同じ側の肩の方へ軽く外にひらきましょう。","胸を上の手の方へひらき、腰は穏やかに保ちましょう。"],"eller":{"nereye":"前の膝の内側と、上の腕の肩先に置きます。","nasil":"同意を得てから、膝にごく軽く外向きの方向を示します。肩を後ろへ引かず、ひらく方向を示すだけにします。","ne_zaman_degil":"同意が得られていない場合、鼠径部の痛め、膝や肩の痛み、妊娠がある場合は触れないでください。"},"kolay":"支えの手を高めのブロックに置き、上の手は前の膝の上に置いたまま、胸だけを回します。","zor":"後ろの膝を曲げ、上の手で後ろの足をつかんで、ねじりながら大腿四頭筋を伸ばす動きを加えます。","dikkat":"股関節や膝のけががある場合は、深さを制限してください。痛みがある場合は、医師や理学療法士に相談するよう勧めてください。","s":99,"fig":true},{"n":90,"bolum":6,"ad":"膝を開いたチャイルドポーズ","aile":"リストラティブ","seviye":"初級","yogunluk":[1,2,3],"calisan":["横隔膜","骨盤底筋群"],"dengeleyen":["脊柱起立筋","内転筋群"],"uzayan":["内転筋群","広背筋","脊柱起立筋"],"ozet":"膝を大きくひらき、その間に上体をゆだねる休息のポーズです。内ももをやさしく伸ばしながら、呼吸が背中に広がる感覚をつかめます。シークエンスの合間の休息に使います。","asamalar":{"giris":"膝立ちになり、足の親指をそろえて膝をマット幅にひらきます。息を吐きながらお尻をかかとの方へ下ろし、腕を前に伸ばして額を床に置きます。","kalis":"お尻はかかとに近づけ、肩はリラックスさせ、額は床かブロックに置きます。息を吸うときに背中が広がるのを観察します。1〜3分キープします。","cikis":"息を吸いながら両手を肩の下まで歩かせ、背骨をゆっくり丸めながら起き上がり、膝を閉じます。"},"hata":{"ne":"お尻がかかとにつかず、肩や首に力が入ること。","neden":"股関節や膝の屈曲が制限されていると体重が前へずれ、肩と首が上体を支え始めます。","yonlendirme":"額とお尻の下に支えを置き、肩をゆるめましょう。"},"soylenecekler":["額の下にブロックを置き、首を完全に休ませましょう。","息を吸うたびに、背中が広がるのを感じましょう。","お尻がかかとにつかなければ、間にブランケットをはさみましょう。"],"eller":{"nereye":"仙骨の上、または腰の両側に置きます。","nasil":"同意を得てから、吐く息に合わせて、手のひらで仙骨に後ろ下方向へのごく軽い重さをのせます。決して押さないでください。","ne_zaman_degil":"同意が得られていない場合、膝の痛み、腰のデリケートさ、妊娠がある場合、またはうつ伏せに近い姿勢で触れられることを生徒が好まない場合は触れないでください。"},"kolay":"上体の下に縦長にボルスターを置き、お尻とかかとの間にブランケットをはさみます。","zor":"腕を右へ歩かせて体の左側のラインを伸ばし、次に左へ移ります。","dikkat":"膝がデリケートな場合は、膝の裏にたたんだブランケットをはさんでください。妊娠中はお腹が収まる幅まで膝をひらいてください。痛みがある場合は、医師や理学療法士に相談するよう勧めてください。","s":100,"fig":true},{"n":91,"bolum":7,"ad":"壁に脚を上げるポーズ（ヴィパリータ・カラニ）","aile":"逆転","seviye":"初級","yogunluk":[1,2,3],"calisan":["横隔膜","大腿四頭筋"],"dengeleyen":["腹横筋","骨盤底筋群"],"uzayan":["ハムストリングス","腓腹筋・ヒラメ筋"],"ozet":"脚を壁にあずけ、心臓が腰より少し高い位置に保たれる穏やかな逆転のポーズです。クラスの終盤にペースを落とし、生徒が呼吸を観察する時間をつくるために用います。","asamalar":{"giris":"片側の腰を壁につけて横向きに座ります。息を吐きながら仰向けになり、脚を壁に沿って上げます。坐骨は壁の近くに、背骨は床の上で長く保ちます。","kalis":"骨盤は床に均等に重さをあずけ、腰は自然なカーブを保ち、腕は体の横で力を抜きます。鼻からゆっくり呼吸し、3〜10分とどまります。","cikis":"息を吐きながら膝を曲げ、足裏を壁に押し当てて右側へ転がります。横向きのまま数呼吸待ち、手で床を押してゆっくり起き上がります。"},"hata":{"ne":"ハムストリングスが硬いのに、お尻を壁にぴったりつけようとすること。","neden":"脚の裏側の張りが骨盤を後ろへ傾け、腰が平らになって詰まりやすくなります。","yonlendirme":"お尻を手のひら一枚分うしろへ、腰は床でやわらかく。"},"soylenecekler":["壁に脚をあずけて、ただ呼吸を見守りましょう。","膝は少し曲げても大丈夫です。ここでは伸びを求めません。","息を吐くたびに、肩を少しずつ床にゆだねていきましょう。"],"eller":{"nereye":"生徒の足首のすぐ上、脚が壁に触れているところ。","nasil":"同意を得てから、脚を壁の方へごくやさしく導くか、位置を整える目的でのみ触れてください。下へ押さないでください。","ne_zaman_degil":"同意を得ていない場合、生徒が脚のしびれや圧迫感を訴えている場合、または妊娠後期で仰向けがつらい場合は触れないでください。"},"kolay":"お尻を壁から離し、膝を曲げて足裏を壁につけます。頭の下に薄いブランケットを敷きます。","zor":"脚を壁に沿って大きく左右にひらくか、足裏を合わせて合せきの形にします。","dikkat":"妊娠後期で仰向けがつらい場合は横向きに切り替えてください。眼圧に関わる状態、コントロールされていない高血圧、逆流性食道炎がある場合は時間を短くし、医師に相談するよう勧めてください。脚にしびれが出たら膝を曲げます。","s":102,"fig":true},{"n":92,"bolum":7,"ad":"イルカのポーズ（アルダ・ピンチャ・マユーラーサナ）","aile":"逆転","seviye":"中級","yogunluk":[3,5,6],"calisan":["三角筋","前鋸筋","回旋筋腱板（ローテーターカフ）"],"dengeleyen":["腹横筋","僧帽筋中部・下部"],"uzayan":["ハムストリングス","広背筋","腓腹筋・ヒラメ筋"],"ozet":"前腕を床について行う、下向きの犬のポーズに似た半逆転のポーズです。肩まわりに筋力と安定性を育て、前腕倒立や頭立ちの準備の土台になります。","asamalar":{"giris":"四つ這いから前腕を肩幅で床に置き、肘を肩の真下にします。息を吐きながらつま先を立て、お尻を上と後ろへ持ち上げます。","kalis":"前腕で床を押し、胸郭を前腕から遠ざけ、背骨は尾骨から頭頂まで長く伸ばします。頭は床から浮かせ、首は楽に保ちます。5〜8呼吸とどまります。","cikis":"息を吐きながら膝を床に下ろし、チャイルドポーズで額を休めます。"},"hata":{"ne":"肩が耳の方へ落ち込み、胸が前腕の方へ沈むこと。","neden":"前鋸筋と僧帽筋下部が十分に働かないと、肩甲骨が背中の上の方へずれ上がります。","yonlendirme":"床を押して、胸を膝の方へ運びます。"},"soylenecekler":["前腕で床をしっかり押して、床から離れていくように感じてください。","背中を長く保てるよう、膝は好きなだけ曲げてかまいません。","頭は床から浮かせて首は楽に、目線は足の方へ向けましょう。"],"eller":{"nereye":"肩甲骨の外側の縁、わきの下のすぐ後ろ。","nasil":"同意を得てから、肩甲骨を腰の方へ、外側へ軽く導いて言葉の合図を補ってください。体重はかけないでください。","ne_zaman_degil":"同意がない場合、肩の痛みや不安定感を訴えている場合、妊娠後期の場合、または頭が床に落ちてしまう場合は、触れずに膝を床に下ろすよう促してください。"},"kolay":"膝を床につけたままお尻だけを持ち上げるか、両手の間にブロックを置いて親指ではさみます。","zor":"足を前腕の方へ数歩歩かせるか、片脚を腰の高さまで持ち上げます。","dikkat":"肩、首、肘に不調がある場合はブロックを使ったバリエーションに切り替えてください。頭が心臓より低くなるため、眼圧に関わる状態やコントロールされていない高血圧がある場合は短めにとどめ、医師に相談するよう勧めてください。妊娠中に行うかどうかは、生徒が医師と一緒に判断するよう伝えてください。","s":103,"fig":true},{"n":93,"bolum":7,"ad":"プランク（パラカーサナ）","aile":"アームバランス","seviye":"初級","yogunluk":[3,5,6],"calisan":["腹直筋","腹横筋","前鋸筋","上腕三頭筋"],"dengeleyen":["大殿筋","大腿四頭筋","三角筋"],"uzayan":[],"ozet":"手からかかとまで体が一直線になる、基本の支えのポーズです。体幹の安定と腕で体重を支える感覚を学び、チャトランガやアームバランスの土台になります。","asamalar":{"giris":"下向きの犬のポーズから息を吸いながら肩を手首の真上に運びます。お尻を肩とかかとの高さまで下ろし、手は肩幅に置きます。","kalis":"尾骨はかかとの方へ伸び、肋骨は内側にまとまり、腰は反りません。首の後ろは長く、目線は手の少し前に。安定した呼吸で5〜10呼吸とどまります。","cikis":"息を吐きながら膝を床に下ろすか、お尻を後ろへ押して下向きの犬のポーズに戻ります。"},"hata":{"ne":"お尻が落ちて腰が沈むこと。","neden":"腹壁と殿筋が疲れると骨盤が前に傾き、腰椎に負担がかかります。","yonlendirme":"おへそは背骨へ、かかとは後ろへ。"},"soylenecekler":["手からかかとまで、一枚の長い板のようになりましょう。","床を押して、肩甲骨の間にスペースをつくりましょう。","呼吸は止めずに、吐く息でお腹をもう少し引き寄せましょう。"],"eller":{"nereye":"仙骨の上、または肩甲骨の間に、手のひらを平らにして。","nasil":"同意を得てから、仙骨の高さの目安として手のひらを置くだけにしてください。生徒自身がお尻を手のひらの方へ上げ下げして調整します。","ne_zaman_degil":"同意がない場合、手首や肩の痛みを訴えている場合、または妊娠中に腹壁の離開のサインが見られる場合は触れずに、膝を床に下ろすよう勧めてください。"},"kolay":"膝を床について行うハーフプランクにするか、手をベンチや壁に置きます。","zor":"片脚を腰の高さまで上げるか、肩を手首より少し前へ運びます。","dikkat":"手首が敏感な場合は前腕プランクを選ぶか、手のひらの下に折りたたんだマットを敷いてください。妊娠中や産後は腹圧に注意し、必要に応じて壁を使ったバリエーションに切り替え、医師や理学療法士に相談するよう勧めてください。","s":104,"fig":true},{"n":94,"bolum":7,"ad":"チャトランガ（チャトランガ・ダンダーサナ）","aile":"アームバランス","seviye":"中級","yogunluk":[5,7,8],"calisan":["上腕三頭筋","大胸筋・小胸筋","前鋸筋","三角筋"],"dengeleyen":["腹直筋","腹横筋","大殿筋"],"uzayan":[],"ozet":"プランクから肘を曲げ、体を床と平行に下ろす筋力のポーズです。フローの中で最も多く繰り返す移行なので、肩の前側を守るアライメントを教えることがとても重要です。","asamalar":{"giris":"プランクで肩を手首より少し前へ運びます。息を吐きながら肘を後ろへ、体の近くで曲げ、体をひとまとまりのまま下ろします。","kalis":"肘は手首の真上、肩は肘と同じ高さか少し上に保ち、胸は広く、腰は沈ませません。1〜3呼吸とどまります。","cikis":"息を吸いながら上向きの犬のポーズかコブラのポーズへ移るか、膝と胸を床に下ろします。"},"hata":{"ne":"肩を肘の高さより下まで落としてしまうこと。","neden":"上腕三頭筋と前鋸筋が疲れると上腕骨の骨頭が前に転がり、肩の前側に負担がかかります。","yonlendirme":"肩は肘の高さで止め、それより下へは下ろしません。"},"soylenecekler":["半分の高さまで下りましょう。ここでは低いほど良いわけではありません。","肘は肋骨をかすめるように後ろへ引きましょう。","胸は前へ、目線は手の少し前に向けましょう。"],"eller":{"nereye":"肩の前側、鎖骨のすぐ外側。","nasil":"同意を得てから、指2本で肩を軽く上へ導き、肩を肘の高さに保つ位置を示してください。体重を支えないでください。","ne_zaman_degil":"同意がない場合、肩や手首に痛みがある場合、妊娠中、または生徒が動いている最中は触れずに、言葉の合図で伝えてください。"},"kolay":"膝を床について下ろすか、胸の下にブロックやボルスターを置きます。","zor":"とどまる時間を5呼吸まで延ばすか、片脚を床から浮かせて下ろします。","dikkat":"肩の前側の痛み、手首の不調、肩の手術歴がある場合は膝をついたバリエーションから始め、理学療法士に相談するよう勧めてください。妊娠中は腹圧がかかるため、膝をついたバリエーションか壁を使ったバリエーションを選んでください。","s":105,"fig":true},{"n":95,"bolum":7,"ad":"前腕プランク","aile":"アームバランス","seviye":"初級","yogunluk":[3,5,6],"calisan":["腹横筋","腹直筋","前鋸筋"],"dengeleyen":["三角筋","大殿筋","大腿四頭筋"],"uzayan":[],"ozet":"体重を前腕に分散させ、手首に負担をかけずに体幹の筋力を養うプランクのバリエーションです。手首が敏感な生徒にとってよい代替となり、イルカのポーズへの準備にもなります。","asamalar":{"giris":"前腕を床に置き、肘を肩の真下にします。息を吐きながら脚を後ろへ伸ばしてつま先を立て、お尻を肩の高さにそろえます。","kalis":"前腕で床を押し、肩甲骨は背中で広く保ち、骨盤はニュートラルにします。首は背骨の延長に保ち、5〜10呼吸、または20〜40秒とどまります。","cikis":"息を吐きながら膝を床に下ろし、チャイルドポーズで休みます。"},"hata":{"ne":"お尻を高く持ち上げて負荷から逃げること。","neden":"腹筋が疲れると、体はお尻を上げて体幹のてこの腕を短くしようとします。","yonlendirme":"お尻は肩の高さに、尾骨はかかとの方へ。"},"soylenecekler":["肘は互いに寄せ、前腕は外へ引くように、床を抱え込みましょう。","胸を床から遠ざけて、背中が沈まないようにしましょう。","息を吐きながら、おへそのあたりを軽く引き込みましょう。"],"eller":{"nereye":"お尻のいちばん高いところ、または仙骨に、手のひらを平らにして。","nasil":"同意を得てから、高さの目安として手のひらを添えるだけにしてください。生徒自身がお尻の高さを調整します。下へ押さないでください。","ne_zaman_degil":"同意がない場合、腰の痛みを訴えている場合、または妊娠中に腹部の圧迫を感じている場合は触れずに、膝を床に下ろすよう勧めてください。"},"kolay":"膝を床につけたまま行うか、前腕を椅子の座面に置いて斜めの姿勢で行います。","zor":"お尻を左右に軽くひねるか、片脚を上げて3呼吸とどまります。","dikkat":"肩に不調がある場合はとどまる時間を短くしてください。妊娠中や産後は腹圧に注意して斜めのバリエーションを選び、必要に応じて医師や理学療法士に相談するよう勧めてください。呼吸を止めないようにしましょう。","s":106,"fig":true},{"n":96,"bolum":7,"ad":"サポート付き肩立ち（サーランバ・サルヴァーンガーサナ）","aile":"逆転","seviye":"上級","yogunluk":[4,6,7],"calisan":["脊柱起立筋","上腕三頭筋","腹直筋"],"dengeleyen":["大殿筋","腹横筋","回旋筋腱板（ローテーターカフ）"],"uzayan":["僧帽筋上部"],"ozet":"肩と上腕で体重を支え、脚を垂直に伸ばす逆転のポーズです。首を守るブランケットの準備と落ち着いた入り方・抜け方が、ポーズそのものと同じくらい大切です。","asamalar":{"giris":"肩を折りたたんだブランケットの端に、頭は床に置いて仰向けになります。息を吐きながら膝を胸に引き寄せ、お尻を持ち上げて両手で背中を支え、脚を片方ずつ上へ伸ばします。","kalis":"体重は首ではなく肩と上腕にのせ、首の後ろと床の間に小さなすき間を残します。目線は胸に固定し、呼吸はやわらかく。5〜15呼吸とどまります。","cikis":"息を吐きながら膝を額の方へ曲げ、手を床に下ろし、背骨を一つずつコントロールしながら床に下ろします。頭を上げずに数呼吸、仰向けのままでいます。"},"hata":{"ne":"ポーズの最中に頭を横に向けること。","neden":"体重がかかった状態で頸椎をひねると、首の組織に無防備な負荷がかかります。","yonlendirme":"首は動かさず、目線も動かさず。"},"soylenecekler":["ポーズの間は頭を横に向けず、目線は胸に置いておきましょう。","体重は肩にのせます。首に圧迫を感じたらすぐに下りてください。","両手を背中で肩甲骨の方へ歩かせ、肘は肩幅に保ちましょう。"],"eller":{"nereye":"準備の段階ではブランケットと肩の位置。ポーズ中に必要な場合のみ、生徒の肘の外側。","nasil":"同意を得てから、肘が開かないようにごく軽く内側へ導いてください。脚を上へ引いたり、体幹に体重をかけたりせず、より垂直な姿勢を無理に求めないでください。","ne_zaman_degil":"同意がない場合、首の痛みや首の不調の既往がある場合、妊娠中、生徒が震えている場合や呼吸を止めている場合は触れずに、安全な抜け方か壁に脚を上げるポーズを提案してください。"},"kolay":"壁に脚を上げるポーズか、仙骨の下にブロックを置いた橋のポーズを行います。次の段階として、足を壁につけたハーフの肩立ちに進みます。","zor":"脚を左右にひらくか合せきの形にしてバリエーションを加えます。準備がしっかりしていて首に圧迫がない場合に限ります。","dikkat":"首の不調、眼圧に関わる状態（緑内障など）、コントロールされていない高血圧、耳や副鼻腔の圧迫感、逆流性食道炎がある場合は行わないか、医師に相談するよう勧めてください。妊娠中に逆転のポーズを新しく始めることはしません。経験のある生徒でも医師の了承が前提です。ブランケットなしの平らな床で首に無理をさせないでください。月経中に行うかどうかは生徒の判断に任せます。","s":107,"fig":true},{"n":97,"bolum":7,"ad":"鋤のポーズ（ハラーサナ）","aile":"逆転","seviye":"上級","yogunluk":[4,6,8],"calisan":["腹直筋","上腕三頭筋","大腿四頭筋"],"dengeleyen":["回旋筋腱板（ローテーターカフ）","腹横筋"],"uzayan":["ハムストリングス","脊柱起立筋","僧帽筋上部"],"ozet":"肩立ちから足を頭の後ろの床へ下ろす、逆転と前屈を合わせたポーズです。体の後ろ側全体を伸ばします。首をニュートラルに保つには、焦らないことと補助具が必要です。","asamalar":{"giris":"肩を折りたたんだブランケットの端に置いて仰向けになります。息を吐きながらお尻を肩の上まで持ち上げ、両手で背中を支え、伸ばした脚をつま先が床か補助具に触れるところまで頭の後ろへ下ろします。","kalis":"お尻は肩の上、背骨は長く、体重は肩にのせたままにします。喉はやわらかく、目線は胸に固定します。呼吸が浅くなったら足を補助具にのせてください。5〜10呼吸とどまります。","cikis":"手を床に置き、息を吐きながら膝を曲げ、背骨をゆっくり丸めながら床に下ろします。頭を上げずに休みます。"},"hata":{"ne":"足を床に届かせようとして体重を首にのせること。","neden":"ハムストリングスや背中の筋肉が硬いと、体幹が首の方へ丸まり、首が過度に曲がります。","yonlendirme":"足は補助具へ、体重は肩へ。"},"soylenecekler":["足が床に届かなくても大丈夫です。椅子やブロックを使いましょう。","頭は横に向けず、目線は胸に置いておきましょう。","喉に圧迫を感じたら、膝を曲げるかポーズから抜けてください。"],"eller":{"nereye":"ポーズに入る前の、椅子やブロックの位置。ポーズ中は生徒の体に触れずにそばに立ちます。","nasil":"足の下に補助具を置くか、その距離を調整してください。脚やお尻を下や前へ押すことは決してしないでください。","ne_zaman_degil":"首の痛みや不調、妊娠、腰椎椎間板ヘルニアの既往を伝えられた場合、呼吸が苦しそうな場合、または同意がない場合は一切触れないでください。"},"kolay":"頭の後ろに置いた椅子の座面に足をのせるか、壁に脚を上げるポーズにとどまります。","zor":"膝を耳の横まで下ろして耳をふさぐポーズに移ります。首にまったく圧迫がない場合に限ります。","dikkat":"首の不調、眼圧に関わる状態、コントロールされていない高血圧、逆流性食道炎、腰椎椎間板の不調がある場合は行わないか、医師に相談するよう勧めてください。妊娠中は行いません。ブランケットの支えなしで、また満腹の状態では行わないでください。","s":108,"fig":true},{"n":98,"bolum":7,"ad":"頭立ちの準備（サーランバ・シルシャーサナ）","aile":"逆転","seviye":"中級","yogunluk":[4,6,7],"calisan":["三角筋","前鋸筋","腹直筋"],"dengeleyen":["腹横筋","回旋筋腱板（ローテーターカフ）","僧帽筋中部・下部"],"uzayan":["ハムストリングス"],"ozet":"前腕と頭頂を床につけ、足は床に置いたままお尻を肩の上へ運ぶ準備の段階です。前腕で体重を支え、首に負荷をかけないことを学ぶのが目的です。","asamalar":{"giris":"肘を肩幅で床に置き、指を組んで頭頂を手のひらの前に置きます。息を吸いながら膝を持ち上げ、足を小さな歩幅で肩の方へ近づけます。","kalis":"前腕でしっかり床を押し、肩は耳から遠ざけ、首は長くニュートラルに保ちます。頭への負荷は軽く、腕への負荷を重くします。3〜5呼吸とどまります。","cikis":"息を吐きながら膝を床に下ろし、頭を上げる前にチャイルドポーズで数呼吸休みます。"},"hata":{"ne":"体重を頭にあずけて肩を落とし込むこと。","neden":"肩まわりが十分に働いていないと、体は負荷を頸椎に移してしまいます。","yonlendirme":"前腕で押して、頭には羽根ほどの重さだけ。"},"soylenecekler":["頭の下に紙が一枚すべり込めるくらい、体重を腕で受け止めましょう。","足を歩かせながらお尻を肩の上へ。脚を跳ね上げないようにしましょう。","首に圧迫を感じたら、すぐに膝を下ろしてください。"],"eller":{"nereye":"生徒の横、お尻の側面の近く。必要な場合のみ骨盤の側面に。","nasil":"同意を得てから、バランスを崩したときに倒れないよう支える程度に、手を安定させて添えてください。お尻を持ち上げたり、脚を上へ引いたりしないでください。","ne_zaman_degil":"同意がない場合、首の痛みや不調がある場合、妊娠中、めまいを訴えている場合、または生徒が体重を頭にあずけている場合は触れずに、ポーズを終えるよう伝えてください。"},"kolay":"頭を床につけずにイルカのポーズで練習し、体重をすべて前腕で支えます。","zor":"壁の前で、膝を胸に引き寄せて一瞬保てるところまでお尻を肩の上へ運びます。脚を振り上げないでください。","dikkat":"首の不調、眼圧に関わる状態（緑内障など）、コントロールされていない高血圧、頭痛、逆流性食道炎がある場合は行わないか、医師に相談するよう勧めてください。妊娠中に新しく始めることはしません。硬い床ではなく折りたたんだマットの上で行い、決して無理をしないでください。","s":109,"fig":true},{"n":99,"bolum":7,"ad":"前腕倒立の準備（ピンチャ・マユーラーサナ）","aile":"逆転","seviye":"上級","yogunluk":[5,7,8],"calisan":["三角筋","前鋸筋","回旋筋腱板（ローテーターカフ）"],"dengeleyen":["腹横筋","腹直筋","大殿筋"],"uzayan":["広背筋"],"ozet":"壁の前で前腕を床につき、片脚を上へ伸ばす、前腕倒立に向けた準備です。肩のひらきと体幹のコントロールが必要で、頭は床につけません。","asamalar":{"giris":"壁に向かってイルカのポーズをとり、指先を壁から手のひら一枚分ほど離します。足を近づけ、息を吸いながら片脚を上へ伸ばします。","kalis":"肘は肩幅に保ち、肩は肘の真上に積み重ね、頭は床から浮かせます。肋骨を内側にまとめ、3〜5呼吸とどまったら脚を替えます。","cikis":"息を吐きながら上げた脚を床に下ろし、膝を床について、チャイルドポーズで休みます。"},"hata":{"ne":"肘が外側へ開いてしまうこと。","neden":"肩関節の可動域が限られていると、体重がかかった腕は開くことで支えを探します。","yonlendirme":"肘は肩幅に、前腕は平行に。"},"soylenecekler":["肘の間にブロックをはさみ、それを押し合いましょう。","胸を壁の方へ運び、頭は床から浮かせておきましょう。","蹴り上げるのではなく、脚の長さを使って上がりましょう。"],"eller":{"nereye":"生徒の横で、肘の外側、または上げた脚のふくらはぎの近く。","nasil":"同意を得てから、肘が開かないよう軽く内側へ導くか、上げた脚が落ちないよう手を構えておいてください。脚を引っぱって持ち上げないでください。","ne_zaman_degil":"同意がない場合、肩の不安定感や痛み、首の不調、妊娠、めまいがある場合は触れずに、イルカのポーズにとどまるよう勧めてください。"},"kolay":"肘の間にブロック、腕にストラップを使い、イルカのポーズで足を歩かせます。","zor":"壁の前で両脚をコントロールしながら上げ、かかとを壁にあずけます。準備の段階が安定している場合に限ります。","dikkat":"肩の不調、首の不調、眼圧に関わる状態、コントロールされていない高血圧がある場合は行わないか、医師に相談するよう勧めてください。妊娠中に新しく始めることはしません。肩が温まっていない状態や、蹴り上げての入り方は避けてください。","s":110,"fig":true},{"n":100,"bolum":7,"ad":"壁を使った倒立の準備（アド・ムカ・ヴリクシャーサナ）","aile":"逆転","seviye":"中級","yogunluk":[5,7,8],"calisan":["三角筋","上腕三頭筋","前鋸筋"],"dengeleyen":["腹横筋","腹直筋","回旋筋腱板（ローテーターカフ）"],"uzayan":["ハムストリングス","広背筋"],"ozet":"手を床に、足を壁の腰の高さに置き、体が直角の形になる倒立の準備です。腕をまっすぐ保ち肩をひらいたまま体を支えること、そして怖さをコントロールしながら扱うことを学びます。","asamalar":{"giris":"壁に背を向けて下向きの犬のポーズをとり、かかとを壁の根元に置きます。息を吸いながら片足を腰の高さで壁に押し当て、もう片方も続けて、足で壁を上へ歩いていきます。","kalis":"手は肩幅、肩は手首の真上、腕はまっすぐにし、お尻を肩の上に積み重ねます。目線は両手の間、肋骨は内側に。3〜5呼吸とどまります。","cikis":"息を吐きながら足を片方ずつ壁から下ろし、膝を床について、チャイルドポーズで頭を休めます。"},"hata":{"ne":"腰が反って、肋骨が前へ開いてしまうこと。","neden":"肩の屈曲が制限されていると、体は腰椎を反らせることで腕を上げる角度を補おうとします。","yonlendirme":"肋骨は内側へ、お尻は肩の上へ。"},"soylenecekler":["指で床をつかみ、手のひらの中央を少し浮かせましょう。","床を押して、肩は耳に寄せずに上へ伸ばしましょう。","いつでも膝を床に下ろしてかまいません。"],"eller":{"nereye":"生徒の横で骨盤の側面。準備の段階では、手と壁の距離。","nasil":"同意を得てから、骨盤が肩の上にくる位置を軽く導いて示し、足がすべらないよう構えておいてください。生徒を上へ持ち上げないでください。","ne_zaman_degil":"同意がない場合、手首や肩の痛み、首の不調、妊娠、めまいがある場合は触れずに、ポーズから抜けるよう勧めてください。"},"kolay":"壁の足の位置を低くするか、膝を曲げた半分の直角の形にとどまります。または下向きの犬のポーズで肩の練習だけを行います。","zor":"直角の形から片脚を上へ垂直に伸ばすか、壁に向かう完全な倒立へのコントロールされた入り方に挑戦します。","dikkat":"手首、肘、肩の不調、眼圧に関わる状態、コントロールされていない高血圧、頭痛がある場合は行わないか、医師に相談するよう勧めてください。妊娠中に新しく始めることはしません。壁との距離は先に床の上で測り、すべりやすい床は使わないでください。","s":111,"fig":true},{"n":101,"bolum":7,"ad":"サイドクロウ（パールシュヴァ・バカーサナ）","aile":"アームバランス","seviye":"上級","yogunluk":[6,7,9],"calisan":["腹斜筋","上腕三頭筋","前鋸筋","大胸筋・小胸筋"],"dengeleyen":["腹直筋","内転筋群","三角筋"],"uzayan":[],"ozet":"ねじったしゃがみ姿勢から、そろえた両膝を片方の上腕にのせるアームバランスです。ねじりの力とチャトランガ型の腕のアライメントを組み合わせます。","asamalar":{"giris":"膝をそろえてしゃがみ、息を吐きながら右へねじって、左の上腕を右の太ももの外側にかけます。手を肩幅で床に置き、肘を曲げて体重を前へ運びます。","kalis":"肘は手首の真上、肩は肘の高さに保ち、両膝は互いに押し合います。胸は前へ、目線は手の前に。3〜5呼吸とどまります。","cikis":"息を吐きながら足を床に下ろし、しゃがみ姿勢に戻って体幹を中央に戻し、反対側も行います。"},"hata":{"ne":"体重を後ろに残したまま足を床から浮かせようとすること。","neden":"アームバランスでは重心を手の上へ運ばないとてこが生まれず、体は後ろへ倒れます。","yonlendirme":"胸を前へ、足は自然に軽くなります。"},"soylenecekler":["まずねじり、次にバランス。お尻も膝と同じ方向へ回しましょう。","膝はぴったりそろえて、肋骨同士を近づけましょう。","前にクッションを置いて、落ちる心配をせずに前へ傾きましょう。"],"eller":{"nereye":"生徒の前の床にクッションやブロックを置きます。必要な場合は肩の前側に。","nasil":"同意を得てから、肩が下がりすぎないよう軽く支えてください。お尻や脚を持ち上げないでください。","ne_zaman_degil":"同意がない場合、手首や肩の痛み、腰の不調、妊娠がある場合は触れないでください。妊娠中のねじったアームバランスは勧めません。"},"kolay":"足をブロックの上に置くか、お尻をブロックにのせてねじったしゃがみ姿勢にとどまります。","zor":"上側の脚をまっすぐ伸ばすか、両脚をそろえて横へ伸ばし、エーカ・パーダ・クンディンニャーサナの準備へ進みます。","dikkat":"手首、肘、肩、腰に不調がある場合は練習を見送るか、理学療法士に相談するよう勧めてください。妊娠中は深いねじりと腹部への圧迫があるため行いません。体が温まっていない状態や、カラスのポーズが安定していない状態では入らないでください。","s":112,"fig":true},{"n":102,"bolum":7,"ad":"ホタルのポーズの準備（ティッティバーサナ）","aile":"アームバランス","seviye":"上級","yogunluk":[6,8,9],"calisan":["上腕三頭筋","前鋸筋","腸腰筋","大腿四頭筋"],"dengeleyen":["腹直筋","内転筋群","三角筋"],"uzayan":["ハムストリングス","内転筋群"],"ozet":"脚の後ろから手を床につき、脚を上腕に巻きつけるアームバランスの準備です。股関節の屈曲、ハムストリングスの柔軟性、腕の筋力を同時に必要とします。","asamalar":{"giris":"足を腰幅より少し広くして前屈し、膝を曲げて肩を片方ずつ膝の裏側に入れます。手をかかとの後ろの床に置き、息を吐きながら手の上に座るように体重を後ろへ移します。","kalis":"内ももで上腕をはさみ、腕はまっすぐ伸ばそうとし、胸は前へ伸びます。足は軽く浮いても床に残っていてもかまいません。3〜5呼吸とどまります。","cikis":"息を吐きながら足を床に下ろし、手を脚の間から抜いて、立位前屈で休みます。"},"hata":{"ne":"ハムストリングスの準備が整っていないのに、脚を伸ばそうとして背中を丸めすぎること。","neden":"ハムストリングスの柔軟性が足りないと骨盤が前へ傾かず、動きを腰椎で補ってしまいます。","yonlendirme":"膝は曲げたまま、腕を太ももにしっかりおさめます。"},"soylenecekler":["肩をできるだけ深く膝の裏側に入れましょう。","内ももで腕を抱き込み、腕を脚の棚にしましょう。","足が浮かなくても大丈夫です。手に体重を感じられれば十分です。"],"eller":{"nereye":"生徒の後ろで、お尻の側面。または手の後ろにブロックを置きます。","nasil":"同意を得てから、後ろへ倒れたときのためにそばで構えるだけにしてください。脚を開いたり、お尻を持ち上げたりしないでください。","ne_zaman_degil":"同意がない場合、ハムストリングスの損傷歴、手首や肩の痛み、腰の不調、妊娠がある場合は触れないでください。"},"kolay":"手の下にブロックを置き、足を床に残したまま腕に寄りかかるだけにします。","zor":"足を床から浮かせ、脚を前へ伸ばして完成形のホタルのポーズに近づきます。","dikkat":"ハムストリングスの損傷、手首や肩の不調、腰椎椎間板の不調がある場合は行わないか、理学療法士に相談するよう勧めてください。妊娠中は行いません。ハムストリングスが十分に温まる前には入らないでください。","s":113,"fig":true},{"n":103,"bolum":7,"ad":"八角のポーズ（アシュターヴァクラーサナ）","aile":"アームバランス","seviye":"上級","yogunluk":[6,8,9],"calisan":["腹斜筋","上腕三頭筋","大胸筋・小胸筋","内転筋群"],"dengeleyen":["前鋸筋","腹直筋","三角筋"],"uzayan":["ハムストリングス"],"ozet":"片脚を上腕にのせ、脚を交差させて横へ伸ばす左右非対称のアームバランスです。ねじり、股関節の柔軟性、チャトランガ型の腕の筋力を一つにまとめます。","asamalar":{"giris":"座った姿勢から右脚を右肩の上にのせ、手をお尻の横に置きます。息を吸いながらお尻を床から持ち上げ、左足を右の足首の上に交差させます。","kalis":"息を吐きながら肘を曲げ、胸を前と下へ下ろします。脚は右へ伸び、右腕をはさみます。肩は肘の高さ、目線は前に。3〜5呼吸とどまります。","cikis":"息を吸いながら胸を持ち上げ、足の交差をほどいてお尻を床に下ろし、反対側も行います。"},"hata":{"ne":"脚を肩にのせようとして膝関節に無理をかけること。","neden":"股関節の外旋が足りないと動きを膝で補うことになり、膝に横方向の負担がかかります。","yonlendirme":"動きは股関節から、膝は楽なままで。"},"soylenecekler":["脚はできるだけ肩の高い位置にのせましょう。肘の上ではありません。","足首を交差させてロックし、脚で腕をはさみましょう。","胸が前へ下りるのに合わせて、肘を後ろへ曲げましょう。"],"eller":{"nereye":"生徒の前で、肩の前側の近く。またはお尻の下にブロックを置きます。","nasil":"同意を得てから、肩が下がりすぎないよう軽く支えてください。脚を肩に押しつけたり、交差を無理に深めたりしないでください。","ne_zaman_degil":"同意がない場合、膝や股関節の痛み、手首や肩の不調、妊娠がある場合は触れないでください。"},"kolay":"手の下にブロックを置いてお尻を持ち上げ、脚を交差させたまま浮かせずにとどまります。","zor":"腕をまっすぐにした状態から肘を曲げて下り、また上がります。コントロールしながら繰り返します。","dikkat":"膝、股関節、手首、肩に不調がある場合は行わないか、理学療法士に相談するよう勧めてください。妊娠中は行いません。股関節とハムストリングスが温まる前には入らないでください。","s":114,"fig":true},{"n":104,"bolum":7,"ad":"カラスからチャトランガへの移行","aile":"アームバランス","seviye":"上級","yogunluk":[6,8,9],"calisan":["上腕三頭筋","前鋸筋","大胸筋・小胸筋","腹直筋"],"dengeleyen":["三角筋","腹横筋","回旋筋腱板（ローテーターカフ）"],"uzayan":[],"ozet":"カラスのポーズから脚を後ろへ跳ぶか伸ばすかして、そのままチャトランガに下りるフローの移行です。アームバランスの筋力をコントロールされた下り方と結びつけることを学びます。","asamalar":{"giris":"カラスのポーズを組みます。膝は上腕の裏側、体重は手の上、目線は前に。息を吐きながら胸をもう少し前へ運びます。","kalis":"一瞬とどまる間も肘は曲げたままにし、脚を後ろへ伸ばすときは肩を肘の高さに、体幹を床と平行に保ちます。チャトランガで1〜2呼吸とどまります。","cikis":"息を吸いながら上向きの犬のポーズかコブラのポーズへ移るか、膝と胸をコントロールしながら床に下ろします。"},"hata":{"ne":"脚を後ろへ送るときに肩が床へ落ち込むこと。","neden":"下りる途中で上腕三頭筋と前鋸筋が負荷を受け止められないと、体幹が肩の前へ落ちてしまいます。","yonlendirme":"肘は曲げたまま、肩は肘の高さに。"},"soylenecekler":["まずカラスのポーズで安定してから、脚を片方ずつ後ろへ伸ばしましょう。","跳ぶ必要はありません。歩いて下がっても同じ移行です。","下りながら息を吐き、目線を前に保って胸を長く伸ばしましょう。"],"eller":{"nereye":"生徒の横で、肩の前側の近く。必要な場合は胸の下にボルスターを置きます。","nasil":"同意を得てから、肩が肘の高さより下に落ちないよう軽く支えてください。脚を後ろへ引っぱらないでください。","ne_zaman_degil":"同意がない場合、手首や肩の痛みがある場合、妊娠中、または生徒が素早く跳んでいる最中は触れずに、言葉の合図で伝えてください。"},"kolay":"カラスのポーズから足を床に下ろし、歩いてプランクへ移り、膝をついたチャトランガに下ります。","zor":"カラスのポーズから両脚をそろえて後ろへ跳び、床に触れずにそのままチャトランガで止まります。","dikkat":"手首、肘、肩に不調がある場合や肩の手術歴がある場合は行わないか、理学療法士に相談するよう勧めてください。妊娠中は行いません。カラスのポーズとチャトランガがそれぞれ安定する前に移行を始めないでください。","s":115,"fig":true},{"n":105,"bolum":8,"ad":"安楽座（スカーサナ）","aile":"座位","seviye":"初級","yogunluk":[1,2,3],"calisan":["脊柱起立筋","多裂筋","横隔膜"],"dengeleyen":["腹横筋","骨盤底筋群"],"uzayan":["内転筋群","梨状筋"],"ozet":"脚を楽に組む基本の座り方です。クラスの始まりと終わりに、呼吸への気づき、意図の設定、心を落ち着けるために用います。","asamalar":{"giris":"折りたたんだブランケットの端に座り、すねの中ほどで脚を組みます。息を吸いながら坐骨に落ち着き、背骨を上へ伸ばします。","kalis":"骨盤はニュートラル、膝は股関節と同じ高さかそれより下に。肩は力を抜き、あごを軽く引きます。呼吸を見守りながら1〜5分とどまり、脚の組み方を替えます。","cikis":"息を吐きながら手を床に置き、脚を前へ伸ばして足首を軽くゆらします。"},"hata":{"ne":"膝が股関節より高い状態で、腰が丸まって座ること。","neden":"股関節まわりや内ももが硬いと骨盤が後ろへ傾き、背骨が丸まります。","yonlendirme":"お尻を高く、膝は下へ。"},"soylenecekler":["坐骨を感じて、頭頂を上へ伸ばしましょう。","手を膝に置いて、肩を耳から遠ざけましょう。","このポーズでは楽であることが大切です。必要ならサポートを足しましょう。"],"eller":{"nereye":"生徒の後ろで、肩甲骨の上、または肩の上。","nasil":"同意を得てから、肩を軽く後ろと下へ導くか、背中に指先で触れて伸ばす方向を示してください。","ne_zaman_degil":"同意がない場合、生徒が目を閉じていて予告なしになる場合、または膝や股関節の痛みを訴えている場合は触れないでください。"},"kolay":"より高いサポートの上に座る、膝の下にブロックを置く、または背中を壁にあずけます。","zor":"サポートなしで座るか、次の段階として半蓮華座に進みます。","dikkat":"膝や股関節に痛みがある場合は高めのサポートを使うか、椅子に座ってください。脚にしびれが出たら姿勢を変えます。痛みが続く場合は、医師や理学療法士に相談するよう勧めてください。","s":117,"fig":true},{"n":106,"bolum":8,"ad":"英雄座（ヴィーラーサナ）","aile":"座位","seviye":"中級","yogunluk":[2,4,6],"calisan":["脊柱起立筋","多裂筋"],"dengeleyen":["腹横筋","骨盤底筋群"],"uzayan":["大腿四頭筋","前脛骨筋"],"ozet":"足をお尻の両側に置き、坐骨を両足の間におさめて座る、ひざまずいた座り方です。太ももの前側と足首の前側を伸ばします。サポートの使用が基本です。","asamalar":{"giris":"膝をそろえてひざまずき、足は腰幅より少し広く置きます。ふくらはぎの筋肉を手で外側へ流し、息を吐きながら両足の間のブロックに座ります。","kalis":"足の甲は床につき、つま先は後ろを向きます。膝は腰幅に、背骨はまっすぐに。膝にまったく圧迫がない状態で1〜3分とどまります。","cikis":"息を吸いながら手を床に置き、お尻を持ち上げて四つ這いになり、脚を片方ずつ後ろへ伸ばします。"},"hata":{"ne":"サポートなしで床に座ろうとして膝に無理をかけること。","neden":"大腿四頭筋や足首の前側が硬いと、膝関節の内側の組織に負担がかかります。","yonlendirme":"ブロックを高くします。膝が楽なら、それが適切な高さです。"},"soylenecekler":["膝に少しでも違和感があれば、すぐにサポートを高くしましょう。","足の裏は天井に向け、かかとが外へ逃げないようにしましょう。","坐骨から頭頂まで、上へ伸びていきましょう。"],"eller":{"nereye":"生徒の後ろで肩の上。準備の段階ではブロックの位置。","nasil":"同意を得てから、肩を軽く後ろへ導くか、ブロックを適切な高さに調整してください。肩から下へ押すことは決してしないでください。","ne_zaman_degil":"同意がない場合、膝の痛みや膝の手術歴がある場合、または足首の不快感を訴えている場合は触れないでください。"},"kolay":"ブロックを複数重ねて座る、足首の下に丸めたブランケットを置く、または膝の裏に薄いタオルをはさみます。","zor":"サポートの高さを少しずつ下げるか、後ろへ寄りかかって半分の仰向けの英雄座（スプタ・ヴィーラーサナ）に移ります。","dikkat":"膝の不調、半月板や靱帯の損傷歴、足首の不調がある場合は行わないか、理学療法士に相談するよう勧めてください。静脈瘤や脚の血行に関する気になる症状がある場合は時間を短くしてください。膝に痛みが出たらすぐにポーズから抜けます。","s":118,"fig":true},{"n":107,"bolum":8,"ad":"杖のポーズ（ダンダーサナ）","aile":"座位","seviye":"初級","yogunluk":[2,4,5],"calisan":["大腿四頭筋","脊柱起立筋","腸腰筋"],"dengeleyen":["腹横筋","僧帽筋中部・下部"],"uzayan":["ハムストリングス","腓腹筋・ヒラメ筋"],"ozet":"脚を前へまっすぐ伸ばし、背骨を立てて座るポーズです。座位の前屈やねじりの基本となるアライメントをつくります。","asamalar":{"giris":"座って脚をそろえて前へ伸ばし、お尻の肉を手で後ろと横へ流して坐骨に落ち着きます。息を吸いながら手をお尻の横の床に押し当てます。","kalis":"足首は曲げてつま先を上に向け、太ももは床を押し、背骨はまっすぐ、胸はひらきます。5〜8呼吸とどまります。","cikis":"息を吐きながら手の力をゆるめ、脚を軽くゆらすか、膝を曲げてリラックスします。"},"hata":{"ne":"骨盤が後ろへ傾いて背中が丸まること。","neden":"ハムストリングスが硬いと坐骨を前へ引っぱり、背骨がまっすぐ保てなくなります。","yonlendirme":"ブランケットに座って、胸を上へ。"},"soylenecekler":["かかとで前へ伸びて、つま先を顔の方へ向けましょう。","手で床を押して、背骨を上へ伸ばしましょう。","膝は少し曲げてもかまいません。背中がまっすぐなことの方が大切です。"],"eller":{"nereye":"生徒の後ろで、肩甲骨の下端、または腰のあたり。","nasil":"同意を得てから、指先で背骨が伸びる方向を示してください。脚を床に押しつけないでください。","ne_zaman_degil":"同意がない場合、または腰やハムストリングスの痛みを訴えている場合は触れないでください。"},"kolay":"折りたたんだブランケットに座る、膝の下に丸めたタオルを置く、または背中を壁にあずけます。","zor":"手を床から離して腕を上へ伸ばすか、手のひらで床を押してお尻を軽く持ち上げてみます。","dikkat":"腰やハムストリングスに不調がある場合は膝を曲げ、高めのサポートを使ってください。痛みが続く場合は理学療法士に相談するよう勧めてください。","s":119,"fig":true},{"n":108,"bolum":8,"ad":"蓮華座と半蓮華座（パドマーサナ）","aile":"座位","seviye":"上級","yogunluk":[3,5,7],"calisan":["脊柱起立筋","多裂筋"],"dengeleyen":["骨盤底筋群","腹横筋"],"uzayan":["梨状筋","中殿筋・小殿筋","内転筋群"],"ozet":"足を反対側の太ももの上にのせる伝統的な座り方です。半蓮華座では片足だけを上にのせます。股関節の大きな外旋が必要で、膝を守ることを最優先にします。","asamalar":{"giris":"安楽座から始めます。息を吐きながら右膝を曲げ、すねを両手で持ち、股関節から回す動きで右足を左の太ももの付け根近くにのせます。","kalis":"足首はニュートラルに保ち、足の外側を三日月のように曲げません。膝は床の方へ楽に。背骨はまっすぐ、呼吸は穏やかに。1〜3分とどまり、左右を替えます。","cikis":"息を吐きながら足を両手で持ってゆっくり下ろし、脚を前へ伸ばして膝を軽くゆらします。"},"hata":{"ne":"足を太ももへ引き寄せるために膝をひねること。","neden":"股関節の外旋が足りないと、回旋を膝関節で補うことになり、半月板に負担がかかります。","yonlendirme":"股関節から回し、膝はそれについていくだけ。"},"soylenecekler":["膝に少しでも違和感があれば戻りましょう。蓮華座は股関節から生まれます。","足を太ももの奥までのせ、足首はまっすぐ保ちましょう。","半蓮華座も、それだけで完全な練習です。"],"eller":{"nereye":"触れる代わりに、生徒が自分の手ですねをどう持つかを見せてください。必要な場合は高さを出すブランケットを整えます。","nasil":"膝を下へ押したり、足を上へ引いたりすることは決してしないでください。サポートを置くだけにします。","ne_zaman_degil":"膝や股関節の痛み、膝の手術歴、妊娠がある場合、または同意がない場合は一切触れないでください。"},"kolay":"高めのサポートに座って半蓮華座を行い、下側の足の下か、浮いている膝の下にブロックを置きます。","zor":"完全な蓮華座でとどまる時間を延ばすか、この座り方のまま呼吸法に移ります。膝がまったく楽な場合に限ります。","dikkat":"膝、股関節、足首に不調がある場合は行わず、安楽座を選んで、理学療法士に相談するよう勧めてください。妊娠中は靱帯がゆるみやすいため無理をしないでください。体が温まる前には入らないでください。","s":120,"fig":true},{"n":109,"bolum":8,"ad":"サポート付きチャイルドポーズ","aile":"リストラティブ","seviye":"初級","yogunluk":[1,2,3],"calisan":["横隔膜","腹横筋"],"dengeleyen":["骨盤底筋群","多裂筋"],"uzayan":["脊柱起立筋","広背筋","大殿筋"],"ozet":"体幹を縦に置いたボルスターにあずける、リストラティブなチャイルドポーズです。呼吸が背中に広がるのを観察し、強度の高いシークエンスの後に休むために用います。","asamalar":{"giris":"膝を開き、足の親指同士を触れ合わせてひざまずき、ボルスターを膝の間に縦に置きます。息を吐きながら体幹をボルスターの上にあずけます。","kalis":"胸とお腹をボルスターにあずけ、顔は片側に向け、腕は楽にします。呼吸が背中の後ろ側へ広がるのを感じながら、2〜5分とどまります。途中で顔の向きを替えます。","cikis":"息を吸いながら手で床を押し、背骨をゆっくり起こしてかかとの上に座ります。"},"hata":{"ne":"サポートが低すぎてお尻が浮き、首に負担がかかること。","neden":"股関節と膝の屈曲が限られていると体幹がボルスターに届かず、体重が肩と首に残ります。","yonlendirme":"ボルスターを高くして、体幹をすべてあずけます。"},"soylenecekler":["サポートに体重をすべてあずけて、ボルスターに支えてもらいましょう。","息を吸うたびに、背中が広がるのを感じましょう。","途中で、顔を反対側に向けましょう。"],"eller":{"nereye":"仙骨の上、または背骨の両側の肩甲骨の下に、手のひらを平らにして。","nasil":"同意を得てから、手のひらを仙骨に軽く置き、体重をかけずに数呼吸そのままにしてください。押さないでください。","ne_zaman_degil":"同意がない場合、生徒が目を閉じていて予告なしになる場合、または膝や腰の痛みを訴えている場合は触れないでください。"},"kolay":"ボルスターの下にブロックを置いて高くし、お尻とかかとの間にブランケットをはさみます。","zor":"ボルスターを低くするか、お尻をかかとにもう少し近づけて、とどまる時間を延ばします。","dikkat":"膝に不調がある場合は膝の裏にブランケットをはさんでください。妊娠中は膝をお腹のスペースができるくらい広く開き、サポートを高くします。不快感がある場合は医師に相談するよう勧めてください。","s":121,"fig":true},{"n":110,"bolum":8,"ad":"ボルスターを使った魚のポーズ","aile":"リストラティブ","seviye":"初級","yogunluk":[1,2,4],"calisan":["横隔膜","脊柱起立筋"],"dengeleyen":["腹横筋","僧帽筋中部・下部"],"uzayan":["大胸筋・小胸筋","腹直筋"],"ozet":"背中を縦に置いたボルスターやブロックにあずけて胸をひらく、リストラティブのポーズです。長時間座っている生徒の胸の前側を、やさしくひらくために用います。","asamalar":{"giris":"ボルスターの短い辺に背中を向けて座ります。息を吐きながら肘に寄りかかり、背中をボルスターに沿って倒し、頭をブランケットで支えます。","kalis":"ボルスターは肩甲骨の下、頭の後ろは支えられ、あごは胸の方へ軽く引きます。腕は手のひらを上にして横へひらき、3〜5分とどまります。","cikis":"息を吐きながら膝を曲げて横向きになり、数呼吸待ってから手で床を押して起き上がります。"},"hata":{"ne":"頭が支えなしで後ろへ落ちること。","neden":"ボルスターが高いと頭が床に届かず、首が反りすぎた状態を強いられます。","yonlendirme":"頭の下にブランケットを、あごは少し下へ。"},"soylenecekler":["頭の下にサポートを置いて、首を楽にしましょう。","腕は好きなだけひらきましょう。肩が引っぱられるなら、手のひらをお腹に置きましょう。","呼吸で、胸の前側がゆっくり持ち上がるのを感じましょう。"],"eller":{"nereye":"頭の下のブランケットの調整、または肩の前側。","nasil":"頭と首の下のブランケットを、あごが軽く下がる程度に整えてください。肩に触れる場合は同意を得てからにし、床に押しつけないでください。","ne_zaman_degil":"同意がない場合、首の不調や肩の痛みを訴えている場合、または妊娠後期で仰向けがつらい場合は触れないでください。"},"kolay":"ボルスターの代わりにブロック2つを最も低い高さで使い、1つを肩甲骨の下、もう1つを頭の下に置きます。膝は曲げます。","zor":"足裏を合わせて合せきの脚でとどまるか、腕を頭の上へ伸ばします。","dikkat":"首や腰に不調がある場合はサポートの高さを下げてください。妊娠後期は体幹をより起こした傾斜で支え、不快感がある場合は医師に相談するよう勧めてください。めまいが出たらゆっくりポーズから抜けます。","s":122,"fig":true},{"n":111,"bolum":8,"ad":"コンストラクティブレスト","aile":"仰向け","seviye":"初級","yogunluk":[1,1,2],"calisan":["横隔膜","腹横筋"],"dengeleyen":["骨盤底筋群","内転筋群"],"uzayan":["腸腰筋"],"ozet":"仰向けで膝を曲げて互いにもたれさせ、足を床に置いて休む姿勢です。骨盤と腰がニュートラルに落ち着くのを観察し、呼吸に戻るために用います。","asamalar":{"giris":"仰向けになり、膝を曲げて足を腰幅より広く床に置きます。息を吐きながら膝を内側へ倒し、互いにもたれさせます。","kalis":"骨盤と腰は床に重くあずけ、腕はお腹の上か体の横で力を抜きます。息を吸うとお腹が、吐くと腰が床に落ち着きます。3〜10分とどまります。","cikis":"息を吸いながら膝を立て、横向きになり、手で床を押してゆっくり起き上がります。"},"hata":{"ne":"膝をそろえておくために、内ももをずっと締め続けること。","neden":"足の幅が狭すぎると膝が外へ倒れ、生徒はそれを筋力で補おうとします。","yonlendirme":"足の幅を広げて、膝を互いにもたれさせます。"},"soylenecekler":["膝を互いにもたれさせましょう。何もしなくて大丈夫です。","腰が床に溶けていくのを、無理せず感じましょう。","吐く息を、少しずつ長くしていきましょう。"],"eller":{"nereye":"膝の上、または肩の上に、手のひらを平らにして。","nasil":"同意を得てから、手のひらを膝か肩にそっと置き、体重をかけずにそのまま落ち着いてください。","ne_zaman_degil":"同意がない場合、生徒が目を閉じていて予告なしになる場合、または妊娠後期で仰向けがつらい場合は触れないでください。"},"kolay":"頭の下に薄いブランケットを、膝の間にブロックか厚めのブランケットを置きます。","zor":"とどまる時間を延ばし、吐く息を吸う息の2倍の長さにしてみます。","dikkat":"妊娠後期で仰向けがつらい場合は横向きで休む姿勢に切り替え、医師に相談するよう勧めてください。腰に不快感がある場合は足の幅を調整してください。","s":123,"fig":true},{"n":112,"bolum":8,"ad":"仰向けで足の親指をつかむポーズ（横）","aile":"仰向け","seviye":"中級","yogunluk":[2,4,6],"calisan":["大腿四頭筋","腹斜筋"],"dengeleyen":["中殿筋・小殿筋","腹横筋","腰方形筋"],"uzayan":["内転筋群","ハムストリングス"],"ozet":"仰向けでストラップを使って片脚を横へひらき、反対側のお尻を床に固定するポーズです。内ももの長さと骨盤のコントロールを同時に練習します。","asamalar":{"giris":"仰向けになり、右足の裏にストラップをかけて脚を上へ伸ばします。息を吐きながらストラップを右手で持って右脚を横へひらき、左手は左の腰骨の前に置きます。","kalis":"左のお尻は床に重く残し、骨盤は右へ回しません。右の膝のお皿は天井に向けます。呼吸に合わせて5〜8呼吸とどまり、反対側も行います。","cikis":"息を吸いながらストラップで脚を中央に戻し、膝を曲げて足を床に下ろします。"},"hata":{"ne":"脚を床に下ろそうとして反対側のお尻が床から浮くこと。","neden":"内転筋群が硬いと、動きを骨盤の回旋で補ってしまいます。","yonlendirme":"反対側のお尻は床に、脚はサポートの上へ。"},"soylenecekler":["左のお尻を床に固定しましょう。脚は下りるところまでで十分です。","右脚の外側の下にブロックを置いてもかまいません。","膝のお皿を天井に向けて、脚が内側へ回らないようにしましょう。"],"eller":{"nereye":"反対側の腰骨の前の出っぱり（上前腸骨棘）の上に、手のひらを平らにして。","nasil":"同意を得てから、反対側の腰を軽く床の方へ安定させてください。ひらいた脚を下へ押さないでください。","ne_zaman_degil":"同意がない場合、鼠径部や内ももの痛み、股関節の不調、産後の骨盤帯の痛み、妊娠がある場合は触れないでください。"},"kolay":"膝を曲げたままにするか、ひらいた脚の下にブロックかボルスターを置きます。","zor":"ストラップを離して足の親指を指2本でつかむか、サポートなしで脚を保ちます。","dikkat":"鼠径部、股関節、仙腸関節のあたりに痛みがある場合は動きの幅を小さくし、理学療法士に相談するよう勧めてください。妊娠中は靱帯がゆるみやすいため必ずサポートを使い、妊娠後期は仰向けの時間を短くしてください。","s":124,"fig":true},{"n":113,"bolum":8,"ad":"ブロックを使った橋のポーズ","aile":"リストラティブ","seviye":"初級","yogunluk":[1,2,3],"calisan":["横隔膜","大殿筋"],"dengeleyen":["腹横筋","骨盤底筋群","内転筋群"],"uzayan":["腸腰筋","腹直筋","大腿四頭筋"],"ozet":"仙骨の下に置いたブロックで骨盤を支える、受け身の橋のポーズです。筋肉の努力なしに股関節の前側をやさしくひらき、クラスのクールダウンに適しています。","asamalar":{"giris":"仰向けで膝を曲げ、足を腰幅に置きます。息を吸いながらお尻を持ち上げ、ブロックを腰椎ではなく仙骨の骨の下に置きます。","kalis":"体重をブロックにあずけ、お尻の力を抜き、膝は腰幅に保ちます。腕は体の横に置き、1〜3分とどまります。","cikis":"息を吸いながらお尻を持ち上げてブロックを外し、息を吐きながら背骨をゆっくり床に下ろします。膝を胸に引き寄せます。"},"hata":{"ne":"ブロックを腰の下に置いてしまうこと。","neden":"サポートが腰椎にあたると腰が反りすぎて、詰まった感覚が生じます。","yonlendirme":"ブロックは仙骨の平らな骨の上に、腰ではありません。"},"soylenecekler":["ブロックに体重をすべてあずけましょう。お尻を締める必要はありません。","膝は腰幅に。互いにもたれさせてもかまいません。","腰に詰まりを感じたら、ブロックを一段低くしましょう。"],"eller":{"nereye":"ブロックの位置。必要な場合は膝の外側。","nasil":"同意を得てから、ブロックを仙骨の下の正しい位置へずらすのを手伝うか、膝を軽く腰幅へ導いてください。骨盤を押さないでください。","ne_zaman_degil":"同意がない場合、腰や仙腸関節の痛み、妊娠後期、首の不調がある場合は触れないでください。"},"kolay":"ブロックを最も低い高さに寝かせるか、ブロックの代わりに折りたたんだブランケットを使います。","zor":"ブロックを中間の高さにし、脚を片方ずつ前へ伸ばします。","dikkat":"腰や首に不調がある場合はブロックを最も低くして使い、不快感があれば理学療法士に相談するよう勧めてください。妊娠後期は仰向けの時間を短くするか、横向きで休む姿勢に切り替えてください。","s":125,"fig":true},{"n":114,"bolum":8,"ad":"膝を胸に抱えるポーズ（アパーナーサナ）","aile":"仰向け","seviye":"初級","yogunluk":[1,2,3],"calisan":["横隔膜","腹直筋"],"dengeleyen":["腹横筋","骨盤底筋群"],"uzayan":["脊柱起立筋","大殿筋","腰方形筋"],"ozet":"仰向けで両膝を胸に引き寄せるシンプルなポーズです。後屈の後に腰まわりをニュートラルに戻し、呼吸によるお腹の動きを感じてもらうために用います。","asamalar":{"giris":"仰向けになり、息を吐きながら両膝を胸に引き寄せます。手をすねの上か膝の裏に置きます。","kalis":"仙骨は床の近くに保ち、肩と頭は床で力を抜きます。息を吸うと膝が少し離れ、吐くと近づきます。5〜10呼吸とどまります。","cikis":"息を吸いながら足を片方ずつ床に下ろし、脚を伸ばします。"},"hata":{"ne":"膝を引き寄せるときに頭と肩が床から浮くこと。","neden":"腕で力を入れると首や肩の筋肉も働いてしまい、上半身が持ち上がります。","yonlendirme":"頭は床に、肩はやわらかく。"},"soylenecekler":["自分を抱きしめるように、膝を抱えましょう。","息を吸うと膝が離れ、吐くと近づきます。","よければ左右にゆっくりゆれて、腰を床でほぐしましょう。"],"eller":{"nereye":"生徒のすねの上、または仙骨が床に触れているところの近く。","nasil":"同意を得てから、すねにごく軽く重さを添えて、膝が胸に近づく動きに寄り添ってください。決して押さないでください。","ne_zaman_degil":"同意がない場合、妊娠中（お腹への圧迫）、膝の痛み、人工股関節がある場合は触れないでください。"},"kolay":"片脚のバージョンで行い、もう片方の脚は床で曲げるか伸ばしておきます。","zor":"頭を持ち上げて鼻を膝に近づけ、数呼吸とどまってからゆっくりゆるめます。","dikkat":"妊娠中は膝をお腹のスペースができるくらい広くひらき、圧迫をかけないでください。妊娠後期は仰向けの時間を短くします。膝に不調がある場合は手を膝の裏に置きます。人工股関節がある場合は、動かせる範囲について医師に相談するよう勧めてください。","s":126,"fig":true},{"n":115,"bolum":8,"ad":"屍のポーズ（シャヴァーサナ）","aile":"リストラティブ","seviye":"初級","yogunluk":[1,1,1],"calisan":["横隔膜","骨盤底筋群"],"dengeleyen":["腹横筋","多裂筋"],"uzayan":[],"ozet":"クラスの最後に体を完全にゆだねる、最終の休息のポーズです。筋肉の努力はなく、呼吸の自然な動きだけが続き、練習がここでまとまります。","asamalar":{"giris":"仰向けになり、脚を腰幅より少し広くひらいて、足が外へ倒れるのにまかせます。息を吐きながら腕を体から少し離し、手のひらを上に向けます。","kalis":"頭は中央に、あごは少し引き、体は左右対称に。呼吸をコントロールせずに見守り、5〜10分とどまります。","cikis":"深く息を吸い、手足の指を動かし、膝を曲げて右側へ転がります。数呼吸の後、手で床を押してゆっくり起き上がります。"},"hata":{"ne":"腰が反っているのに、不快感をがまんして動かずにいること。","neden":"腸腰筋が硬いと、伸ばした脚が骨盤を前へ引き、腰が床から浮きます。","yonlendirme":"膝の下にボルスターを、腰を床に落ち着けます。"},"soylenecekler":["体の重さを、すべて床にあずけましょう。","呼吸は自分のリズムで行き来させましょう。整えなくて大丈夫です。","寒ければ、ブランケットをかけましょう。"],"eller":{"nereye":"肩、または足首。事前に同意を得ている場合のみ。","nasil":"同意を得てから、ごく軽く安定したタッチで数呼吸そのままにしてください。急に触れたり、体を動かしたりするのは避けてください。","ne_zaman_degil":"事前に同意を得ていない場合は一切触れないでください。目を閉じている生徒を予告なしに驚かせないでください。妊娠後期の生徒や、トラウマへの配慮が必要とわかっている生徒には、触れる代わりに言葉で案内してください。"},"kolay":"膝の下にボルスター、頭の下にブランケット、目の上にアイピローを置きます。","zor":"時間を延ばし、足から頭へ向かって体を部分ごとに感じていきます。","dikkat":"妊娠後期は仰向けではなく横向きのシャヴァーサナを行ってください。腰に不快感がある場合は膝を曲げるか、サポートを置いてください。不安を感じる生徒は目を開けたままでもかまいません。","s":127,"fig":true},{"n":116,"bolum":8,"ad":"横向きのシャヴァーサナ（妊娠中）","aile":"リストラティブ","seviye":"初級","yogunluk":[1,1,1],"calisan":["横隔膜","骨盤底筋群"],"dengeleyen":["腹横筋","腹斜筋"],"uzayan":[],"ozet":"横向きに寝て、脚の間と頭の下にサポートを置いて行う最終の休息のポーズです。仰向けがつらい妊娠期や、腰が敏感な場合の代わりとなります。","asamalar":{"giris":"膝を曲げて横向きになり、頭の下にブランケット、脚の間にボルスターを置きます。息を吐きながらお尻と肩を床にあずけます。","kalis":"耳、肩、お尻を一直線にそろえ、上側の膝はボルスターの上に、腕は楽にします。必要ならお腹の下にもブランケットを置き、5〜10分とどまります。","cikis":"息を吸いながら上側の手で床を押し、頭を最後に起こしてゆっくり座ります。"},"hata":{"ne":"サポートなしで上側の脚を前に落とし、腰をねじってしまうこと。","neden":"上側の脚が支えられていないと骨盤が前に回り、腰と仙腸関節のあたりが引っぱられます。","yonlendirme":"膝は股関節の高さで、サポートの上に。"},"soylenecekler":["脚の間のサポートで、お尻をまっすぐに保ちましょう。","頭は肩と同じ高さに。ブランケットは必要なだけ高くしましょう。","楽に感じる側で休みましょう。"],"eller":{"nereye":"体には触れず、ボルスターとブランケットの配置だけを整えます。","nasil":"生徒の合図に合わせてサポートを調整してください。体を動かさないでください。","ne_zaman_degil":"妊娠中はこのポーズで触れる代わりに、言葉での案内とサポートの調整を行ってください。同意がない場合は一切触れないでください。"},"kolay":"背中の後ろに2つ目のボルスターを置いて体幹をあずけ、椅子や壁の支えを加えます。","zor":"サポートを減らし、時間を延ばして体の側面に広がる呼吸に意識を向けます。","dikkat":"妊娠中は一般的に左側が勧められますが、生徒の医師の指示が優先です。めまい、息苦しさ、不快感があれば姿勢を変え、医師に相談するよう勧めてください。","s":128,"fig":true},{"n":117,"bolum":8,"ad":"呼吸法のための座り方","aile":"座位","seviye":"初級","yogunluk":[1,2,3],"calisan":["横隔膜","脊柱起立筋","多裂筋"],"dengeleyen":["骨盤底筋群","腹横筋","僧帽筋中部・下部"],"uzayan":[],"ozet":"呼吸の練習のために、背骨が長く、胸が自由で、体が楽な状態をつくる座り方の準備です。サポートは人それぞれに選び、何分間も無理なくまっすぐ座れることを目指します。","asamalar":{"giris":"お尻が膝より高くなるよう、クッション、ブロック、または椅子に座ります。息を吸いながら坐骨を床に根づかせ、頭頂を伸ばします。","kalis":"骨盤はニュートラル、肋骨は自由に広がり、肩は下がり、あごは軽く引きます。手を太ももに置き、選んだ呼吸法で5〜15分とどまります。","cikis":"呼吸を自然なリズムに戻し、数呼吸目を閉じたまま過ごしてから、脚をゆっくり前へ伸ばします。"},"hata":{"ne":"胸を持ち上げようとして腰を反らせすぎること。","neden":"まっすぐ座ろうとする努力で脊柱起立筋が働きすぎ、肋骨が前へ開いて横隔膜の動きが制限されます。","yonlendirme":"肋骨はやわらかく、背骨は長く。"},"soylenecekler":["自分に合った高さを選びましょう。椅子も立派な呼吸法の座り方です。","息を吸うたびに、肋骨が横と後ろへ広がるのを感じましょう。","顔の筋肉、舌、あごの力を抜きましょう。"],"eller":{"nereye":"生徒の後ろで、肋骨の背面の横側に、手のひらを平らにして。","nasil":"同意を得てから、呼吸で肋骨が広がる場所を感じてもらうために手のひらを軽く添えてください。押さないでください。","ne_zaman_degil":"同意がない場合、生徒が目を閉じていて予告なしになる場合、または呼吸の練習中に不安のサインが見られる場合は触れないでください。"},"kolay":"背中を壁にあずけるか、椅子に座って足を床につけます。","zor":"より低いサポートの上か半蓮華座で、長い時間まっすぐ座ります。","dikkat":"呼吸法の途中でめまいが出たら自然な呼吸に戻ってください。妊娠中は息を止める呼吸法を避けます。心臓、血圧、呼吸器に不調がある場合、強度の高い呼吸法については医師に相談するよう勧めてください。","s":129,"fig":true},{"n":118,"bolum":8,"ad":"金剛座（ヴァジュラーサナ）","aile":"座位","seviye":"初級","yogunluk":[1,3,4],"calisan":["脊柱起立筋","多裂筋"],"dengeleyen":["腹横筋","骨盤底筋群"],"uzayan":["前脛骨筋","大腿四頭筋"],"ozet":"かかとの上に座る、シンプルなひざまずきの座り方です。瞑想、呼吸、ひざまずいて行う移行の出発点になります。","asamalar":{"giris":"膝をそろえてひざまずき、足の親指同士を触れ合わせ、かかとは少し離します。息を吐きながらお尻をかかとの上に下ろします。","kalis":"足の甲は床につけ、背骨はまっすぐ、手は太ももの上で楽にします。膝に圧迫がない状態で1〜5分とどまります。","cikis":"息を吸いながら手を床に置き、四つ這いになって足首を軽く動かします。"},"hata":{"ne":"足首の前側が張っているのに長くとどまり続けること。","neden":"前脛骨筋や足首の前側が硬いと、足の甲と膝が過度に引っぱられます。","yonlendirme":"足首の下に丸めたブランケットを。"},"soylenecekler":["かかとの上に落ち着いて、背骨を上へ伸ばしましょう。","膝に圧迫を感じたら、かかととお尻の間にブロックをはさみましょう。","手を太ももに置いて、呼吸を見守りましょう。"],"eller":{"nereye":"生徒の後ろで肩の上、またはサポートの配置。","nasil":"同意を得てから、肩を軽く後ろへ導くか、ブロックやブランケットを正しい位置に置いてください。下へ押さないでください。","ne_zaman_degil":"同意がない場合、または膝や足首の痛みを訴えている場合は触れないでください。"},"kolay":"お尻とかかとの間にブロック、足首の下に丸めたブランケット、膝の下に折りたたんだマットを置きます。","zor":"つま先を立てて座り、足の裏を伸ばして数呼吸とどまります。","dikkat":"膝や足首に不調がある場合はサポートを使うか椅子に座ってください。痛みが続く場合は理学療法士に相談するよう勧めてください。脚にしびれが出たらポーズから抜けます。","s":130,"fig":true},{"n":119,"bolum":8,"ad":"ボルスターを使ったリストラティブのねじり","aile":"リストラティブ","seviye":"初級","yogunluk":[1,2,3],"calisan":["横隔膜","腹斜筋"],"dengeleyen":["多裂筋","腹横筋"],"uzayan":["腹斜筋","腰方形筋","広背筋"],"ozet":"片側のお尻をボルスターの横に置き、体幹をねじってボルスターの上にあずける受け身のねじりです。体幹の側面と背面を、呼吸とともにやさしくひらきます。","asamalar":{"giris":"右のお尻をボルスターの短い辺に寄せて座り、膝は左側へたたみます。息を吸いながら背骨を伸ばし、息を吐きながら体幹をボルスターの方へねじってその上にあずけます。","kalis":"胸とお腹をボルスターにあずけ、腕は体の横の床に置き、顔は膝の側か反対側へ向けます。2〜4分とどまり、反対側も行います。","cikis":"息を吸いながら手で床を押して体幹を中央に戻し、脚を伸ばす前に数呼吸まっすぐ座ります。"},"hata":{"ne":"ねじりを深めようとして腕で体幹を引っぱること。","neden":"腕をてことして使うと、回旋が腰椎に集中してしまいます。","yonlendirme":"ボルスターに支えてもらい、ねじりは呼吸とともに。"},"soylenecekler":["まず伸びて、それからねじりましょう。ねじりながらも長さを保ちましょう。","顔は楽な方向へ向けましょう。","息を吐くたびに、体幹をもう少しボルスターにゆだねましょう。"],"eller":{"nereye":"背中の背面の横側、肩甲骨の下に、手のひらを平らにして。","nasil":"同意を得てから、手のひらを軽く添えて呼吸が背中に広がるのを感じてもらってください。ねじりを深めるために押さないでください。","ne_zaman_degil":"同意がない場合、腰や仙腸関節の痛み、椎間板の不調、妊娠がある場合は触れないでください。"},"kolay":"ボルスターをブロックで高くし、ねじりの角度を小さく保ちます。","zor":"ボルスターを低くし、顔を脚と反対の方向へ向けて首もねじりに加えます。","dikkat":"腰、椎間板、仙腸関節に不調がある場合は動きの幅を小さくし、理学療法士に相談するよう勧めてください。妊娠中はお腹を圧迫する閉じたねじりではなく、ひらいた軽いねじりを選んでください。","s":131,"fig":true},{"n":120,"bolum":8,"ad":"ボルスターを使ったヴィパリータ・カラニ","aile":"リストラティブ","seviye":"初級","yogunluk":[1,2,3],"calisan":["横隔膜","腹横筋"],"dengeleyen":["骨盤底筋群","脊柱起立筋"],"uzayan":["ハムストリングス","大胸筋・小胸筋"],"ozet":"壁の前に置いたボルスターで骨盤を高くし、脚を壁にあずけるサポート付きの穏やかな逆転のポーズです。壁に脚を上げるポーズの、より深いリストラティブ版です。","asamalar":{"giris":"ボルスターを壁からこぶし一つ分ほど離して置き、片側のお尻をボルスターに寄せて横向きに座ります。息を吐きながら仰向けになり、脚を壁に上げて骨盤をボルスターの上にのせます。","kalis":"仙骨はボルスターの上、肋骨の下側と肩は床に、胸は軽くひらきます。腕は横へひらき、5〜10分とどまります。","cikis":"息を吐きながら膝を曲げて足を壁に押し当て、お尻を持ち上げてボルスターを脇によけます。横向きになって数呼吸休みます。"},"hata":{"ne":"ボルスターを壁から離しすぎて、骨盤がサポートからずり落ちること。","neden":"お尻がボルスターに完全にのっていないと、腰が端で宙に浮いて引っぱられます。","yonlendirme":"仙骨はボルスターに、腰は自由に。"},"soylenecekler":["骨盤をボルスターにしっかりのせて、腰が宙に浮かないようにしましょう。","脚は壁にあずけます。膝は少し曲げてもかまいません。","目の上にアイピローをのせてもかまいません。"],"eller":{"nereye":"ボルスターの配置と壁との距離。必要な場合は足首の上。","nasil":"同意を得てから、生徒がお尻を持ち上げたときにボルスターをずらして正しい位置に置いてください。脚や骨盤を押さないでください。","ne_zaman_degil":"同意がない場合、妊娠後期、腰や首の痛みを訴えている場合、または脚に圧迫感やしびれを感じている場合は触れないでください。"},"kolay":"ボルスターの代わりに折りたたんだブランケットを使うか、ボルスターを壁から少し離します。","zor":"足裏を合わせて膝を横へひらき、合せきの脚でとどまります。","dikkat":"眼圧に関わる状態、コントロールされていない高血圧、逆流性食道炎、首の不調がある場合は、骨盤を高くせず平らな床で行う壁に脚を上げるポーズを選び、医師に相談するよう勧めてください。妊娠中にこの逆転の姿勢を行うかどうかは、生徒が医師と一緒に判断するよう伝えてください。不快感があれば横向きに切り替えます。","s":132,"fig":true}],"kaslar":[{"n":1,"ad":"僧帽筋上部","latince":"Musculus trapezius, pars descendens","bolge":"頸部 / 肩甲帯","baslangic":"後頭骨（上項線）および項靭帯。","yapisma":"鎖骨の外側3分の1。","islev":["肩甲骨を引き上げます（挙上）。","前鋸筋とともに肩甲骨を上方回旋させます。","頭を同じ側へ側屈させ、反対側へ回旋させます。"],"yogadaki_rol":"腕を頭上に上げると、肩甲骨の上方回旋を助けます。そのため、戦士のポーズⅠや下向きの犬のポーズで完全に働きを止めることは想定されていません。問題になるのは、肩が耳のほうへすくみ上がることです。頭を横に傾ける首のストレッチや、鷲のポーズの腕では伸ばされます。","aktive_et":"腕を上げながら、肩甲骨の外側の角が上と外へ回るのを感じてください。首は長く保ちます。","sik_hata":"腕を上げたときに無意識に肩を耳まですくめ、首を縮めてしまうこと。","asanalar":[3,11,14,15,100],"figur_en":"Posterior view of the neck and upper back; highlight in red the upper (descending) fibres of trapezius from the occiput to the lateral clavicle, rest of the trapezius in light grey.","s":134},{"n":2,"ad":"僧帽筋中部・下部","latince":"Musculus trapezius, pars transversa et pars ascendens","bolge":"背部 / 肩甲帯","baslangic":"第7頸椎〜第12胸椎の棘突起。","yapisma":"肩峰および肩甲棘。","islev":["中部線維は肩甲骨を脊柱に近づけます（内転）。","下部線維は肩甲骨を引き下げます（下制）。","下部線維は肩甲骨の上方回旋を助けます。"],"yogadaki_rol":"後屈で胸がひらき、肩甲骨が背中に落ち着くのを支えます。バッタのポーズ、コブラのポーズ、逆プランクで活発に働き、鷲のポーズの腕や背中を丸める前屈では伸ばされます。","aktive_et":"肩甲骨を後ろのポケットのほうへすべらせてください。胸は自然と前にひらきます。","sik_hata":"肩甲骨を寄せすぎて背中の中央を固めてしまうこと。呼吸が胸郭に入らなくなります。","asanalar":[49,51,22,25,62,92],"figur_en":"Posterior view of the upper and mid back; highlight in red the middle (transverse) and lower (ascending) fibres of trapezius, upper fibres in light grey.","s":135},{"n":3,"ad":"菱形筋","latince":"Musculus rhomboideus major et minor","bolge":"背部 / 肩甲帯","baslangic":"第7頸椎〜第5胸椎の棘突起。","yapisma":"肩甲骨の内側縁。","islev":["肩甲骨を脊柱に近づけます（内転）。","肩甲骨を下方回旋させます。","肩甲骨を胸郭に固定するのを助けます。"],"yogadaki_rol":"胸がひらき、腕を後ろへ伸ばすポーズで働きます。バッタのポーズ、逆テーブルのポーズ、橋のポーズで肩を体の下へ寄せるときなどです。鷲のポーズの腕、糸通しのポーズ、キャットで背中を丸めるときには伸ばされます。","aktive_et":"背中で両手を組み、肩甲骨の内側縁をやさしく近づけてください。","sik_hata":"チャトランガやプランクで肩甲骨を寄せきってしまい、胸郭が落ち込むのを許すこと。","asanalar":[51,52,53,61,62,24],"figur_en":"Posterior view of the upper back with trapezius removed; highlight in red rhomboid major and minor between the spine and the medial border of the scapula.","s":136},{"n":4,"ad":"広背筋","latince":"Musculus latissimus dorsi","bolge":"背部 / 体幹","baslangic":"第7〜第12胸椎の棘突起、胸腰筋膜、腸骨稜、下位肋骨。","yapisma":"上腕骨の結節間溝。","islev":["肩を伸展させます（腕を下と後ろへ引きます）。","腕を体幹に近づけます（内転）。","腕を内旋させます。","腕が固定されているとき、体幹を引き上げるのを助けます。"],"yogadaki_rol":"腕が頭上にあるときに最も伸ばされます。この筋が硬いと、下向きの犬のポーズや車輪のポーズで背中が丸まったり、腰が反りすぎたりすることがあります。チャトランガや前腕プランクでは、体幹を支えるために働きます。","aktive_et":"プランクで、手のひらで床を足のほうへ引き寄せるように押し、わきの下をアクティブに保ってください。","sik_hata":"腕を上げたときに肋骨を前へ突き出し、腰を反らせて広背筋の硬さを補ってしまうこと。","asanalar":[14,39,54,94,15],"figur_en":"Lateral-posterior view of the trunk with arm raised overhead; highlight in red latissimus dorsi from the lower spine and iliac crest to the humerus.","s":137},{"n":5,"ad":"前鋸筋","latince":"Musculus serratus anterior","bolge":"肩甲帯 / 体幹","baslangic":"第1〜第9肋骨の外側面。","yapisma":"肩甲骨内側縁の前面。","islev":["肩甲骨を前方・外側へ動かします（外転）。","肩甲骨を上方回旋させます。","肩甲骨を胸郭に固定します。"],"yogadaki_rol":"手で体を支えるすべてのポーズの土台となる筋です。プランク、下向きの犬のポーズ、サイドプランク、カラスのポーズなどで働きます。弱いままだと肩甲骨が背中から浮き、胸郭が腕の間に沈み込みます。","aktive_et":"両手で床を押し、肩甲骨が胸郭を包み込むのを感じてください。","sik_hata":"プランクで胸が両手の間に落ち、肩甲骨が翼のように浮き上がること。","asanalar":[93,14,28,30,92,100],"figur_en":"Lateral view of the thorax with the arm raised forward; highlight in red the serrated slips of serratus anterior along the ribs to the scapula.","s":138},{"n":6,"ad":"脊柱起立筋","latince":"Musculus erector spinae (iliocostalis, longissimus, spinalis)","bolge":"背部","baslangic":"仙骨、腸骨稜、腰椎および下位胸椎の棘突起。","yapisma":"肋骨、椎骨の横突起と棘突起、後頭骨。","islev":["脊柱を伸展させます。","片側だけが働くと、体幹を側屈させます。","前屈で体幹が下りる動きを遠心性にコントロールします。"],"yogadaki_rol":"後屈や、背中を長く保つ前屈で脊柱を支えます。コブラのポーズ、バッタのポーズ、半分の前屈、戦士のポーズⅢなどです。座位前屈（パスチモッターナーサナ）やチャイルドポーズでは伸ばされます。","aktive_et":"胸骨を前へ伸ばし、頭頂と尾骨の間に距離をつくってください。","sik_hata":"前屈でハムストリングスの硬さを背中を丸めて補い、この筋を必要以上に引き伸ばすこと。","asanalar":[49,51,37,22,52,2],"figur_en":"Posterior view of the back; highlight in red the erector spinae columns on both sides of the spine from the sacrum to the neck.","s":139},{"n":7,"ad":"多裂筋","latince":"Musculi multifidi","bolge":"背部","baslangic":"仙骨、上後腸骨棘、腰椎の乳頭突起、胸椎の横突起。","yapisma":"2〜4分節上の椎骨の棘突起。","islev":["脊柱を分節ごとに安定させます。","脊柱にわずかな伸展を与えます。","回旋をコントロールします。"],"yogadaki_rol":"表層の大きな筋よりも先に働く、深層の安定筋です。山のポーズや四つ這いで、ニュートラルな脊柱を保ちます。ねじりでは、椎骨が一つずつ回旋し、コントロールしながら戻るのを助けます。","aktive_et":"四つ這いで片腕を上げながら、骨盤と腰が動かないことに意識を向けてください。","sik_hata":"ねじりで腰の一か所だけを使って無理に回すこと。回旋が脊柱全体に分散しません。","asanalar":[1,47,48,63,74,22],"figur_en":"Posterior view of the lumbar and thoracic spine with superficial muscles removed; highlight in red the short multifidus fascicles spanning 2-4 vertebrae.","s":140},{"n":8,"ad":"腰方形筋","latince":"Musculus quadratus lumborum","bolge":"体幹 / 腰部","baslangic":"腸骨稜の後部および腸腰靭帯。","yapisma":"第12肋骨および第1〜第4腰椎の横突起。","islev":["体幹を側屈させます。","骨盤の片側を引き上げます。","息を吸うときに第12肋骨を安定させます。","両側が働くと、腰を伸展させます。"],"yogadaki_rol":"側屈や三角のポーズでは、上側で伸ばされ、下側で働きます。サイドプランクでは骨盤を高く保つのを助けます。門のポーズは、腰の側面を伸ばすのに適したポーズです。","aktive_et":"サイドプランクで下側の腰をもう少し天井のほうへ持ち上げ、腰の側面が働くのを感じてください。","sik_hata":"三角のポーズや側屈で、下側の腰の側面をつぶしてしまうこと。伸びるかわりに圧迫になります。","asanalar":[6,15,28,45,88,23],"figur_en":"Posterior-lateral view of the lumbar region; highlight in red quadratus lumborum between the iliac crest, the 12th rib and the lumbar transverse processes.","s":141},{"n":9,"ad":"回旋筋腱板（ローテーターカフ）","latince":"Musculi supraspinatus, infraspinatus, teres minor et subscapularis","bolge":"肩甲帯","baslangic":"肩甲骨の棘上窩、棘下窩、肩甲下窩および外側縁。","yapisma":"上腕骨の大結節と小結節。","islev":["上腕骨頭を関節窩の中心に保ちます。","腕を外旋させます（棘下筋、小円筋）。","腕を内旋させます（肩甲下筋）。","外転の最初の動きを始めます（棘上筋）。"],"yogadaki_rol":"腕に体重がかかるとき、肩関節を中心に保ちます。チャトランガ、プランク、イルカのポーズ、壁を使った倒立の準備などです。牛の顔のポーズの腕では、内旋筋と外旋筋が左右それぞれで伸ばされます。","aktive_et":"下向きの犬のポーズで、上腕をわずかに外へ、前腕をわずかに内へ回してください。","sik_hata":"チャトランガで肩をひじより下へ落とすこと。上腕骨頭が前へずれます。","asanalar":[94,93,92,100,82,28],"figur_en":"Posterior and anterior views of the scapula and humeral head; highlight in red supraspinatus, infraspinatus, teres minor and subscapularis.","s":142},{"n":10,"ad":"三角筋","latince":"Musculus deltoideus","bolge":"肩甲帯 / 腕","baslangic":"鎖骨の外側3分の1、肩峰、肩甲棘。","yapisma":"上腕骨の三角筋粗面。","islev":["腕を横に上げます（外転）。","前部線維は腕を前に上げます（屈曲）。","後部線維は腕を後ろへ動かします（伸展）。"],"yogadaki_rol":"腕を床と平行に保つときに負荷を支えます。戦士のポーズⅡや体側を伸ばすポーズなどです。サイドプランクやイルカのポーズでは肩を包むように働き、逆テーブルのポーズでは前部線維が伸ばされます。","aktive_et":"戦士のポーズⅡで腕を指先まで伸ばし、肩先は下げたままにしてください。","sik_hata":"腕が床と平行なときに肩をすくめ、負担を首に集めてしまうこと。","asanalar":[4,7,28,92,100,61],"figur_en":"Lateral view of the shoulder; highlight in red the anterior, middle and posterior fibres of deltoid.","s":143},{"n":11,"ad":"大胸筋・小胸筋","latince":"Musculus pectoralis major et minor","bolge":"胸部 / 肩甲帯","baslangic":"大胸筋：鎖骨の内側半分、胸骨、第1〜第6肋軟骨。小胸筋：第3〜第5肋骨。","yapisma":"大胸筋：上腕骨の結節間溝の外側唇。小胸筋：肩甲骨の烏口突起。","islev":["腕を体幹に近づけ、内旋させます（大胸筋）。","腕を前に上げます（大胸筋の鎖骨部線維）。","肩甲骨を前下方へ引きます（小胸筋）。"],"yogadaki_rol":"チャトランガやプランクで体幹を支えるときに働きます。後屈、魚のポーズ、逆プランク、ボルスターを使って胸をひらくポーズでは伸ばされます。この筋が硬いと、肩が前へ巻き込む姿勢として表れます。","aktive_et":"チャトランガでひじを肋骨の近くに保ち、胸を前へ伸ばしてください。","sik_hata":"後屈で胸ではなく肩を前へ押し出し、肩の前面に負担を集めること。","asanalar":[94,57,55,62,110,54],"figur_en":"Anterior view of the chest; highlight in red pectoralis major, show pectoralis minor beneath it in a darker red with major partially transparent.","s":144},{"n":12,"ad":"上腕三頭筋","latince":"Musculus triceps brachii","bolge":"腕","baslangic":"長頭：肩甲骨の関節下結節。外側頭・内側頭：上腕骨の後面。","yapisma":"尺骨の肘頭。","islev":["ひじを伸ばします（伸展）。","長頭は肩の伸展を助けます。","負荷がかかったときに、ひじ関節を安定させます。"],"yogadaki_rol":"チャトランガで下りる動きをコントロールし、車輪のポーズや上向きの犬のポーズで腕をまっすぐにします。アームバランスやサポート付き肩立ちでは体を支えます。頭上でひじを曲げると（牛の顔のポーズの腕）、長頭が伸ばされます。","aktive_et":"チャトランガでひじを後ろへ向け、下りる動きをゆっくりにしてください。","sik_hata":"ひじを外へ開いてしまい、チャトランガで肩の前面に負担をかけること。","asanalar":[94,54,50,30,96,104],"figur_en":"Posterior view of the upper arm; highlight in red the long, lateral and medial heads of triceps brachii.","s":145},{"n":13,"ad":"腹直筋","latince":"Musculus rectus abdominis","bolge":"体幹 / 腹部","baslangic":"恥骨結合および恥骨稜。","yapisma":"第5〜第7肋軟骨および剣状突起。","islev":["体幹を前へ曲げます（屈曲）。","骨盤の後傾を助けます。","腹腔内圧を高めます。"],"yogadaki_rol":"舟のポーズ、カラスのポーズ、前腕プランクで体幹をまとめます。ラクダのポーズ、車輪のポーズ、コブラのポーズなどの後屈では伸ばされます。この伸びをコントロールすることで、腰への負担が分散されます。","aktive_et":"息を吐きながら、下部肋骨を骨盤のほうへやさしく近づけてください。","sik_hata":"舟のポーズでお腹を外へ押し出して力むこと。腰が丸まり、負担が股関節屈筋へ移ります。","asanalar":[29,30,93,95,55,96],"figur_en":"Anterior view of the abdomen; highlight in red rectus abdominis from the pubis to the lower ribs, showing tendinous intersections.","s":146},{"n":14,"ad":"腹斜筋","latince":"Musculus obliquus externus et internus abdominis","bolge":"体幹 / 腹部","baslangic":"外腹斜筋：第5〜第12肋骨の外側面。内腹斜筋：胸腰筋膜、腸骨稜、鼠径靭帯。","yapisma":"外腹斜筋：腸骨稜、白線、鼠径靭帯。内腹斜筋：第10〜第12肋骨および白線。","islev":["体幹を回旋させます。","体幹を側屈させます。","体幹の屈曲を助けます。","腹腔内圧を支えます。"],"yogadaki_rol":"すべてのねじりの原動力です。座位のねじり、ねじった体側を伸ばすポーズ、ねじった三角のポーズなどで働きます。サイドプランクでは体幹を側面から支え、三角のポーズでは上側で伸ばされます。","aktive_et":"ねじりでは、まず息を吸って伸び、吐きながらおへそを回旋の方向へ向けてください。","sik_hata":"腕をてこにして無理にねじること。回旋が体幹からではなく肩から生まれてしまいます。","asanalar":[63,68,9,6,28,101],"figur_en":"Anterolateral view of the trunk; highlight in red external oblique, show internal oblique underneath in darker red with crossing fibre directions.","s":147},{"n":15,"ad":"腹横筋","latince":"Musculus transversus abdominis","bolge":"体幹 / 腹部","baslangic":"第7〜第12肋軟骨の内面、胸腰筋膜、腸骨稜、鼠径靭帯。","yapisma":"白線および恥骨。","islev":["腹壁を内側へ引き締めます。","腹腔内圧を調整します。","息を吐くのを助けます。","腰椎・骨盤部を安定させます。"],"yogadaki_rol":"コルセットのように体幹を包み、プランク、舟のポーズ、カラスのポーズなどで脊柱を守ります。キャット＆カウでは呼吸に合わせてやさしく働き、深いリストラティブのポーズではゆるむにまかせます。","aktive_et":"息を吐きながら、ベルトを締めるように、骨盤の左右の骨の間で下腹部をやさしく内側へ引き入れてください。","sik_hata":"お腹を常に強く引き込み、呼吸を制限してしまうこと。","asanalar":[93,29,30,22,95,47],"figur_en":"Anterior view of the abdomen with obliques removed; highlight in red transversus abdominis with its horizontal fibres wrapping around the trunk.","s":148},{"n":16,"ad":"横隔膜","latince":"Diaphragma","bolge":"体幹 / 胸郭","baslangic":"胸骨部：剣状突起の後面。肋骨部：第7〜第12肋骨の内面。腰椎部：第1〜第3腰椎（横隔膜脚）。","yapisma":"腱中心。","islev":["主要な呼吸筋で、息を吸うときに下がります。","胸腔を広げます。","骨盤底筋群や腹筋とともに、腹腔内圧を調整します。"],"yogadaki_rol":"すべてのポーズのリズムを決めます。チャイルドポーズでは呼吸が背中側へ、仰向けの合せきではお腹の前側へ広がります。呼吸法のための座り方やシャヴァーサナでは、呼吸の流れを観察するための中心的なフォーカスになります。","aktive_et":"片手を下部肋骨に置き、息を吸うときに肋骨が横へ広がるのを感じてください。","sik_hata":"息を吸うために肩や首の筋肉を持ち上げること。呼吸が胸の上部にとどまります。","asanalar":[117,115,111,40,79,105],"figur_en":"Anterior cut-away view of the thorax and abdomen; highlight in red the dome of the diaphragm with its central tendon and crura.","s":149},{"n":17,"ad":"骨盤底筋群","latince":"Diaphragma pelvis (musculus levator ani et musculus coccygeus)","bolge":"骨盤","baslangic":"恥骨の後面、閉鎖筋膜の腱弓、坐骨棘。","yapisma":"尾骨、肛門尾骨靭帯、会陰体。","islev":["骨盤内の臓器を支えます。","横隔膜と協調して、呼吸のリズムに参加します。","腹腔内圧を下から受け止めます。"],"yogadaki_rol":"呼吸に合わせて、わずかに上がったり下がったりします。息を吐くときは軽く引き上がる感覚、吸うときはゆるむ感覚です。花輪のポーズや合せきのポーズではゆるむための余地を、橋のポーズや山のポーズでは軽く支えるための余地をつくります。","aktive_et":"息を吐きながら、左右の坐骨がほんのわずかに近づくのをイメージし、吸うときに手放してください。","sik_hata":"ポーズのあいだずっと骨盤底を締め続け、ゆるめる段階を飛ばしてしまうこと。","asanalar":[80,78,117,53,1,79],"figur_en":"View from above into the pelvis (superior view); highlight in red levator ani and coccygeus forming the pelvic floor.","s":150},{"n":18,"ad":"腸腰筋","latince":"Musculus iliopsoas (psoas major et iliacus)","bolge":"股関節 / 体幹","baslangic":"大腰筋：第12胸椎〜第4腰椎の椎体、横突起、椎間板。腸骨筋：腸骨窩。","yapisma":"大腿骨の小転子。","islev":["股関節を曲げます（屈曲）。","腰椎を安定させます。","脚が固定されているとき、体幹を前へ倒します。"],"yogadaki_rol":"舟のポーズや、立位で足の親指をつかむポーズで脚を持ち上げます。ローランジ、戦士のポーズⅠの後ろ脚、後屈を加えたローランジでは伸ばされます。この筋が硬いと、腰の反りすぎとして表れます。","aktive_et":"ローランジで尾骨をやさしく下へ向け、後ろ脚側の股関節の前面がひらくのを感じてください。","sik_hata":"ランジで骨盤を前へ倒し、伸びを腰へ逃がしてしまうこと。","asanalar":[29,12,3,86,26,60],"figur_en":"Anterior view of the lumbar spine and pelvis; highlight in red psoas major and iliacus joining to the lesser trochanter of the femur.","s":151},{"n":19,"ad":"大殿筋","latince":"Musculus gluteus maximus","bolge":"殿部","baslangic":"腸骨の後面、仙骨、尾骨、仙結節靭帯。","yapisma":"腸脛靭帯および大腿骨の殿筋粗面。","islev":["股関節を伸展させます。","股関節を外旋させます。","しゃがんだ姿勢から立ち上がるときや、階段を上るときに力を生みます。","骨盤を安定させます。"],"yogadaki_rol":"橋のポーズ、バッタのポーズ、戦士のポーズⅢで後ろ脚と骨盤を支え、椅子のポーズでは立ち上がる動きをコントロールします。鳩のポーズ、仰向けの鳩のポーズ、ハッピーベイビーでは伸ばされます。","aktive_et":"橋のポーズで足をマットに押しつけ、かかとを肩のほうへ引き寄せるようにしてください。","sik_hata":"後屈でお尻を強く締めすぎて、腰への負担を増やすこと。","asanalar":[53,22,2,51,49,76],"figur_en":"Posterior view of the hip; highlight in red gluteus maximus from the sacrum and ilium to the iliotibial band and femur.","s":152},{"n":20,"ad":"中殿筋・小殿筋","latince":"Musculus gluteus medius et minimus","bolge":"殿部","baslangic":"腸骨の外面（前殿筋線と後殿筋線の間）。","yapisma":"大腿骨の大転子。","islev":["股関節を横へひらきます（外転）。","片脚立ちのとき、骨盤を水平に保ちます。","前部線維は内旋を、後部線維は外旋を助けます。"],"yogadaki_rol":"すべてのバランスポーズを静かに支える筋です。木のポーズ、半月のポーズ、戦士のポーズⅢ、鷲のポーズなどで働きます。戦士のポーズⅡでは前ひざが内側へ入らないよう助け、サイドプランクでは下側の股関節を支えます。","aktive_et":"木のポーズで軸脚側のお尻をやさしく内側へ引き寄せ、骨盤を左右同じ高さに保ってください。","sik_hata":"片脚立ちで、軸脚側の腰を横へ流してしまうこと。","asanalar":[21,23,4,22,24,28],"figur_en":"Lateral view of the hip with gluteus maximus made transparent; highlight in red gluteus medius and, beneath it, gluteus minimus to the greater trochanter.","s":153},{"n":21,"ad":"梨状筋","latince":"Musculus piriformis","bolge":"殿部","baslangic":"仙骨の前面（第2〜第4仙椎）。","yapisma":"大腿骨大転子の上縁。","islev":["股関節が伸びているときは、外旋させます。","股関節を90°曲げているときは、外転を助けます。","仙腸関節まわりの安定を支えます。"],"yogadaki_rol":"深層外旋筋の中で最も代表的な筋です。鳩のポーズ、仰向けの鳩のポーズ、薪のポーズ、牛の顔のポーズで伸ばされます。ストレッチは軽く始め、ひざではなく股関節がひらいているかを観察することが大切です。","aktive_et":"仰向けの鳩のポーズで足首を曲げてかかとを押し出し、ひざを胸からやさしく遠ざけてください。","sik_hata":"鳩のポーズで、股関節がひらかないところをひざで無理に補うこと。負担がひざ関節にかかります。","asanalar":[75,76,81,82,85],"figur_en":"Posterior view of the deep hip with gluteus maximus removed; highlight in red piriformis from the anterior sacrum to the greater trochanter.","s":154},{"n":22,"ad":"大腿四頭筋","latince":"Musculus quadriceps femoris (rectus femoris, vastus lateralis, vastus medialis, vastus intermedius)","bolge":"脚 / 大腿","baslangic":"大腿直筋：下前腸骨棘。広筋群：大腿骨の前面と側面。","yapisma":"膝蓋骨を経て、膝蓋靭帯により脛骨粗面。","islev":["ひざを伸ばします（伸展）。","大腿直筋は股関節の屈曲を助けます。","膝蓋骨の動きを導き、ひざを安定させます。"],"yogadaki_rol":"椅子のポーズ、戦士のポーズⅡ、女神のポーズで曲げたひざを支えます。大腿四頭筋を伸ばすローランジや英雄座では伸ばされ、踊り子のポーズでは後ろ脚の大腿直筋が伸ばされます。","aktive_et":"立位前屈で、ひざをロックせずに膝蓋骨をやさしく引き上げてください。","sik_hata":"脚をまっすぐにして立つポーズで、ひざを後ろへロックすること。","asanalar":[2,4,3,13,86,106],"figur_en":"Anterior view of the thigh; highlight in red rectus femoris and the three vasti converging into the patellar tendon.","s":155},{"n":23,"ad":"ハムストリングス","latince":"Musculus biceps femoris, semitendinosus et semimembranosus","bolge":"脚 / 大腿","baslangic":"坐骨結節（坐骨）。大腿二頭筋短頭は大腿骨の粗線。","yapisma":"大腿二頭筋：腓骨頭。半腱様筋・半膜様筋：脛骨の内側面。","islev":["ひざを曲げます。","股関節を伸展させます。","前屈で、骨盤が前へ傾く動きをコントロールします。"],"yogadaki_rol":"すべての前屈で伸ばされます。立位前屈、座位前屈（パスチモッターナーサナ）、ピラミッドのポーズ、ハーフスプリットなどです。橋のポーズや戦士のポーズⅢでは働いて骨盤を支えます。この筋の硬さは、多くの場合、背中が丸まることで表れます。","aktive_et":"前屈で坐骨を後ろと上へ伸ばしてください。必要ならひざを曲げます。","sik_hata":"手を床や足に届かせるために、背中を丸めること。","asanalar":[20,33,8,42,41,53],"figur_en":"Posterior view of the thigh; highlight in red biceps femoris, semitendinosus and semimembranosus from the sitting bone to the lower leg.","s":156},{"n":24,"ad":"内転筋群","latince":"Musculi adductor longus, brevis et magnus, gracilis, pectineus","bolge":"脚 / 大腿内側","baslangic":"恥骨体と恥骨枝、坐骨枝、坐骨結節。","yapisma":"大腿骨の粗線と内転筋結節。薄筋は脛骨の内側面。","islev":["脚を正中線に近づけます（内転）。","大内転筋は股関節の伸展を助けます。","立位やバランスのポーズで骨盤を安定させます。"],"yogadaki_rol":"木のポーズの軸脚や、鷲のポーズで脚を巻きつける動きを安定させます。女神のポーズ、開脚座位前屈、合せきのポーズ、花輪のポーズでは伸ばされます。","aktive_et":"木のポーズで、足を脚に、脚を足に、同じ強さで押し合ってください。","sik_hata":"合せきのポーズで、ひざを手で床へ押しつけること。","asanalar":[21,13,35,78,80,87],"figur_en":"Anterior-medial view of the thigh; highlight in red adductor longus, brevis, magnus, gracilis and pectineus.","s":157},{"n":25,"ad":"大腿筋膜張筋","latince":"Musculus tensor fasciae latae","bolge":"股関節 / 大腿外側","baslangic":"上前腸骨棘および腸骨稜の前部。","yapisma":"腸脛靭帯を介して脛骨の外側顆。","islev":["股関節を曲げます。","股関節を横へひらきます。","股関節を内旋させます。","ひざの外側の安定を助けます。"],"yogadaki_rol":"片脚のバランスポーズで、中殿筋とともに骨盤を支えます。半月のポーズや木のポーズなどです。鷲のポーズや、仰向けで足の親指をつかむポーズ（横）の交差させるバリエーションでは伸ばされます。","aktive_et":"半月のポーズで軸脚側の股関節をやさしく後ろへ引き、股関節の前面を詰まらせないようにしてください。","sik_hata":"バランスポーズで負担をすべて股関節の外側前面にかけ、中殿筋を働かせないこと。","asanalar":[23,21,24,7,112],"figur_en":"Anterolateral view of the hip and thigh; highlight in red tensor fasciae latae and show the iliotibial band continuing down the lateral thigh in a lighter red.","s":158},{"n":26,"ad":"腓腹筋・ヒラメ筋","latince":"Musculus gastrocnemius et musculus soleus (triceps surae)","bolge":"下腿","baslangic":"腓腹筋：大腿骨の内側顆と外側顆。ヒラメ筋：脛骨と腓骨の後面上部。","yapisma":"アキレス腱を介して踵骨。","islev":["足首を底屈させます（つま先立ち）。","腓腹筋はひざの屈曲を助けます。","立っているときの前後の揺れをコントロールします。"],"yogadaki_rol":"下向きの犬のポーズやピラミッドのポーズで伸ばされます。ひざを伸ばしているときは腓腹筋が、ひざを曲げているときはヒラメ筋がより伸びます。つま先立ちの椅子のポーズで働き、花輪のポーズではかかとが床に下りるかどうかを左右します。","aktive_et":"つま先立ちの椅子のポーズで左右のかかとを同じ高さに保ち、足首を外側へ倒さないでください。","sik_hata":"下向きの犬のポーズで、かかとを床につけようとして背中を丸めること。","asanalar":[14,31,8,20,80],"figur_en":"Posterior view of the lower leg; highlight in red the two heads of gastrocnemius and, deeper, soleus joining into the Achilles tendon.","s":159},{"n":27,"ad":"前脛骨筋","latince":"Musculus tibialis anterior","bolge":"下腿","baslangic":"脛骨の外側顆と外側面の上半分、骨間膜。","yapisma":"内側楔状骨および第1中足骨底。","islev":["足首を背屈させます。","足を内側へ返します（内反）。","足の内側のアーチを支えます。"],"yogadaki_rol":"木のポーズなど片脚のポーズで、足首の細かな調整を行います。椅子のポーズや花輪のポーズでは、ひざが前へ進む動きに伴って働きます。金剛座や英雄座で足の甲を床につけると伸ばされます。","aktive_et":"木のポーズで軸足の内側のアーチをやさしく引き上げ、親指の付け根は床につけたままにしてください。","sik_hata":"片脚立ちで足のアーチをつぶすこと。ひざが内側へ入ります。","asanalar":[21,2,80,106,118],"figur_en":"Anterolateral view of the lower leg and foot; highlight in red tibialis anterior from the tibia to the medial foot.","s":160},{"n":28,"ad":"胸鎖乳突筋","latince":"Musculus sternocleidomastoideus","bolge":"頸部","baslangic":"胸骨柄および鎖骨の内側3分の1。","yapisma":"側頭骨の乳様突起および上項線。","islev":["片側：頭を同じ側へ側屈させ、反対側へ回旋させます。","両側：首を前へ曲げます。","努力呼吸のときに、呼吸補助筋として働きます。"],"yogadaki_rol":"舟のポーズや仰向けの腹筋エクササイズで頭を支えます。魚のポーズやラクダのポーズで頭を後ろへ預けると伸ばされ、仰向けのねじりで頭を反対側へ向けるとやさしくストレッチされます。","aktive_et":"舟のポーズであごを胸のほうへ軽く近づけ、首の前側をやわらかく保ってください。","sik_hata":"ラクダのポーズで頭を急に後ろへ倒すこと。首の前側がコントロールされないまま伸ばされます。","asanalar":[29,57,55,66,96],"figur_en":"Anterolateral view of the neck with the head slightly rotated; highlight in red sternocleidomastoid from the sternum and clavicle to the mastoid process.","s":161}],"dersler":[{"n":1,"baslik":"基礎：初心者のためのアライメント","seviye":"初級","s":170,"asanalar":[111,47,40,14,1,2,12,4,6,21,107,34,53,66,114,115,105]},{"n":2,"baslik":"立位のダイナミックフロー","seviye":"中級","s":172,"asanalar":[105,47,14,18,19,3,4,5,7,11,16,22,23,10,33,66,115]},{"n":3,"baslik":"股関節とハムストリングス","seviye":"初級","s":174,"asanalar":[111,47,114,41,14,12,42,8,80,75,76,78,35,34,84,115]},{"n":4,"baslik":"段階的に学ぶ後屈","seviye":"中級","s":176,"asanalar":[105,47,39,14,12,86,48,49,51,53,56,58,55,40,73,114,115]},{"n":5,"baslik":"ねじりと背骨","seviye":"初級","s":178,"asanalar":[105,47,74,69,1,15,72,16,88,64,63,45,66,114,115]},{"n":6,"baslik":"スローでリストラティブな練習","seviye":"全レベル","s":180,"asanalar":[111,47,114,73,109,79,110,119,113,120,115,105]}],"bolumler":{"1":"立位のポーズ","2":"バランスのポーズ","3":"前屈","4":"後屈","5":"ねじり","6":"股関節をひらくポーズ","7":"逆転とアームバランス","8":"座位・仰向け・リストラティブのポーズ"},"pdf":"Yoga-Anatomy-Asana-Atlas-JP.pdf"};